import re

class LutBuilder:

    def __init__(self, patterns: list[str] | None=None, op_name: str | None=None) -> None:
        if patterns is not None:
            self.patterns = patterns
        else:
            self.patterns = []
        self.lut: bytearray | None = None
        if op_name is not None:
            known_patterns = {'corner': ['1:(... ... ...)->0', '4:(00. 01. ...)->1'], 'dilation4': ['4:(... .0. .1.)->1'], 'dilation8': ['4:(... .0. .1.)->1', '4:(... .0. ..1)->1'], 'erosion4': ['4:(... .1. .0.)->0'], 'erosion8': ['4:(... .1. .0.)->0', '4:(... .1. ..0)->0'], 'edge': ['1:(... ... ...)->0', '4:(.0. .1. ...)->1', '4:(01. .1. ...)->1']}
            if op_name not in known_patterns:
                msg = 'Unknown pattern ' + op_name + '!'
                raise Exception(msg)
            self.patterns = known_patterns[op_name]

    def build_default_lut(self) -> None:
        symbols = [0, 1]
        m = 1 << 4
        self.lut = bytearray((symbols[i & m > 0] for i in range(LUT_SIZE)))

    def _string_permute(self, pattern: str, permutation: list[int]) -> str:
        assert len(permutation) == 9
        return ''.join((pattern[p] for p in permutation))

    def _pattern_permute(self, basic_pattern: str, options: str, basic_result: int) -> list[tuple[str, int]]:
        patterns = [(basic_pattern, basic_result)]
        if '4' in options:
            res = patterns[-1][1]
            for i in range(4):
                patterns.append((self._string_permute(patterns[-1][0], ROTATION_MATRIX), res))
        if 'M' in options:
            n = len(patterns)
            for pattern, res in patterns[:n]:
                patterns.append((self._string_permute(pattern, MIRROR_MATRIX), res))
        if 'N' in options:
            n = len(patterns)
            for pattern, res in patterns[:n]:
                pattern = pattern.replace('0', 'Z').replace('1', '0').replace('Z', '1')
                res = 1 - int(res)
                patterns.append((pattern, res))
        return patterns

    def build_lut(self) -> bytearray:
        self.build_default_lut()
        assert self.lut is not None
        patterns = []
        for p in self.patterns:
            m = re.search('(\\w*):?\\s*\\((.+?)\\)\\s*->\\s*(\\d)', p.replace('\n', ''))
            if not m:
                msg = 'Syntax error in pattern "' + p + '"'
                raise Exception(msg)
            options = m.group(1)
            pattern = m.group(2)
            result = int(m.group(3))
            pattern = pattern.replace(' ', '').replace('\n', '')
            patterns += self._pattern_permute(pattern, options, result)
        compiled_patterns = []
        for pattern in patterns:
            p = pattern[0].replace('.', 'X').replace('X', '[01]')
            compiled_patterns.append((re.compile(p), pattern[1]))
        for i in range(LUT_SIZE):
            bitpattern = bin(i)[2:]
            bitpattern = ('0' * (9 - len(bitpattern)) + bitpattern)[::-1]
            for pattern, r in compiled_patterns:
                if pattern.match(bitpattern):
                    self.lut[i] = [0, 1][r]
        return self.lut

Pillow.src.PIL.ImageMorph._pattern_permute

def _pattern_permute(
    self, basic_pattern: str, options: str, basic_result: int
) -> list[tuple[str, int]]:
    """pattern_permute takes a basic pattern and its result and clones
    the pattern according to the modifications described in the $options
    parameter. It returns a list of all cloned patterns."""
    patterns = [(basic_pattern, basic_result)]

    # rotations
    if "4" in options:
        res = patterns[-1][1]
        for i in range(4):
            patterns.append(
                (self._string_permute(patterns[-1][0], ROTATION_MATRIX), res)
            )
    # mirror
    if "M" in options:
        n = len(patterns)
        for pattern, res in patterns[:n]:
            patterns.append((self._string_permute(pattern, MIRROR_MATRIX), res))

    # negate
    if "N" in options:
        n = len(patterns)
        for pattern, res in patterns[:n]:
            # Swap 0 and 1
            pattern = pattern.replace("0", "Z").replace("1", "0").replace("Z", "1")
            res = 1 - int(res)
            patterns.append((pattern, res))

    return patterns

Pillow.src.PIL.ImageMorph.build_default_lut

def build_default_lut(self) -> None:
    symbols = [0, 1]
    m = 1 << 4  # pos of current pixel
    self.lut = bytearray(symbols[(i & m) > 0] for i in range(LUT_SIZE))

