import sys
from matplotlib import _api, _c_internal_utils, mlab
from gi.repository import GLib

def _get_running_interactive_framework():
    QtWidgets = sys.modules.get('PyQt6.QtWidgets') or sys.modules.get('PySide6.QtWidgets') or sys.modules.get('PyQt5.QtWidgets') or sys.modules.get('PySide2.QtWidgets')
    if QtWidgets and QtWidgets.QApplication.instance():
        return 'qt'
    Gtk = sys.modules.get('gi.repository.Gtk')
    if Gtk:
        if Gtk.MAJOR_VERSION == 4:
            from gi.repository import GLib
            if GLib.main_depth():
                return 'gtk4'
        if Gtk.MAJOR_VERSION == 3 and Gtk.main_level():
            return 'gtk3'
    wx = sys.modules.get('wx')
    if wx and wx.GetApp():
        return 'wx'
    tkinter = sys.modules.get('tkinter')
    if tkinter:
        codes = {tkinter.mainloop.__code__, tkinter.Misc.mainloop.__code__}
        for frame in sys._current_frames().values():
            while frame:
                if frame.f_code in codes:
                    return 'tk'
                frame = frame.f_back
        del frame
    macosx = sys.modules.get('matplotlib.backends._macosx')
    if macosx and macosx.event_loop_is_running():
        return 'macosx'
    if not _c_internal_utils.display_is_valid():
        return 'headless'
    return None

import itertools
import typing as T
import numpy as np

class Hlist(List):

    def __init__(self, elements: T.Sequence[Node], w: float=0.0, m: T.Literal['additional', 'exactly']='additional', do_kern: bool=True):
        super().__init__(elements)
        if do_kern:
            self.kern()
        self.hpack(w=w, m=m)

    def kern(self) -> None:
        new_children = []
        for elem0, elem1 in itertools.zip_longest(self.children, self.children[1:]):
            new_children.append(elem0)
            kerning_distance = elem0.get_kerning(elem1)
            if kerning_distance != 0.0:
                kern = Kern(kerning_distance)
                new_children.append(kern)
        self.children = new_children

    def hpack(self, w: float=0.0, m: T.Literal['additional', 'exactly']='additional') -> None:
        h = 0.0
        d = 0.0
        x = 0.0
        total_stretch = [0.0] * 4
        total_shrink = [0.0] * 4
        for p in self.children:
            if isinstance(p, Char):
                x += p.width
                h = max(h, p.height)
                d = max(d, p.depth)
            elif isinstance(p, Box):
                x += p.width
                if not np.isinf(p.height) and (not np.isinf(p.depth)):
                    s = getattr(p, 'shift_amount', 0.0)
                    h = max(h, p.height - s)
                    d = max(d, p.depth + s)
            elif isinstance(p, Glue):
                glue_spec = p.glue_spec
                x += glue_spec.width
                total_stretch[glue_spec.stretch_order] += glue_spec.stretch
                total_shrink[glue_spec.shrink_order] += glue_spec.shrink
            elif isinstance(p, Kern):
                x += p.width
        self.height = h
        self.depth = d
        if m == 'additional':
            w += x
        self.width = w
        x = w - x
        if x == 0.0:
            self.glue_sign = 0
            self.glue_order = 0
            self.glue_ratio = 0.0
            return
        if x > 0.0:
            self._set_glue(x, 1, total_stretch, 'Overful')
        else:
            self._set_glue(x, -1, total_shrink, 'Underful')

matplotlib.lib.matplotlib._mathtext._set_glue

def _set_glue(self, x: float, sign: int, totals: list[float],
              error_type: str) -> None:
    self.glue_order = o = next(
        # Highest order of glue used by the members of this list.
        (i for i in range(len(totals))[::-1] if totals[i] != 0), 0)
    self.glue_sign = sign
    if totals[o] != 0.:
        self.glue_set = x / totals[o]
    else:
        self.glue_sign = 0
        self.glue_ratio = 0.
    if o == 0:
        if len(self.children):
            _log.warning("%s %s: %r",
                         error_type, type(self).__name__, self)

def largest_smallest_integers(lst):
    smallest = list(filter(lambda x: x < 0, lst))
    largest = list(filter(lambda x: x > 0, lst))
    return (max(smallest) if smallest else None, min(largest) if largest else None)

import numpy as np
from scipy import sparse as sp
from sklearn.base import BaseEstimator, TransformerMixin, _fit_context
from sklearn.utils._mask import _get_mask
from sklearn.utils._missing import is_pandas_na, is_scalar_nan
from sklearn.utils._param_validation import MissingValues, StrOptions
from sklearn.utils.validation import FLOAT_DTYPES, _check_feature_names_in, _check_n_features, check_is_fitted, validate_data

class MissingIndicator(TransformerMixin, BaseEstimator):
    _parameter_constraints: dict = {'missing_values': [MissingValues()], 'features': [StrOptions({'missing-only', 'all'})], 'sparse': ['boolean', StrOptions({'auto'})], 'error_on_new': ['boolean']}

    def __init__(self, *, missing_values=np.nan, features='missing-only', sparse='auto', error_on_new=True):
        self.missing_values = missing_values
        self.features = features
        self.sparse = sparse
        self.error_on_new = error_on_new

    def _get_missing_features_info(self, X):
        if not self._precomputed:
            imputer_mask = _get_mask(X, self.missing_values)
        else:
            imputer_mask = X
        if sp.issparse(X):
            imputer_mask.eliminate_zeros()
            if self.features == 'missing-only':
                n_missing = imputer_mask.sum(axis=0)
            if self.sparse is False:
                imputer_mask = imputer_mask.toarray()
            elif imputer_mask.format == 'csr':
                imputer_mask = imputer_mask.tocsc()
        else:
            if not self._precomputed:
                imputer_mask = _get_mask(X, self.missing_values)
            else:
                imputer_mask = X
            if self.features == 'missing-only':
                n_missing = imputer_mask.sum(axis=0)
            if self.sparse is True:
                imputer_mask = sp.csc_matrix(imputer_mask)
        if self.features == 'all':
            features_indices = np.arange(X.shape[1])
        else:
            features_indices = np.flatnonzero(n_missing)
        return (imputer_mask, features_indices)

    def _validate_input(self, X, in_fit):
        if not is_scalar_nan(self.missing_values):
            ensure_all_finite = True
        else:
            ensure_all_finite = 'allow-nan'
        X = validate_data(self, X, reset=in_fit, accept_sparse=('csc', 'csr'), dtype=None, ensure_all_finite=ensure_all_finite)
        _check_inputs_dtype(X, self.missing_values)
        if X.dtype.kind not in ('i', 'u', 'f', 'O'):
            raise ValueError('MissingIndicator does not support data with dtype {0}. Please provide either a numeric array (with a floating point or integer dtype) or categorical data represented either as an array with integer dtype or an array of string values with an object dtype.'.format(X.dtype))
        if sp.issparse(X) and self.missing_values == 0:
            raise ValueError('Sparse input with missing_values=0 is not supported. Provide a dense array instead.')
        return X

    def _fit(self, X, y=None, precomputed=False):
        if precomputed:
            if not (hasattr(X, 'dtype') and X.dtype.kind == 'b'):
                raise ValueError('precomputed is True but the input data is not a mask')
            self._precomputed = True
        else:
            self._precomputed = False
        if not self._precomputed:
            X = self._validate_input(X, in_fit=True)
        else:
            _check_n_features(self, X, reset=True)
        self._n_features = X.shape[1]
        missing_features_info = self._get_missing_features_info(X)
        self.features_ = missing_features_info[1]
        return missing_features_info[0]

scikit-learn.sklearn.impute._base._get_missing_features_info

def _get_missing_features_info(self, X):
    """Compute the imputer mask and the indices of the features
    containing missing values.

    Parameters
    ----------
    X : {ndarray, sparse matrix} of shape (n_samples, n_features)
        The input data with missing values. Note that `X` has been
        checked in :meth:`fit` and :meth:`transform` before to call this
        function.

    Returns
    -------
    imputer_mask : {ndarray, sparse matrix} of shape \
    (n_samples, n_features)
        The imputer mask of the original data.

    features_with_missing : ndarray of shape (n_features_with_missing)
        The features containing missing values.
    """
    if not self._precomputed:
        imputer_mask = _get_mask(X, self.missing_values)
    else:
        imputer_mask = X

    if sp.issparse(X):
        imputer_mask.eliminate_zeros()

        if self.features == "missing-only":
            # count number of True values in each row.
            n_missing = imputer_mask.sum(axis=0)

        if self.sparse is False:
            imputer_mask = imputer_mask.toarray()
        elif imputer_mask.format == "csr":
            imputer_mask = imputer_mask.tocsc()
    else:
        if not self._precomputed:
            imputer_mask = _get_mask(X, self.missing_values)
        else:
            imputer_mask = X

        if self.features == "missing-only":
            n_missing = imputer_mask.sum(axis=0)

        if self.sparse is True:
            imputer_mask = sp.csc_matrix(imputer_mask)

    if self.features == "all":
        features_indices = np.arange(X.shape[1])
    else:
        features_indices = np.flatnonzero(n_missing)

    return imputer_mask, features_indices

scikit-learn.sklearn.impute._base._validate_input

def _validate_input(self, X, in_fit):
    if not is_scalar_nan(self.missing_values):
        ensure_all_finite = True
    else:
        ensure_all_finite = "allow-nan"
    X = validate_data(
        self,
        X,
        reset=in_fit,
        accept_sparse=("csc", "csr"),
        dtype=None,
        ensure_all_finite=ensure_all_finite,
    )
    _check_inputs_dtype(X, self.missing_values)
    if X.dtype.kind not in ("i", "u", "f", "O"):
        raise ValueError(
            "MissingIndicator does not support data with "
            "dtype {0}. Please provide either a numeric array"
            " (with a floating point or integer dtype) or "
            "categorical data represented either as an array "
            "with integer dtype or an array of string values "
            "with an object dtype.".format(X.dtype)
        )

    if sp.issparse(X) and self.missing_values == 0:
        # missing_values = 0 not allowed with sparse data as it would
        # force densification
        raise ValueError(
            "Sparse input with missing_values=0 is "
            "not supported. Provide a dense "
            "array instead."
        )

    return X

scikit-learn.sklearn.utils.validation._check_n_features

def _check_n_features(estimator, X, reset):
    """Set the `n_features_in_` attribute, or check against it on an estimator.

    .. note::
        To only check n_features without conducting a full data validation, prefer
        using `validate_data(..., skip_check_array=True)` if possible.

    .. versionchanged:: 1.6
        Moved from :class:`~sklearn.base.BaseEstimator` to
        :mod:`~sklearn.utils.validation`.

    Parameters
    ----------
    estimator : estimator instance
        The estimator to validate the input for.

    X : {ndarray, sparse matrix} of shape (n_samples, n_features)
        The input samples.

    reset : bool
        Whether to reset the `n_features_in_` attribute.
        If True, the `n_features_in_` attribute is set to `X.shape[1]`.
        If False and the attribute exists, then check that it is equal to
        `X.shape[1]`. If False and the attribute does *not* exist, then
        the check is skipped.

        .. note::
           It is recommended to call `reset=True` in `fit` and in the first
           call to `partial_fit`. All other methods that validate `X`
           should set `reset=False`.
    """
    try:
        n_features = _num_features(X)
    except TypeError as e:
        if not reset and hasattr(estimator, "n_features_in_"):
            raise ValueError(
                "X does not contain any features, but "
                f"{estimator.__class__.__name__} is expecting "
                f"{estimator.n_features_in_} features"
            ) from e
        # If the number of features is not defined and reset=True,
        # then we skip this check
        return

    if reset:
        estimator.n_features_in_ = n_features
        return

    if not hasattr(estimator, "n_features_in_"):
        # Skip this check if the expected number of expected input features
        # was not recorded by calling fit first. This is typically the case
        # for stateless transformers.
        return

    if n_features != estimator.n_features_in_:
        raise ValueError(
            f"X has {n_features} features, but {estimator.__class__.__name__} "
            f"is expecting {estimator.n_features_in_} features as input."
        )

