    obj._free = index_structure.free[:]
    obj._dum = index_structure.dum[:]
    obj._free_indices = {x[0] for x in obj.free}
    obj._rank = len(obj.free)
    obj._ext_rank = len(obj._index_structure.free) + 2 * len(obj._index_structure.dum)
