.sympy.combinatorics.permutations.Cycle.__init__

def __init__(self, *args):
    if not args:
        return
    if len(args) == 1:
        if isinstance(args[0], Permutation):
            for c in args[0].cyclic_form:
                self.update(self(*c))
            return
        elif isinstance(args[0], Cycle):
            for k, v in args[0].items():
                self[k] = v
            return
    args = [as_int(a) for a in args]
    if any((i < 0 for i in args)):
        raise ValueError('negative integers are not allowed in a cycle.')
    if has_dups(args):
        raise ValueError('All elements must be unique in a cycle.')
    for i in range(-len(args), 0):
        self[args[i]] = args[i + 1]

.sympy.combinatorics.permutations.Permutation.cyclic_form

def cyclic_form(self):
    if self._cyclic_form is not None:
        return list(self._cyclic_form)
    array_form = self.array_form
    unchecked = [True] * len(array_form)
    cyclic_form = []
    for i in range(len(array_form)):
        if unchecked[i]:
            cycle = []
            cycle.append(i)
            unchecked[i] = False
            j = i
            while unchecked[array_form[j]]:
                j = array_form[j]
                cycle.append(j)
                unchecked[j] = False
            if len(cycle) > 1:
                cyclic_form.append(cycle)
                assert cycle == list(minlex(cycle))
    cyclic_form.sort()
    self._cyclic_form = cyclic_form[:]
    return cyclic_form

.sympy.combinatorics.permutations.Permutation.array_form

def array_form(self):
    return self._array_form[:]

.sympy.combinatorics.permutations.Cycle.__call__

def __call__(self, *other):
    rv = Cycle(*other)
    for k, v in zip(list(self.keys()), [rv[self[k]] for k in self.keys()]):
        rv[k] = v
    return rv

.sympy.utilities.misc.as_int

def as_int(n, strict=True):
    if strict:
        try:
            if isinstance(n, bool):
                raise TypeError
            return operator.index(n)
        except TypeError:
            raise ValueError('%s is not an integer' % (n,))
    else:
        try:
            result = int(n)
        except TypeError:
            raise ValueError('%s is not an integer' % (n,))
        if n != result:
