.sympy.core.numbers.Rational.__lt__

def __lt__(self, other):
    try:
        other = _sympify(other)
    except SympifyError:
        raise TypeError('Invalid comparison %s < %s' % (self, other))
    if other.is_NumberSymbol:
        return other.__gt__(self)
    expr = self
    if other.is_Number:
        if other.is_Rational:
            return _sympify(bool(self.p * other.q < self.q * other.p))
        if other.is_Float:
            return _sympify(bool(mlib.mpf_lt(self._as_mpf_val(other._prec), other._mpf_)))
    elif other.is_number and other.is_real:
        expr, other = (Integer(self.p), self.q * other)
    return Expr.__lt__(expr, other)

.sympy.core.expr.Expr.__lt__

def __lt__(self, other):
    from sympy import StrictLessThan
    try:
        other = _sympify(other)
    except SympifyError:
        raise TypeError('Invalid comparison %s < %s' % (self, other))
    for me in (self, other):
        if me.is_complex and me.is_real is False:
            raise TypeError('Invalid comparison of complex %s' % me)
        if me is S.NaN:
            raise TypeError('Invalid NaN comparison')
    n2 = _n2(self, other)
    if n2 is not None:
        return _sympify(n2 < 0)
    if self.is_real or other.is_real:
        dif = self - other
        if dif.is_negative is not None and dif.is_negative is not dif.is_nonnegative:
            return sympify(dif.is_negative)
    return StrictLessThan(self, other, evaluate=False)

.sympy.core.expr._n2

def _n2(a, b):
    if a.is_comparable and b.is_comparable:
        dif = (a - b).evalf(2)
        if dif.is_comparable:
            return dif

.sympy.core.basic.Basic.is_comparable

def is_comparable(self):
    is_real = self.is_real
    if is_real is False:
        return False
    if not self.is_number:
        return False
    n, i = [p.evalf(2) if not p.is_Number else p for p in self.as_real_imag()]
    if not (i.is_Number and n.is_Number):
        return False
    if i:
        return False
    else:
        return n._prec != 1

