.sympy.sets.sets.FiniteSet._contains

def _contains(self, other):
    r = false
    for e in self._elements:
        t = Eq(e, other, evaluate=True)
        if t is true:
            return t
        elif t is not false:
            r = None
    return r

.sympy.core.relational.Equality.__new__

def __new__(cls, lhs, rhs=0, **options):
    from sympy.core.add import Add
    from sympy.core.logic import fuzzy_bool
    from sympy.core.expr import _n2
    from sympy.simplify.simplify import clear_coefficients
    lhs = _sympify(lhs)
    rhs = _sympify(rhs)
    evaluate = options.pop('evaluate', global_evaluate[0])
    if evaluate:
        if hasattr(lhs, '_eval_Eq'):
            r = lhs._eval_Eq(rhs)
            if r is not None:
                return r
        if hasattr(rhs, '_eval_Eq'):
            r = rhs._eval_Eq(lhs)
            if r is not None:
                return r
        if lhs == rhs:
            return S.true
        elif all((isinstance(i, BooleanAtom) for i in (rhs, lhs))):
            return S.false
        elif not (lhs.is_Symbol or rhs.is_Symbol) and isinstance(lhs, Boolean) != isinstance(rhs, Boolean):
            return S.false
        fin = L, R = [i.is_finite for i in (lhs, rhs)]
        if None not in fin:
            if L != R:
                return S.false
            if L is False:
                if lhs == -rhs:
                    return S.false
                return S.true
        elif None in fin and False in fin:
            return Relational.__new__(cls, lhs, rhs, **options)
        if all((isinstance(i, Expr) for i in (lhs, rhs))):
            dif = lhs - rhs
            z = dif.is_zero
            if z is not None:
                if z is False and dif.is_commutative:
                    return S.false
                if z:
                    return S.true
            n2 = _n2(lhs, rhs)
            if n2 is not None:
                return _sympify(n2 == 0)
            n, d = dif.as_numer_denom()
            rv = None
            if n.is_zero:
                rv = d.is_nonzero
            elif n.is_finite:
                if d.is_infinite:
                    rv = S.true
                elif n.is_zero is False:
                    rv = d.is_infinite
                    if rv is None:
                        l, r = clear_coefficients(d, S.Infinity)
                        args = [_.subs(l, r) for _ in (lhs, rhs)]
                        if args != [lhs, rhs]:
                            rv = fuzzy_bool(Eq(*args))
                            if rv is True:
                                rv = None
            elif any((a.is_infinite for a in Add.make_args(n))):
                rv = S.false
            if rv is not None:
                return _sympify(rv)
    return Relational.__new__(cls, lhs, rhs, **options)

.sympy.logic.boolalg.BooleanTrue.__hash__

def __hash__(self):
    return hash(True)

.sympy.core.function.Application.__new__

def __new__(cls, *args, **options):
    from sympy.sets.fancysets import Naturals0
    from sympy.sets.sets import FiniteSet
    args = list(map(sympify, args))
    evaluate = options.pop('evaluate', global_evaluate[0])
    options.pop('nargs', None)
    if options:
        raise ValueError('Unknown options: %s' % options)
    if evaluate:
        evaluated = cls.eval(*args)
        if evaluated is not None:
            return evaluated
    obj = super(Application, cls).__new__(cls, *args, **options)
    try:
        if is_sequence(obj.nargs):
            nargs = tuple(ordered(set(obj.nargs)))
        elif obj.nargs is not None:
            nargs = (as_int(obj.nargs),)
        else:
            nargs = None
    except AttributeError:
        nargs = obj._nargs
    obj.nargs = FiniteSet(*nargs) if nargs else Naturals0()
    return obj

.sympy.functions.combinatorial.factorials.RisingFactorial.eval

def eval(cls, x, k):
    x = sympify(x)
    k = sympify(k)
    if x is S.NaN or k is S.NaN:
        return S.NaN
    elif x is S.One:
        return factorial(k)
    elif k.is_Integer:
        if k is S.Zero:
            return S.One
        elif k.is_positive:
            if x is S.Infinity:
                return S.Infinity
            elif x is S.NegativeInfinity:
                if k.is_odd:
                    return S.NegativeInfinity
                else:
                    return S.Infinity
            elif isinstance(x, Poly):
                gens = x.gens
                if len(gens) != 1:
                    raise ValueError('rf only defined for polynomials on one generator')
                else:
                    return reduce(lambda r, i: r * x.shift(i).expand(), range(0, int(k)), 1)
            else:
                return reduce(lambda r, i: r * (x + i), range(0, int(k)), 1)
        elif x is S.Infinity:
            return S.Infinity
        elif x is S.NegativeInfinity:
            return S.Infinity
        elif isinstance(x, Poly):
            gens = x.gens
            if len(gens) != 1:
                raise ValueError('rf only defined for polynomials on one generator')
            else:
                return 1 / reduce(lambda r, i: r * x.shift(-i).expand(), range(1, abs(int(k)) + 1), 1)
        else:
            return 1 / reduce(lambda r, i: r * (x - i), range(1, abs(int(k)) + 1), 1)

.sympy.core.function.Function._should_evalf

def _should_evalf(cls, arg):
    from sympy.core.evalf import pure_complex
    if arg.is_Float:
        return arg._prec
    if not arg.is_Add:
        return -1
    m = pure_complex(arg)
    if m is None or not (m[0].is_Float or m[1].is_Float):
        return -1
    l = [i._prec for i in m if i.is_Float]
    l.append(-1)
    return max(l)

.sympy.core.expr.Expr.__pow__

def __pow__(self, other, mod=None):
    if mod is None:
        return self._pow(other)
    try:
        _self, other, mod = (as_int(self), as_int(other), as_int(mod))
        if other >= 0:
            return pow(_self, other, mod)
        else:
            from sympy.core.numbers import mod_inverse
            return mod_inverse(pow(_self, -other, mod), mod)
    except ValueError:
        power = self._pow(other)
        try:
            return power % mod
        except TypeError:
            return NotImplemented

