.sympy.polys.sqfreetools.dup_sqf_part

def dup_sqf_part(f, K):
    if K.is_FiniteField:
        return dup_gf_sqf_part(f, K)
    if not f:
        return f
    if K.is_negative(dup_LC(f, K)):
        f = dup_neg(f, K)
    gcd = dup_gcd(f, dup_diff(f, 1, K), K)
    sqf = dup_quo(f, gcd, K)
    if K.is_Field:
        return dup_monic(sqf, K)
    else:
        return dup_primitive(sqf, K)[1]

.sympy.polys.domains.domain.Domain.is_negative

def is_negative(self, a):
    return a < 0

.sympy.polys.densetools.dup_diff

def dup_diff(f, m, K):
    if m <= 0:
        return f
    n = dup_degree(f)
    if n < m:
        return []
    deriv = []
    if m == 1:
        for coeff in f[:-m]:
            deriv.append(K(n) * coeff)
            n -= 1
    else:
        for coeff in f[:-m]:
            k = n
            for i in range(n - 1, n - m, -1):
                k *= i
            deriv.append(K(k) * coeff)
            n -= 1
    return dup_strip(deriv)

.sympy.polys.domains.domain.Domain.__call__

def __call__(self, *args):
    return self.new(*args)

.sympy.polys.domains.domain.Domain.new

def new(self, *args):
