from typing import Callable, TYPE_CHECKING
from .singleton import S
from .expr import Expr
from .logic import fuzzy_bool, fuzzy_not, fuzzy_and, fuzzy_or
from .numbers import Integer, Rational

class Pow(Expr):
    is_Pow = True
    __slots__ = ('is_commutative',)
    if TYPE_CHECKING:

        @property
        def args(self) -> tuple[Expr, Expr]:
            ...

    @property
    def base(self) -> Expr:
        return self.args[0]

    @property
    def exp(self) -> Expr:
        return self.args[1]

    def as_base_exp(self):
        b, e = self.args
        if b.is_Rational and b.p == 1 and (b.q != 1):
            return (Integer(b.q), -e)
        return (b, e)

    def _eval_is_rational(self):
        if self.exp.is_integer and self.base.is_rational and fuzzy_not(fuzzy_and([self.exp.is_negative, self.base.is_zero])):
            return True
        p = self.func(*self.as_base_exp())
        if not p.is_Pow:
            return p.is_rational
        b, e = p.as_base_exp()
        if e.is_Rational and b.is_Rational:
            return False
        if e.is_integer:
            if b.is_rational:
                if fuzzy_not(b.is_zero) or e.is_nonnegative:
                    return True
                if b == e:
                    return True
            elif b.is_irrational:
                return e.is_zero
        if b is S.Exp1:
            if e.is_rational and e.is_nonzero:
                return False

