sympy.sympy.core.decorators._func

@wraps(func)
def _func(self, other):
    # XXX: The check for _op_priority here should be removed. It is
    # needed to stop mutable matrices from being sympified to
    # immutable matrices which breaks things in quantum...
    if not hasattr(other, '_op_priority'):
        try:
            other = sympify(other, strict=True)
        except SympifyError:
            return retval
    if not isinstance(other, expectedcls):
        return retval
    return func(self, other)

sympy.sympy.core.expr.is_number

@property
def is_number(self):
    """Returns True if ``self`` has no free symbols and no
    undefined functions (AppliedUndef, to be precise). It will be
    faster than ``if not self.free_symbols``, however, since
    ``is_number`` will fail as soon as it hits a free symbol
    or undefined function.

    Examples
    ========

    >>> from sympy import Function, Integral, cos, sin, pi
    >>> from sympy.abc import x
    >>> f = Function('f')

    >>> x.is_number
    False
    >>> f(1).is_number
    False
    >>> (2*x).is_number
    False
    >>> (2 + Integral(2, x)).is_number
    False
    >>> (2 + Integral(2, (x, 1, 2))).is_number
    True

    Not all numbers are Numbers in the SymPy sense:

    >>> pi.is_number, pi.is_Number
    (True, False)

    If something is a number it should evaluate to a number with
    real and imaginary parts that are Numbers; the result may not
    be comparable, however, since the real and/or imaginary part
    of the result may not have precision.

    >>> cos(1).is_number and cos(1).is_comparable
    True

    >>> z = cos(1)**2 + sin(1)**2 - 1
    >>> z.is_number
    True
    >>> z.is_comparable
    False

    See Also
    ========

    sympy.core.basic.Basic.is_comparable
    """
    return all(obj.is_number for obj in self.args)

sympy.sympy.core.numbers.__rdivmod__

def __rdivmod__(self, other):
    if isinstance(other, int) and global_parameters.evaluate:
        return Tuple(*(divmod(other, self.p)))
    else:
        try:
            other = Number(other)
        except TypeError:
            msg = "unsupported operand type(s) for divmod(): '%s' and '%s'"
            oname = type(other).__name__
            sname = type(self).__name__
            raise TypeError(msg % (oname, sname))
        return Number.__divmod__(other, self)

sympy.sympy.core.numbers.__rmul__

def __rmul__(self, other):
    if global_parameters.evaluate:
        if isinstance(other, int):
            return Integer(other*self.p)
        elif isinstance(other, Rational):
            return Rational._new(other.p*self.p, other.q, igcd(self.p, other.q))
        return Rational.__rmul__(self, other)
    return Rational.__rmul__(self, other)

sympy.sympy.core.numbers.__lt__

def __lt__(self, other):
    try:
        other = _sympify(other)
    except SympifyError:
        return NotImplemented
    if other.is_Integer:
        return _sympify(self.p < other.p)
    return Rational.__lt__(self, other)

sympy.sympy.core.numbers.__ge__

def __ge__(self, other):
    try:
        other = _sympify(other)
    except SympifyError:
        return NotImplemented
    if other.is_Integer:
        return _sympify(self.p >= other.p)
    return Rational.__ge__(self, other)

sympy.sympy.core.numbers.__index__

def __index__(self):
