def restify(cls: Optional['Type']) -> str:
    from sphinx.util import inspect
    if cls is None or cls is NoneType:
        return ':obj:`None`'
    elif cls is Ellipsis:
        return '...'
    elif cls in INVALID_BUILTIN_CLASSES:
        return ':class:`%s`' % INVALID_BUILTIN_CLASSES[cls]
    elif inspect.isNewType(cls):
        return ':class:`%s`' % cls.__name__
    elif types_Union and isinstance(cls, types_Union):
        if len(cls.__args__) > 1 and None in cls.__args__:
            args = ' | '.join((restify(a) for a in cls.__args__ if a))
            return 'Optional[%s]' % args
        else:
            return ' | '.join((restify(a) for a in cls.__args__))
    elif cls.__module__ in ('__builtin__', 'builtins'):
        return ':class:`%s`' % cls.__name__
    elif sys.version_info >= (3, 7):
        return _restify_py37(cls)
    else:
        return _restify_py36(cls)

.sphinx.util.inspect.isNewType

def isNewType(obj: Any) -> bool:
    __module__ = safe_getattr(obj, '__module__', None)
    __qualname__ = safe_getattr(obj, '__qualname__', None)
    if __module__ == 'typing' and __qualname__ == 'NewType.<locals>.new_type':
        return True
    else:
        return False

.sphinx.util.inspect.safe_getattr

def safe_getattr(obj: Any, name: str, *defargs: Any) -> Any:
    try:
        return getattr(obj, name, *defargs)
    except Exception as exc:
        try:
            return obj.__dict__[name]
        except Exception:
            pass
        if defargs:
            return defargs[0]
        raise AttributeError(name) from exc

from __future__ import print_function, division
from collections import defaultdict
from sympy import SYMPY_DEBUG
from sympy.core import expand_power_base, sympify, Add, S, Mul, Derivative, Pow, symbols, expand_mul
from sympy.core.add import _unevaluated_Add
from sympy.core.compatibility import iterable, ordered, default_sort_key
from sympy.core.parameters import global_parameters
from sympy.core.exprtools import Factors, gcd_terms
from sympy.core.function import _mexpand
from sympy.core.mul import _keep_coeff, _unevaluated_Mul
from sympy.core.numbers import Rational
from sympy.functions import exp, sqrt, log
from sympy.functions.elementary.complexes import Abs
from sympy.polys import gcd
from sympy.simplify.sqrtdenest import sqrtdenest
from sympy.core.assumptions import assumptions
from sympy.utilities.iterables import sift
from sympy.core.symbol import Dummy, Wild
from sympy.simplify.simplify import signsimp
from sympy.core.mul import _mulsort
from sympy.simplify.simplify import nsimplify
from sympy.simplify.powsimp import powsimp, powdenest
expand_numer = numer_expand
expand_denom = denom_expand
expand_fraction = fraction_expand

def collect(expr, syms, func=None, evaluate=None, exact=False, distribute_order_term=True):
    from sympy.core.assumptions import assumptions
    from sympy.utilities.iterables import sift
    from sympy.core.symbol import Dummy, Wild
    expr = sympify(expr)
    syms = [sympify(i) for i in (syms if iterable(syms) else [syms])]
    cond = lambda x: x.is_Symbol or (-x).is_Symbol or bool(x.atoms(Wild))
    _, nonsyms = sift(syms, cond, binary=True)
    if nonsyms:
        reps = dict(zip(nonsyms, [Dummy(**assumptions(i)) for i in nonsyms]))
        syms = [reps.get(s, s) for s in syms]
        rv = collect(expr.subs(reps), syms, func=func, evaluate=evaluate, exact=exact, distribute_order_term=distribute_order_term)
        urep = {v: k for k, v in reps.items()}
        if not isinstance(rv, dict):
            return rv.xreplace(urep)
        else:
            return {urep.get(k, k): v.xreplace(urep) for k, v in rv.items()}
    if evaluate is None:
        evaluate = global_parameters.evaluate

    def make_expression(terms):
        product = []
        for term, rat, sym, deriv in terms:
            if deriv is not None:
                var, order = deriv
                while order > 0:
                    term, order = (Derivative(term, var), order - 1)
            if sym is None:
                if rat is S.One:
                    product.append(term)
                else:
                    product.append(Pow(term, rat))
            else:
                product.append(Pow(term, rat * sym))
        return Mul(*product)

    def parse_derivative(deriv):
        expr, sym, order = (deriv.expr, deriv.variables[0], 1)
        for s in deriv.variables[1:]:
            if s == sym:
                order += 1
            else:
                raise NotImplementedError('Improve MV Derivative support in collect')
        while isinstance(expr, Derivative):
            s0 = expr.variables[0]
            for s in expr.variables:
                if s != s0:
                    raise NotImplementedError('Improve MV Derivative support in collect')
            if s0 == sym:
                expr, order = (expr.expr, order + len(expr.variables))
            else:
                break
        return (expr, (sym, Rational(order)))

    def parse_term(expr):
        rat_expo, sym_expo = (S.One, None)
        sexpr, deriv = (expr, None)
        if expr.is_Pow:
            if isinstance(expr.base, Derivative):
                sexpr, deriv = parse_derivative(expr.base)
            else:
                sexpr = expr.base
            if expr.exp.is_Number:
                rat_expo = expr.exp
            else:
                coeff, tail = expr.exp.as_coeff_Mul()
                if coeff.is_Number:
                    rat_expo, sym_expo = (coeff, tail)
                else:
                    sym_expo = expr.exp
        elif isinstance(expr, exp):
            arg = expr.args[0]
            if arg.is_Rational:
                sexpr, rat_expo = (S.Exp1, arg)
            elif arg.is_Mul:
                coeff, tail = arg.as_coeff_Mul(rational=True)
                sexpr, rat_expo = (exp(tail), coeff)
        elif isinstance(expr, Derivative):
            sexpr, deriv = parse_derivative(expr)
        return (sexpr, rat_expo, sym_expo, deriv)

    def parse_expression(terms, pattern):
        pattern = Mul.make_args(pattern)
        if len(terms) < len(pattern):
            return None
        else:
            pattern = [parse_term(elem) for elem in pattern]
            terms = terms[:]
            elems, common_expo, has_deriv = ([], None, False)
            for elem, e_rat, e_sym, e_ord in pattern:
                if elem.is_Number and e_rat == 1 and (e_sym is None):
                    continue
                for j in range(len(terms)):
                    if terms[j] is None:
                        continue
                    term, t_rat, t_sym, t_ord = terms[j]
                    if t_ord is not None:
                        has_deriv = True
                    if term.match(elem) is not None and (t_sym == e_sym or (t_sym is not None and e_sym is not None and (t_sym.match(e_sym) is not None))):
                        if exact is False:
                            expo = t_rat / e_rat
                            if common_expo is None:
                                common_expo = expo
                            elif common_expo != expo:
                                common_expo = 1
                        elif e_rat != t_rat or e_ord != t_ord:
                            continue
                        elems.append(terms[j])
                        terms[j] = None
                        break
                else:
                    return None
            return ([_f for _f in terms if _f], elems, common_expo, has_deriv)
    if evaluate:
        if expr.is_Add:
            o = expr.getO() or 0
            expr = expr.func(*[collect(a, syms, func, True, exact, distribute_order_term) for a in expr.args if a != o]) + o
        elif expr.is_Mul:
            return expr.func(*[collect(term, syms, func, True, exact, distribute_order_term) for term in expr.args])
        elif expr.is_Pow:
            b = collect(expr.base, syms, func, True, exact, distribute_order_term)
            return Pow(b, expr.exp)
    syms = [expand_power_base(i, deep=False) for i in syms]
    order_term = None
    if distribute_order_term:
        order_term = expr.getO()
        if order_term is not None:
            if order_term.has(*syms):
                order_term = None
            else:
                expr = expr.removeO()
    summa = [expand_power_base(i, deep=False) for i in Add.make_args(expr)]
    collected, disliked = (defaultdict(list), S.Zero)
    for product in summa:
        c, nc = product.args_cnc(split_1=False)
        args = list(ordered(c)) + nc
        terms = [parse_term(i) for i in args]
        small_first = True
        for symbol in syms:
            if SYMPY_DEBUG:
                print('DEBUG: parsing of expression %s with symbol %s ' % (str(terms), str(symbol)))
            if isinstance(symbol, Derivative) and small_first:
                terms = list(reversed(terms))
                small_first = not small_first
            result = parse_expression(terms, symbol)
            if SYMPY_DEBUG:
                print('DEBUG: returned %s' % str(result))
            if result is not None:
                if not symbol.is_commutative:
                    raise AttributeError('Can not collect noncommutative symbol')
                terms, elems, common_expo, has_deriv = result
                if not has_deriv:
                    margs = []
                    for elem in elems:
                        if elem[2] is None:
                            e = elem[1]
                        else:
                            e = elem[1] * elem[2]
                        margs.append(Pow(elem[0], e))
                    index = Mul(*margs)
                else:
                    index = make_expression(elems)
                terms = expand_power_base(make_expression(terms), deep=False)
                index = expand_power_base(index, deep=False)
                collected[index].append(terms)
                break
        else:
            disliked += product
    collected = {k: Add(*v) for k, v in collected.items()}
    if disliked is not S.Zero:
        collected[S.One] = disliked
    if order_term is not None:
        for key, val in collected.items():
            collected[key] = val + order_term
    if func is not None:
        collected = dict([(key, func(val)) for key, val in collected.items()])
    if evaluate:
        return Add(*[key * val for key, val in collected.items()])
    else:
        return collected

def GCD(a, b):
    while a % b != 0:
        a, b = (b, a % b)
    return b

def LCM(a, b):
    return a * b // GCD(a, b)
