def walk(rv, F):
    args = getattr(rv, 'args', None)
    if args is not None:
        if args:
            newargs = tuple([walk(a, F) for a in args])
            if args != newargs:
                rv = rv.func(*newargs)
                if simultaneous:
                    for i, e in enumerate(args):
                        if rv == e and e != newargs[i]:
                            return rv
        rv = F(rv)
    return rv

