.sympy.core.numbers.NaN.__eq__

def __eq__(self, other):
    return other is S.NaN

.sympy.core.basic.Basic._subs

def _subs(self, old, new, **hints):

    def fallback(self, old, new):
        hit = False
        args = list(self.args)
        for i, arg in enumerate(args):
            if not hasattr(arg, '_eval_subs'):
                continue
            arg = arg._subs(old, new, **hints)
            if not _aresame(arg, args[i]):
                hit = True
                args[i] = arg
        if hit:
            rv = self.func(*args)
            hack2 = hints.get('hack2', False)
            if hack2 and self.is_Mul and (not rv.is_Mul):
                coeff = S.One
                nonnumber = []
                for i in args:
                    if i.is_Number:
                        coeff *= i
                    else:
                        nonnumber.append(i)
                nonnumber = self.func(*nonnumber)
                if coeff is S.One:
                    return nonnumber
                else:
                    return self.func(coeff, nonnumber, evaluate=False)
            return rv
        return self
    if _aresame(self, old):
        return new
    rv = self._eval_subs(old, new)
    if rv is None:
        rv = fallback(self, old, new)
    return rv

.sympy.core.mul.Mul._eval_subs

def _eval_subs(self, old, new):
    from sympy.functions.elementary.complexes import sign
    from sympy.ntheory.factor_ import multiplicity
    from sympy.simplify.powsimp import powdenest
    from sympy.simplify.radsimp import fraction
    if not old.is_Mul:
        return None
    if old.args[0].is_Number and old.args[0] < 0:
        if self.args[0].is_Number:
            if self.args[0] < 0:
                return self._subs(-old, -new)
            return None

    def base_exp(a):
        from sympy.functions.elementary.exponential import exp
        if a.is_Pow or isinstance(a, exp):
            return a.as_base_exp()
        return (a, S.One)

    def breakup(eq):
        c, nc = (defaultdict(int), list())
        for a in Mul.make_args(eq):
            a = powdenest(a)
            b, e = base_exp(a)
            if e is not S.One:
                co, _ = e.as_coeff_mul()
                b = Pow(b, e / co)
                e = co
            if a.is_commutative:
                c[b] += e
            else:
                nc.append([b, e])
        return (c, nc)

    def rejoin(b, co):
        b, e = base_exp(b)
        return Pow(b, e * co)

    def ndiv(a, b):
        if not b.q % a.q or not a.q % b.q:
            return int(a / b)
        return 0
    rv = None
    n, d = fraction(self)
    self2 = self
    if d is not S.One:
        self2 = n._subs(old, new) / d._subs(old, new)
        if not self2.is_Mul:
            return self2._subs(old, new)
        if self2 != self:
            rv = self2
    co_self = self2.args[0]
    co_old = old.args[0]
    co_xmul = None
    if co_old.is_Rational and co_self.is_Rational:
        if co_old != co_self:
            co_xmul = co_self.extract_multiplicatively(co_old)
    elif co_old.is_Rational:
        return rv
    c, nc = breakup(self2)
    old_c, old_nc = breakup(old)
    if co_xmul and co_xmul.is_Rational and (abs(co_old) != 1):
        mult = S(multiplicity(abs(co_old), co_self))
        c.pop(co_self)
        if co_old in c:
            c[co_old] += mult
        else:
            c[co_old] = mult
        co_residual = co_self / co_old ** mult
    else:
        co_residual = 1
    ok = True
    if len(old_nc) > len(nc):
        ok = False
    elif len(old_c) > len(c):
        ok = False
    elif {i[0] for i in old_nc}.difference({i[0] for i in nc}):
        ok = False
    elif set(old_c).difference(set(c)):
        ok = False
    elif any((sign(c[b]) != sign(old_c[b]) for b in old_c)):
        ok = False
    if not ok:
        return rv
    if not old_c:
        cdid = None
    else:
        rat = []
        for b, old_e in old_c.items():
            c_e = c[b]
            rat.append(ndiv(c_e, old_e))
            if not rat[-1]:
                return rv
        cdid = min(rat)
    if not old_nc:
        ncdid = None
        for i in range(len(nc)):
            nc[i] = rejoin(*nc[i])
    else:
        ncdid = 0
        take = len(old_nc)
        limit = cdid or S.Infinity
        failed = []
        i = 0
        while limit and i + take <= len(nc):
            hit = False
            rat = []
            for j in range(take):
                if nc[i + j][0] != old_nc[j][0]:
                    break
                elif j == 0:
                    rat.append(ndiv(nc[i + j][1], old_nc[j][1]))
                elif j == take - 1:
                    rat.append(ndiv(nc[i + j][1], old_nc[j][1]))
                elif nc[i + j][1] != old_nc[j][1]:
                    break
                else:
                    rat.append(1)
                j += 1
            else:
                ndo = min(rat)
                if ndo:
                    if take == 1:
                        if cdid:
                            ndo = min(cdid, ndo)
                        nc[i] = Pow(new, ndo) * rejoin(nc[i][0], nc[i][1] - ndo * old_nc[0][1])
                    else:
                        ndo = 1
                        l = rejoin(nc[i][0], nc[i][1] - ndo * old_nc[0][1])
                        mid = new
                        ir = i + take - 1
                        r = (nc[ir][0], nc[ir][1] - ndo * old_nc[-1][1])
                        if r[1]:
                            if i + take < len(nc):
                                nc[i:i + take] = [l * mid, r]
                            else:
                                r = rejoin(*r)
                                nc[i:i + take] = [l * mid * r]
                        else:
                            nc[i:i + take] = [l * mid]
                    limit -= ndo
                    ncdid += ndo
                    hit = True
            if not hit:
                failed.append(i)
            i += 1
        else:
            if not ncdid:
                return rv
            failed.extend(range(i, len(nc)))
            for i in failed:
                nc[i] = rejoin(*nc[i]).subs(old, new)
    if cdid is None:
        do = ncdid
    elif ncdid is None:
        do = cdid
    else:
        do = min(ncdid, cdid)
    margs = []
    for b in c:
        if b in old_c:
            e = c[b] - old_c[b] * do
            margs.append(rejoin(b, e))
        else:
            margs.append(rejoin(b.subs(old, new), c[b]))
    if cdid and (not ncdid):
        margs = [Pow(new, cdid)] + margs
    return co_residual * self2.func(*margs) * self2.func(*nc)

.sympy.core.basic.Basic.fallback

def fallback(self, old, new):
    hit = False
    args = list(self.args)
    for i, arg in enumerate(args):
        if not hasattr(arg, '_eval_subs'):
            continue
        arg = arg._subs(old, new, **hints)
        if not _aresame(arg, args[i]):
            hit = True
            args[i] = arg
    if hit:
        rv = self.func(*args)
        hack2 = hints.get('hack2', False)
        if hack2 and self.is_Mul and (not rv.is_Mul):
            coeff = S.One
            nonnumber = []
            for i in args:
                if i.is_Number:
                    coeff *= i
                else:
                    nonnumber.append(i)
            nonnumber = self.func(*nonnumber)
            if coeff is S.One:
                return nonnumber
            else:
                return self.func(coeff, nonnumber, evaluate=False)
        return rv
    return self

.sympy.core.symbol.Symbol._eval_subs

def _eval_subs(self, old, new):
    if old.is_Pow:
        from sympy.core.power import Pow
        return Pow(self, S.One, evaluate=False)._eval_subs(old, new)

.sympy.core.basic.Basic.func

def func(self):
    return self.__class__

.sympy.core.numbers.igcd

def igcd(*args):
    if len(args) < 2:
        raise TypeError('igcd() takes at least 2 arguments (%s given)' % len(args))
    args_temp = [abs(as_int(i)) for i in args]
    if 1 in args_temp:
        return 1
    a = args_temp.pop()
    if HAS_GMPY:
        for b in args_temp:
            a = gmpy.gcd(a, b) if b else a
        return as_int(a)
    for b in args_temp:
        a = math.gcd(a, b)
    return a

