.sympy.core.basic.Basic._eval_derivative_n_times

def _eval_derivative_n_times(self, s, n):
    from .numbers import Integer
    if isinstance(n, (int, Integer)):
        obj = self
        for i in range(n):
            obj2 = obj._eval_derivative(s)
            if obj == obj2 or obj2 is None:
                break
            obj = obj2
        return obj2
    else:
        return None

