.sympy.core.expr.Expr.as_coefficient

def as_coefficient(self, expr):
    r = self.extract_multiplicatively(expr)
    if r and (not r.has(expr)):
        return r

.sympy.core.expr.Expr.extract_multiplicatively

def extract_multiplicatively(self, c):
    from sympy.functions.elementary.exponential import exp
    from .add import _unevaluated_Add
    c = sympify(c)
    if self is S.NaN:
        return None
    if c is S.One:
        return self
    elif c == self:
        return S.One
    if c.is_Add:
        cc, pc = c.primitive()
        if cc is not S.One:
            c = Mul(cc, pc, evaluate=False)
    if c.is_Mul:
        a, b = c.as_two_terms()
        x = self.extract_multiplicatively(a)
        if x is not None:
            return x.extract_multiplicatively(b)
        else:
            return x
    quotient = self / c
    if self.is_Number:
        if self is S.Infinity:
            if c.is_positive:
                return S.Infinity
        elif self is S.NegativeInfinity:
            if c.is_negative:
                return S.Infinity
            elif c.is_positive:
                return S.NegativeInfinity
        elif self is S.ComplexInfinity:
            if not c.is_zero:
                return S.ComplexInfinity
        elif self.is_Integer:
            if not quotient.is_Integer:
                return None
            elif self.is_positive and quotient.is_negative:
                return None
            else:
                return quotient
        elif self.is_Rational:
            if not quotient.is_Rational:
                return None
            elif self.is_positive and quotient.is_negative:
                return None
            else:
                return quotient
        elif self.is_Float:
            if not quotient.is_Float:
                return None
            elif self.is_positive and quotient.is_negative:
                return None
            else:
                return quotient
    elif self.is_NumberSymbol or self.is_Symbol or self is S.ImaginaryUnit:
        if quotient.is_Mul and len(quotient.args) == 2:
            if quotient.args[0].is_Integer and quotient.args[0].is_positive and (quotient.args[1] == self):
                return quotient
        elif quotient.is_Integer and c.is_Number:
            return quotient
    elif self.is_Add:
        cs, ps = self.primitive()
        if c.is_Number and c is not S.NegativeOne:
            if cs is not S.One:
                if c.is_negative:
                    xc = -cs.extract_multiplicatively(-c)
                else:
                    xc = cs.extract_multiplicatively(c)
                if xc is not None:
                    return xc * ps
            return
        if c == ps:
            return cs
        newargs = []
        for arg in ps.args:
            newarg = arg.extract_multiplicatively(c)
            if newarg is None:
                return
            newargs.append(newarg)
        if cs is not S.One:
            args = [cs * t for t in newargs]
            return _unevaluated_Add(*args)
        else:
            return Add._from_args(newargs)
    elif self.is_Mul:
        args = list(self.args)
        for i, arg in enumerate(args):
            newarg = arg.extract_multiplicatively(c)
            if newarg is not None:
                args[i] = newarg
                return Mul(*args)
    elif self.is_Pow or isinstance(self, exp):
        sb, se = self.as_base_exp()
        cb, ce = c.as_base_exp()
        if cb == sb:
            new_exp = se.extract_additively(ce)
            if new_exp is not None:
                return Pow(sb, new_exp)
        elif c == sb:
            new_exp = self.exp.extract_additively(1)
            if new_exp is not None:
                return Pow(sb, new_exp)

.sympy.core.numbers.ImaginaryUnit._eval_power

def _eval_power(self, expt):
    if isinstance(expt, Integer):
        expt = expt % 4
        if expt == 0:
            return S.One
        elif expt == 1:
            return S.ImaginaryUnit
        elif expt == 2:
            return S.NegativeOne
        elif expt == 3:
            return -S.ImaginaryUnit
    if isinstance(expt, Rational):
        i, r = divmod(expt, 2)
        rv = Pow(S.ImaginaryUnit, r, evaluate=False)
        if i % 2:
            return Mul(S.NegativeOne, rv, evaluate=False)
        return rv

.sympy.core.expr.Expr.__neg__

def __neg__(self):
    c = self.is_commutative
    return Mul._from_args((S.NegativeOne, self), c)

.sympy.core.function.Function._should_evalf

def _should_evalf(cls, arg):
    if arg.is_Float:
        return arg._prec
    if not arg.is_Add:
        return -1
    from .evalf import pure_complex
    m = pure_complex(arg)
    if m is None or not (m[0].is_Float or m[1].is_Float):
        return -1
    l = [i._prec for i in m if i.is_Float]
    l.append(-1)
    return max(l)

