.sympy.core.mul.Mul._eval_pos_neg

def _eval_pos_neg(self, sign):
    saw_NON = saw_NOT = False
    for t in self.args:
        if t.is_extended_positive:
            continue
        elif t.is_extended_negative:
            sign = -sign
        elif t.is_zero:
            if all((a.is_finite for a in self.args)):
                return False
            return
        elif t.is_extended_nonpositive:
            sign = -sign
            saw_NON = True
        elif t.is_extended_nonnegative:
            saw_NON = True
        elif t.is_positive is False:
            sign = -sign
            if saw_NOT:
                return
            saw_NOT = True
        elif t.is_negative is False:
            if saw_NOT:
                return
            saw_NOT = True
        else:
            return
    if sign == 1 and saw_NON is False and (saw_NOT is False):
        return True
    if sign < 0:
        return False

.sympy.core.mul.Mul._eval_is_extended_positive

def _eval_is_extended_positive(self):
    return self._eval_pos_neg(1)

.sympy.core.expr.Expr._eval_is_positive

def _eval_is_positive(self):
    finite = self.is_finite
    if finite is False:
        return False
    extended_positive = self.is_extended_positive
    if finite is True:
        return extended_positive
    if extended_positive is False:
        return False

.sympy.core.expr.Expr.args_cnc

def args_cnc(self, cset=False, warn=True, split_1=True):
    if self.is_Mul:
        args = list(self.args)
    else:
        args = [self]
    for i, mi in enumerate(args):
        if not mi.is_commutative:
            c = args[:i]
            nc = args[i:]
            break
    else:
        c = args
        nc = []
    if c and split_1 and (c[0].is_Number and c[0].is_extended_negative and (c[0] is not S.NegativeOne)):
        c[:1] = [S.NegativeOne, -c[0]]
    if cset:
        clen = len(c)
        c = set(c)
        if clen and warn and (len(c) != clen):
            raise ValueError('repeated commutative arguments: %s' % [ci for ci in c if list(self.args).count(ci) > 1])
    return [c, nc]

.sympy.utilities.iterables.sift

def sift(seq, keyfunc, binary=False):
    if not binary:
        m = defaultdict(list)
        for i in seq:
            m[keyfunc(i)].append(i)
        return m
    sift = F, T = ([], [])
    for i in seq:
        try:
            sift[keyfunc(i)].append(i)
        except (IndexError, TypeError):
            raise ValueError('keyfunc gave non-binary output')
    return (T, F)

.sympy.core.expr.Expr.has

def has(e):
