.sympy.core.power.Pow._eval_expand_power_base

def _eval_expand_power_base(self, **hints):
    force = hints.get('force', False)
    b = self.base
    e = self.exp
    if not b.is_Mul:
        return self
    cargs, nc = b.args_cnc(split_1=False)
    if nc:
        nc = [i._eval_expand_power_base(**hints) if hasattr(i, '_eval_expand_power_base') else i for i in nc]
        if e.is_Integer:
            if e.is_positive:
                rv = Mul(*nc * e)
            else:
                rv = Mul(*[i ** (-1) for i in nc[::-1]] * -e)
            if cargs:
                rv *= Mul(*cargs) ** e
            return rv
        if not cargs:
            return self.func(Mul(*nc), e, evaluate=False)
        nc = [Mul(*nc)]
    other, maybe_real = sift(cargs, lambda x: x.is_extended_real is False, binary=True)

    def pred(x):
        if x is S.ImaginaryUnit:
            return S.ImaginaryUnit
        polar = x.is_polar
        if polar:
            return True
        if polar is None:
            return fuzzy_bool(x.is_extended_nonnegative)
    sifted = sift(maybe_real, pred)
    nonneg = sifted[True]
    other += sifted[None]
    neg = sifted[False]
    imag = sifted[S.ImaginaryUnit]
    if imag:
        I = S.ImaginaryUnit
        i = len(imag) % 4
        if i == 0:
            pass
        elif i == 1:
            other.append(I)
        elif i == 2:
            if neg:
                nonn = -neg.pop()
                if nonn is not S.One:
                    nonneg.append(nonn)
            else:
                neg.append(S.NegativeOne)
        else:
            if neg:
                nonn = -neg.pop()
                if nonn is not S.One:
                    nonneg.append(nonn)
            else:
                neg.append(S.NegativeOne)
            other.append(I)
        del imag
    if force or e.is_integer:
        cargs = nonneg + neg + other
        other = nc
    else:
        assert not e.is_Integer
        if len(neg) > 1:
            o = S.One
            if not other and neg[0].is_Number:
                o *= neg.pop(0)
            if len(neg) % 2:
                o = -o
            for n in neg:
                nonneg.append(-n)
            if o is not S.One:
                other.append(o)
        elif neg and other:
            if neg[0].is_Number and neg[0] is not S.NegativeOne:
                other.append(S.NegativeOne)
                nonneg.append(-neg[0])
            else:
                other.extend(neg)
        else:
            other.extend(neg)
        del neg
        cargs = nonneg
        other += nc
    rv = S.One
    if cargs:
        rv *= Mul(*[self.func(b, e, evaluate=False) for b in cargs])
    if other:
        rv *= self.func(Mul(*other), e, evaluate=False)
    return rv

.sympy.core.power.Pow.base

def base(self):
    return self._args[0]

.sympy.core.power.Pow.exp

def exp(self):
    return self._args[1]

.sympy.core.power.Pow._eval_expand_power_exp

def _eval_expand_power_exp(self, **hints):
    b = self.base
    e = self.exp
    if e.is_Add and e.is_commutative:
        expr = []
        for x in e.args:
            expr.append(self.func(self.base, x))
        return Mul(*expr)
    return self.func(b, e)

.sympy.core.add.Add.as_numer_denom

def as_numer_denom(self):
    content, expr = self.primitive()
    ncon, dcon = content.as_numer_denom()
    nd = defaultdict(list)
    for f in expr.args:
        ni, di = f.as_numer_denom()
        nd[di].append(ni)
    if len(nd) == 1:
        d, n = nd.popitem()
        return (self.func(*[_keep_coeff(ncon, ni) for ni in n]), _keep_coeff(dcon, d))
    for d, n in nd.items():
        if len(n) == 1:
            nd[d] = n[0]
        else:
            nd[d] = self.func(*n)
    denoms, numers = [list(i) for i in zip(*iter(nd.items()))]
    n, d = (self.func(*[Mul(*denoms[:i] + [numers[i]] + denoms[i + 1:]) for i in range(len(numers))]), Mul(*denoms))
    return (_keep_coeff(ncon, n), _keep_coeff(dcon, d))

.sympy.core.add.Add.primitive

def primitive(self):
    terms = []
    inf = False
    for a in self.args:
        c, m = a.as_coeff_Mul()
        if not c.is_Rational:
            c = S.One
            m = a
        inf = inf or m is S.ComplexInfinity
        terms.append((c.p, c.q, m))
    if not inf:
        ngcd = reduce(igcd, [t[0] for t in terms], 0)
        dlcm = reduce(ilcm, [t[1] for t in terms], 1)
    else:
        ngcd = reduce(igcd, [t[0] for t in terms if t[1]], 0)
        dlcm = reduce(ilcm, [t[1] for t in terms if t[1]], 1)
    if ngcd == dlcm == 1:
        return (S.One, self)
    if not inf:
        for i, (p, q, term) in enumerate(terms):
            terms[i] = _keep_coeff(Rational(p // ngcd * (dlcm // q)), term)
    else:
        for i, (p, q, term) in enumerate(terms):
            if q:
                terms[i] = _keep_coeff(Rational(p // ngcd * (dlcm // q)), term)
            else:
                terms[i] = _keep_coeff(Rational(p, q), term)
    if terms[0].is_Number or terms[0] is S.ComplexInfinity:
        c = terms.pop(0)
    else:
        c = None
    _addsort(terms)
    if c:
        terms.insert(0, c)
    return (Rational(ngcd, dlcm), self._new_rawargs(*terms))

.sympy.core.mul.Mul.as_coeff_Mul

def as_coeff_Mul(self, rational=False):
    coeff, args = (self.args[0], self.args[1:])
    if coeff.is_Number:
        if not rational or coeff.is_Rational:
            if len(args) == 1:
                return (coeff, args[0])
            else:
                return (coeff, self._new_rawargs(*args))
        elif coeff.is_extended_negative:
            return (S.NegativeOne, self._new_rawargs(*(-coeff,) + args))
    return (S.One, self)

.sympy.core.operations.AssocOp._new_rawargs

def _new_rawargs(self, *args, **kwargs):
    if kwargs.pop('reeval', True) and self.is_commutative is False:
        is_commutative = None
    else:
        is_commutative = self.is_commutative
    return self._from_args(args, is_commutative)

.sympy.core.numbers.igcd

def igcd(*args):
    if len(args) < 2:
        raise TypeError('igcd() takes at least 2 arguments (%s given)' % len(args))
    args_temp = [abs(as_int(i)) for i in args]
    if 1 in args_temp:
        return 1
    a = args_temp.pop()
    for b in args_temp:
        a = igcd2(a, b) if b else a
    return a

.sympy.core.numbers.ilcm

def ilcm(*args):
    if len(args) < 2:
        raise TypeError('ilcm() takes at least 2 arguments (%s given)' % len(args))
    if 0 in args:
        return 0
    a = args[0]
    for b in args[1:]:
        a = a // igcd(a, b) * b
    return a

.sympy.core.power.Pow.as_numer_denom

def as_numer_denom(self):
    if not self.is_commutative:
        return (self, S.One)
    base, exp = self.as_base_exp()
    n, d = base.as_numer_denom()
    neg_exp = exp.is_negative
    if not neg_exp and (not (-exp).is_negative):
        neg_exp = _coeff_isneg(exp)
    int_exp = exp.is_integer
    if not (d.is_extended_real or int_exp):
        n = base
        d = S.One
    dnonpos = d.is_nonpositive
    if dnonpos:
        n, d = (-n, -d)
    elif dnonpos is None and (not int_exp):
        n = base
        d = S.One
    if neg_exp:
        n, d = (d, n)
        exp = -exp
    if exp.is_infinite:
        if n is S.One and d is not S.One:
            return (n, self.func(d, exp))
        if n is not S.One and d is S.One:
            return (self.func(n, exp), d)
    return (self.func(n, exp), self.func(d, exp))

.sympy.core.numbers.Integer.__neg__

def __neg__(self):
    return Integer(-self.p)

.sympy.core.numbers.Integer.__abs__

def __abs__(self):
    if self.p >= 0:
        return self
    else:
        return Integer(-self.p)

.sympy.core.add.Add.flatten

def flatten(cls, seq):
    from sympy.calculus.util import AccumBounds
    from sympy.matrices.expressions import MatrixExpr
    from sympy.tensor.tensor import TensExpr
    rv = None
    if len(seq) == 2:
        a, b = seq
        if b.is_Rational:
            a, b = (b, a)
        if a.is_Rational:
            if b.is_Mul:
                rv = ([a, b], [], None)
        if rv:
            if all((s.is_commutative for s in rv[0])):
                return rv
            return ([], rv[0], None)
    terms = {}
    coeff = S.Zero
    order_factors = []
    extra = []
    for o in seq:
        if o.is_Order:
            for o1 in order_factors:
                if o1.contains(o):
                    o = None
                    break
            if o is None:
                continue
            order_factors = [o] + [o1 for o1 in order_factors if not o.contains(o1)]
            continue
        elif o.is_Number:
            if (o is S.NaN or (coeff is S.ComplexInfinity and o.is_finite is False)) and (not extra):
                return ([S.NaN], [], None)
            if coeff.is_Number:
                coeff += o
                if coeff is S.NaN and (not extra):
                    return ([S.NaN], [], None)
            continue
        elif isinstance(o, AccumBounds):
            coeff = o.__add__(coeff)
            continue
        elif isinstance(o, MatrixExpr):
            extra.append(o)
            continue
        elif isinstance(o, TensExpr):
            coeff = o.__add__(coeff) if coeff else o
            continue
        elif o is S.ComplexInfinity:
            if coeff.is_finite is False and (not extra):
                return ([S.NaN], [], None)
            coeff = S.ComplexInfinity
            continue
        elif o.is_Add:
            seq.extend(o.args)
            continue
        elif o.is_Mul:
            c, s = o.as_coeff_Mul()
        elif o.is_Pow:
            b, e = o.as_base_exp()
            if b.is_Number and (e.is_Integer or (e.is_Rational and e.is_negative)):
                seq.append(b ** e)
                continue
            c, s = (S.One, o)
        else:
            c = S.One
            s = o
        if s in terms:
            terms[s] += c
            if terms[s] is S.NaN and (not extra):
                return ([S.NaN], [], None)
        else:
            terms[s] = c
    newseq = []
    noncommutative = False
    for s, c in terms.items():
        if c.is_zero:
            continue
        elif c is S.One:
            newseq.append(s)
        elif s.is_Mul:
            cs = s._new_rawargs(*(c,) + s.args)
            newseq.append(cs)
        elif s.is_Add:
            newseq.append(Mul(c, s, evaluate=False))
        else:
            newseq.append(Mul(c, s))
        noncommutative = noncommutative or not s.is_commutative
    if coeff is S.Infinity:
        newseq = [f for f in newseq if not (f.is_extended_nonnegative or f.is_real)]
    elif coeff is S.NegativeInfinity:
        newseq = [f for f in newseq if not (f.is_extended_nonpositive or f.is_real)]
    if coeff is S.ComplexInfinity:
        newseq = [c for c in newseq if not (c.is_finite and c.is_extended_real is not None)]
    if order_factors:
        newseq2 = []
        for t in newseq:
            for o in order_factors:
                if o.contains(t):
                    t = None
                    break
            if t is not None:
                newseq2.append(t)
        newseq = newseq2 + order_factors
        for o in order_factors:
            if o.contains(coeff):
                coeff = S.Zero
                break
    _addsort(newseq)
    if coeff is not S.Zero:
        newseq.insert(0, coeff)
    if extra:
        newseq += extra
        noncommutative = True
    if noncommutative:
        return ([], newseq, None)
    else:
        return (newseq, [], None)

.sympy.core.numbers.Integer.__add__

def __add__(self, other):
    if global_evaluate[0]:
        if isinstance(other, integer_types):
            return Integer(self.p + other)
        elif isinstance(other, Integer):
            return Integer(self.p + other.p)
        elif isinstance(other, Rational):
            return Rational(self.p * other.q + other.p, other.q, 1)
        return Rational.__add__(self, other)
    else:
        return Add(self, other)

.sympy.core.add._addsort

def _addsort(args):
    args.sort(key=_args_sortkey)

.sympy.core.numbers.Rational._hashable_content

def _hashable_content(self):
    return (self.p, self.q)

.sympy.core.add.Add.as_content_primitive

def as_content_primitive(self, radical=False, clear=True):
    con, prim = self.func(*[_keep_coeff(*a.as_content_primitive(radical=radical, clear=clear)) for a in self.args]).primitive()
    if not clear and (not con.is_Integer) and prim.is_Add:
        con, d = con.as_numer_denom()
        _p = prim / d
        if any((a.as_coeff_Mul()[0].is_Integer for a in _p.args)):
            prim = _p
        else:
            con /= d
    if radical and prim.is_Add:
        args = prim.args
        rads = []
        common_q = None
        for m in args:
            term_rads = defaultdict(list)
            for ai in Mul.make_args(m):
                if ai.is_Pow:
                    b, e = ai.as_base_exp()
                    if e.is_Rational and b.is_Integer:
                        term_rads[e.q].append(abs(int(b)) ** e.p)
            if not term_rads:
                break
            if common_q is None:
                common_q = set(term_rads.keys())
            else:
                common_q = common_q & set(term_rads.keys())
                if not common_q:
                    break
            rads.append(term_rads)
        else:
            for r in rads:
                for q in list(r.keys()):
                    if q not in common_q:
                        r.pop(q)
                for q in r:
                    r[q] = prod(r[q])
            G = []
            for q in common_q:
                g = reduce(igcd, [r[q] for r in rads], 0)
                if g != 1:
                    G.append(g ** Rational(1, q))
            if G:
                G = Mul(*G)
                args = [ai / G for ai in args]
                prim = G * prim.func(*args)
    return (con, prim)

.sympy.core.numbers.Rational.__mul__

def __mul__(self, other):
    if global_evaluate[0]:
        if isinstance(other, Integer):
            return Rational(self.p * other.p, self.q, igcd(other.p, self.q))
        elif isinstance(other, Rational):
            return Rational(self.p * other.p, self.q * other.q, igcd(self.p, other.q) * igcd(self.q, other.p))
        elif isinstance(other, Float):
            return other * self
        else:
            return Number.__mul__(self, other)
    return Number.__mul__(self, other)

.sympy.core.numbers.Number.__mul__

def __mul__(self, other):
    if isinstance(other, Number) and global_evaluate[0]:
        if other is S.NaN:
            return S.NaN
        elif other is S.Infinity:
            if self.is_zero:
                return S.NaN
            elif self.is_positive:
                return S.Infinity
            else:
                return S.NegativeInfinity
        elif other is S.NegativeInfinity:
            if self.is_zero:
                return S.NaN
            elif self.is_positive:
                return S.NegativeInfinity
            else:
                return S.Infinity
    elif isinstance(other, Tuple):
        return NotImplemented
    return AtomicExpr.__mul__(self, other)

.sympy.core.decorators._SympifyWrapper._func

def _func(self, other):
    if not hasattr(other, '_op_priority'):
        try:
            other = sympify(other, strict=True)
        except SympifyError:
            return retval
    if not isinstance(other, expectedcls):
        return retval
    return func(self, other)

.sympy.core.decorators.binary_op_wrapper

def binary_op_wrapper(self, other):
    if hasattr(other, '_op_priority'):
        if other._op_priority > self._op_priority:
            f = getattr(other, method_name, None)
            if f is not None:
                return f(self)
    return func(self, other)

.sympy.core.expr.Expr.__mul__

def __mul__(self, other):
    return Mul(self, other)

.sympy.core.power.Pow.as_content_primitive

def as_content_primitive(self, radical=False, clear=True):
    b, e = self.as_base_exp()
    b = _keep_coeff(*b.as_content_primitive(radical=radical, clear=clear))
    ce, pe = e.as_content_primitive(radical=radical, clear=clear)
    if b.is_Rational:
        h, t = pe.as_coeff_Add()
        if h.is_Rational:
            ceh = ce * h
            c = self.func(b, ceh)
            r = S.Zero
            if not c.is_Rational:
                iceh, r = divmod(ceh.p, ceh.q)
                c = self.func(b, iceh)
            return (c, self.func(b, _keep_coeff(ce, t + r / ce / ceh.q)))
    e = _keep_coeff(ce, pe)
    if e.is_Rational and b.is_Mul:
        h, t = b.as_content_primitive(radical=radical, clear=clear)
        c, m = self.func(h, e).as_coeff_Mul()
        m, me = m.as_base_exp()
        if m is S.One or me == e:
            return (c, self.func(_keep_coeff(m, t), e))
    return (S.One, self.func(b, e))

.sympy.core.expr.Expr.extract_multiplicatively

def extract_multiplicatively(self, c):
    from .add import _unevaluated_Add
    c = sympify(c)
    if self is S.NaN:
        return None
    if c is S.One:
        return self
    elif c == self:
        return S.One
    if c.is_Add:
        cc, pc = c.primitive()
        if cc is not S.One:
            c = Mul(cc, pc, evaluate=False)
    if c.is_Mul:
        a, b = c.as_two_terms()
        x = self.extract_multiplicatively(a)
        if x is not None:
            return x.extract_multiplicatively(b)
        else:
            return x
    quotient = self / c
    if self.is_Number:
        if self is S.Infinity:
            if c.is_positive:
                return S.Infinity
        elif self is S.NegativeInfinity:
            if c.is_negative:
                return S.Infinity
            elif c.is_positive:
                return S.NegativeInfinity
        elif self is S.ComplexInfinity:
            if not c.is_zero:
                return S.ComplexInfinity
        elif self.is_Integer:
            if not quotient.is_Integer:
                return None
            elif self.is_positive and quotient.is_negative:
                return None
            else:
                return quotient
        elif self.is_Rational:
            if not quotient.is_Rational:
                return None
            elif self.is_positive and quotient.is_negative:
                return None
            else:
                return quotient
        elif self.is_Float:
            if not quotient.is_Float:
                return None
            elif self.is_positive and quotient.is_negative:
                return None
            else:
                return quotient
    elif self.is_NumberSymbol or self.is_Symbol or self is S.ImaginaryUnit:
        if quotient.is_Mul and len(quotient.args) == 2:
            if quotient.args[0].is_Integer and quotient.args[0].is_positive and (quotient.args[1] == self):
                return quotient
        elif quotient.is_Integer and c.is_Number:
            return quotient
    elif self.is_Add:
        cs, ps = self.primitive()
        if c.is_Number and c is not S.NegativeOne:
            if cs is not S.One:
                if c.is_negative:
                    xc = -cs.extract_multiplicatively(-c)
                else:
                    xc = cs.extract_multiplicatively(c)
                if xc is not None:
                    return xc * ps
            return
        if c == ps:
            return cs
        newargs = []
        for arg in ps.args:
            newarg = arg.extract_multiplicatively(c)
            if newarg is None:
                return
            newargs.append(newarg)
        if cs is not S.One:
            args = [cs * t for t in newargs]
            return _unevaluated_Add(*args)
        else:
            return Add._from_args(newargs)
    elif self.is_Mul:
        args = list(self.args)
        for i, arg in enumerate(args):
            newarg = arg.extract_multiplicatively(c)
            if newarg is not None:
                args[i] = newarg
                return Mul(*args)
    elif self.is_Pow:
        if c.is_Pow and c.base == self.base:
            new_exp = self.exp.extract_additively(c.exp)
            if new_exp is not None:
                return self.base ** new_exp
        elif c == self.base:
            new_exp = self.exp.extract_additively(1)
            if new_exp is not None:
                return self.base ** new_exp

.sympy.core.mul.Mul.as_base_exp

def as_base_exp(self):
    e1 = None
    bases = []
    nc = 0
    for m in self.args:
        b, e = m.as_base_exp()
        if not b.is_commutative:
            nc += 1
        if e1 is None:
            e1 = e
        elif e != e1 or nc > 1:
            return (self, S.One)
        bases.append(b)
    return (self.func(*bases), e1)

.sympy.core.exprtools.gcd_terms

def gcd_terms(terms, isprimitive=False, clear=True, fraction=True):

    def mask(terms):
        args = [(a, []) if a.is_commutative else a.args_cnc() for a in terms]
        reps = []
        for i, (c, nc) in enumerate(args):
            if nc:
                nc = Mul(*nc)
                d = Dummy()
                reps.append((d, nc))
                c.append(d)
                args[i] = Mul(*c)
            else:
                args[i] = c
        return (args, dict(reps))
    isadd = isinstance(terms, Add)
    addlike = isadd or (not isinstance(terms, Basic) and is_sequence(terms, include=set) and (not isinstance(terms, Dict)))
    if addlike:
        if isadd:
            terms = list(terms.args)
        else:
            terms = sympify(terms)
        terms, reps = mask(terms)
        cont, numer, denom = _gcd_terms(terms, isprimitive, fraction)
        numer = numer.xreplace(reps)
        coeff, factors = cont.as_coeff_Mul()
        if not clear:
            c, _coeff = coeff.as_coeff_Mul()
            if not c.is_Integer and (not clear) and numer.is_Add:
                n, d = c.as_numer_denom()
                _numer = numer / d
                if any((a.as_coeff_Mul()[0].is_Integer for a in _numer.args)):
                    numer = _numer
                    coeff = n * _coeff
        return _keep_coeff(coeff, factors * numer / denom, clear=clear)
    if not isinstance(terms, Basic):
        return terms
    if terms.is_Atom:
        return terms
    if terms.is_Mul:
        c, args = terms.as_coeff_mul()
        return _keep_coeff(c, Mul(*[gcd_terms(i, isprimitive, clear, fraction) for i in args]), clear=clear)

    def handle(a):
        if not isinstance(a, Expr):
            if isinstance(a, Basic):
                return a.func(*[handle(i) for i in a.args])
            return type(a)([handle(i) for i in a])
        return gcd_terms(a, isprimitive, clear, fraction)
    if isinstance(terms, Dict):
        return Dict(*[(k, handle(v)) for k, v in terms.args])
    return terms.func(*[handle(i) for i in terms.args])

.sympy.core.exprtools.mask

def mask(terms):
    args = [(a, []) if a.is_commutative else a.args_cnc() for a in terms]
    reps = []
    for i, (c, nc) in enumerate(args):
        if nc:
            nc = Mul(*nc)
            d = Dummy()
            reps.append((d, nc))
            c.append(d)
            args[i] = Mul(*c)
        else:
            args[i] = c
    return (args, dict(reps))

.sympy.core.exprtools._gcd_terms

def _gcd_terms(terms, isprimitive=False, fraction=True):
    if isinstance(terms, Basic) and (not isinstance(terms, Tuple)):
        terms = Add.make_args(terms)
    terms = list(map(Term, [t for t in terms if t]))
    if len(terms) == 0:
        return (S.Zero, S.Zero, S.One)
    if len(terms) == 1:
        cont = terms[0].coeff
        numer = terms[0].numer.as_expr()
        denom = terms[0].denom.as_expr()
    else:
        cont = terms[0]
        for term in terms[1:]:
            cont = cont.gcd(term)
        for i, term in enumerate(terms):
            terms[i] = term.quo(cont)
        if fraction:
            denom = terms[0].denom
            for term in terms[1:]:
                denom = denom.lcm(term.denom)
            numers = []
            for term in terms:
                numer = term.numer.mul(denom.quo(term.denom))
                numers.append(term.coeff * numer.as_expr())
        else:
            numers = [t.as_expr() for t in terms]
            denom = Term(S.One).numer
        cont = cont.as_expr()
        numer = Add(*numers)
        denom = denom.as_expr()
    if not isprimitive and numer.is_Add:
        _cont, numer = numer.primitive()
        cont *= _cont
    return (cont, numer, denom)

.sympy.core.exprtools.Term.__init__

def __init__(self, term, numer=None, denom=None):
    if numer is None and denom is None:
        if not term.is_commutative:
            raise NonCommutativeExpression('commutative expression expected')
        coeff, factors = term.as_coeff_mul()
        numer, denom = (defaultdict(int), defaultdict(int))
        for factor in factors:
            base, exp = decompose_power(factor)
            if base.is_Add:
                cont, base = base.primitive()
                coeff *= cont ** exp
            if exp > 0:
                numer[base] += exp
            else:
                denom[base] += -exp
        numer = Factors(numer)
        denom = Factors(denom)
    else:
        coeff = term
        if numer is None:
            numer = Factors()
        if denom is None:
            denom = Factors()
    self.coeff = coeff
    self.numer = numer
    self.denom = denom

.sympy.core.numbers.Number.as_coeff_mul

def as_coeff_mul(self, *deps, **kwargs):
    if self.is_Rational or not kwargs.pop('rational', True):
        return (self, tuple())
    elif self.is_negative:
        return (S.NegativeOne, (-self,))
    return (S.One, (self,))

.sympy.core.exprtools.Factors.__init__

def __init__(self, factors=None):
    if isinstance(factors, (SYMPY_INTS, float)):
        factors = S(factors)
    if isinstance(factors, Factors):
        factors = factors.factors.copy()
    elif factors is None or factors is S.One:
        factors = {}
    elif factors is S.Zero or factors == 0:
        factors = {S.Zero: S.One}
    elif isinstance(factors, Number):
        n = factors
        factors = {}
        if n < 0:
            factors[S.NegativeOne] = S.One
            n = -n
        if n is not S.One:
            if n.is_Float or n.is_Integer or n is S.Infinity:
                factors[n] = S.One
            elif n.is_Rational:
                if n.p != 1:
                    factors[Integer(n.p)] = S.One
                factors[Integer(n.q)] = S.NegativeOne
            else:
                raise ValueError('Expected Float|Rational|Integer, not %s' % n)
    elif isinstance(factors, Basic) and (not factors.args):
        factors = {factors: S.One}
    elif isinstance(factors, Expr):
        c, nc = factors.args_cnc()
        i = c.count(I)
        for _ in range(i):
            c.remove(I)
        factors = dict(Mul._from_args(c).as_powers_dict())
        for f in list(factors.keys()):
            if isinstance(f, Rational) and (not isinstance(f, Integer)):
                p, q = (Integer(f.p), Integer(f.q))
                factors[p] = (factors[p] if p in factors else S.Zero) + factors[f]
                factors[q] = (factors[q] if q in factors else S.Zero) - factors[f]
                factors.pop(f)
        if i:
            factors[I] = S.One * i
        if nc:
            factors[Mul(*nc, evaluate=False)] = S.One
    else:
        factors = factors.copy()
        handle = []
        for k in factors:
            if k is I or k in (-1, 1):
                handle.append(k)
        if handle:
            i1 = S.One
            for k in handle:
                if not _isnumber(factors[k]):
                    continue
                i1 *= k ** factors.pop(k)
            if i1 is not S.One:
                for a in i1.args if i1.is_Mul else [i1]:
                    if a is S.NegativeOne:
                        factors[a] = S.One
                    elif a is I:
                        factors[I] = S.One
                    elif a.is_Pow:
                        if S.NegativeOne not in factors:
                            factors[S.NegativeOne] = S.Zero
                        factors[S.NegativeOne] += a.exp
                    elif a == 1:
                        factors[a] = S.One
                    elif a == -1:
                        factors[-a] = S.One
                        factors[S.NegativeOne] = S.One
                    else:
                        raise ValueError('unexpected factor in i1: %s' % a)
    self.factors = factors
    keys = getattr(factors, 'keys', None)
    if keys is None:
        raise TypeError('expecting Expr or dictionary')
    self.gens = frozenset(keys())

.sympy.core.mul.Mul.as_coeff_mul

def as_coeff_mul(self, *deps, **kwargs):
    if deps:
        from sympy.utilities.iterables import sift
        l1, l2 = sift(self.args, lambda x: x.has(*deps), binary=True)
        return (self._new_rawargs(*l2), tuple(l1))
    rational = kwargs.pop('rational', True)
    args = self.args
    if args[0].is_Number:
        if not rational or args[0].is_Rational:
            return (args[0], args[1:])
        elif args[0].is_extended_negative:
            return (S.NegativeOne, (-args[0],) + args[1:])
    return (S.One, args)

.sympy.core.exprtools.Term.gcd

def gcd(self, other):
    return Term(self.coeff.gcd(other.coeff), self.numer.gcd(other.numer), self.denom.gcd(other.denom))

.sympy.core.numbers.Rational.gcd

def gcd(self, other):
    if isinstance(other, Rational):
        if other == S.Zero:
            return other
        return Rational(Integer(igcd(self.p, other.p)), Integer(ilcm(self.q, other.q)))
    return Number.gcd(self, other)

.sympy.core.exprtools.Factors.gcd

def gcd(self, other):
    if not isinstance(other, Factors):
        other = Factors(other)
        if other.is_zero:
            return Factors(self.factors)
    factors = {}
    for factor, exp in self.factors.items():
        factor, exp = (sympify(factor), sympify(exp))
        if factor in other.factors:
            lt = (exp - other.factors[factor]).is_negative
            if lt == True:
                factors[factor] = exp
            elif lt == False:
                factors[factor] = other.factors[factor]
    return Factors(factors)

