.sympy.core.mul.Mul.matches

def matches(self, expr, repl_dict={}, old=False):
    expr = sympify(expr)
    if self.is_commutative and expr.is_commutative:
        return AssocOp._matches_commutative(self, expr, repl_dict, old)
    elif self.is_commutative is not expr.is_commutative:
        return None
    c1, nc1 = self.args_cnc()
    c2, nc2 = expr.args_cnc()
    c1, c2 = [c or [1] for c in [c1, c2]]
    comm_mul_self = Mul(*c1)
    comm_mul_expr = Mul(*c2)
    repl_dict = comm_mul_self.matches(comm_mul_expr, repl_dict, old)
    if repl_dict is None and c1 != c2:
        return None
    nc1 = Mul._matches_expand_pows(nc1)
    nc2 = Mul._matches_expand_pows(nc2)
    repl_dict = Mul._matches_noncomm(nc1, nc2, repl_dict)
    return repl_dict or None

.sympy.core.operations.AssocOp._matches_commutative

def _matches_commutative(self, expr, repl_dict={}, old=False):
    from .expr import Add, Expr
    from sympy import Mul
    if isinstance(self, Expr) and (not isinstance(expr, Expr)):
        return None
    if self == expr:
        return repl_dict
    d = self._matches_simple(expr, repl_dict)
    if d is not None:
        return d
    from .function import WildFunction
    from .symbol import Wild
    wild_part, exact_part = sift(self.args, lambda p: p.has(Wild, WildFunction) and (not expr.has(p)), binary=True)
    if not exact_part:
        wild_part = list(ordered(wild_part))
    else:
        exact = self._new_rawargs(*exact_part)
        free = expr.free_symbols
        if free and exact.free_symbols - free:
            return None
        newexpr = self._combine_inverse(expr, exact)
        if not old and (expr.is_Add or expr.is_Mul):
            if newexpr.count_ops() > expr.count_ops():
                return None
        newpattern = self._new_rawargs(*wild_part)
        return newpattern.matches(newexpr, repl_dict)
    i = 0
    saw = set()
    while expr not in saw:
        saw.add(expr)
        expr_list = (self.identity,) + tuple(ordered(self.make_args(expr)))
        for last_op in reversed(expr_list):
            for w in reversed(wild_part):
                d1 = w.matches(last_op, repl_dict)
                if d1 is not None:
                    d2 = self.xreplace(d1).matches(expr, d1)
                    if d2 is not None:
                        return d2
        if i == 0:
            if self.is_Mul:
                if expr.is_Pow and expr.exp.is_Integer:
                    if expr.exp > 0:
                        expr = Mul(*[expr.base, expr.base ** (expr.exp - 1)], evaluate=False)
                    else:
                        expr = Mul(*[1 / expr.base, expr.base ** (expr.exp + 1)], evaluate=False)
                    i += 1
                    continue
            elif self.is_Add:
                c, e = expr.as_coeff_Mul()
                if abs(c) > 1:
                    if c > 0:
                        expr = Add(*[e, (c - 1) * e], evaluate=False)
                    else:
                        expr = Add(*[-e, (c + 1) * e], evaluate=False)
                    i += 1
                    continue
                from sympy.simplify.radsimp import collect
                was = expr
                did = set()
                for w in reversed(wild_part):
                    c, w = w.as_coeff_mul(Wild)
                    free = c.free_symbols - did
                    if free:
                        did.update(free)
                        expr = collect(expr, free)
                if expr != was:
                    i += 0
                    continue
            break
    return

.sympy.core.mul.Mul._matches_simple

def _matches_simple(self, expr, repl_dict):
    coeff, terms = self.as_coeff_Mul()
    terms = Mul.make_args(terms)
    if len(terms) == 1:
        newexpr = self.__class__._combine_inverse(expr, coeff)
        return terms[0].matches(newexpr, repl_dict)
    return

.sympy.core.compatibility._nodes

def _nodes(e):
    from .basic import Basic
    if isinstance(e, Basic):
        return e.count(Basic)
    elif iterable(e):
        return 1 + sum((_nodes(ei) for ei in e))
    elif isinstance(e, dict):
        return 1 + sum((_nodes(k) + _nodes(v) for k, v in e.items()))
    else:
        return 1

.sympy.core.basic.Basic.count

def count(self, query):
    query = _make_find_query(query)
    return sum((bool(query(sub)) for sub in preorder_traversal(self)))

.sympy.core.basic._make_find_query

def _make_find_query(query):
    try:
        query = sympify(query)
    except SympifyError:
        pass
    if isinstance(query, type):
        return lambda expr: isinstance(expr, query)
    elif isinstance(query, Basic):
        return lambda expr: expr.match(query) is not None
    return query

.sympy.core.power.Pow.matches

def matches(self, expr, repl_dict={}, old=False):
    expr = _sympify(expr)
    if expr is S.One:
        d = repl_dict.copy()
        d = self.exp.matches(S.Zero, d)
        if d is not None:
            return d
    if not isinstance(expr, Expr):
        return None
    b, e = expr.as_base_exp()
    sb, se = self.as_base_exp()
    if sb.is_Symbol and se.is_Integer and expr:
        if e.is_rational:
            return sb.matches(b ** (e / se), repl_dict)
        return sb.matches(expr ** (1 / se), repl_dict)
    d = repl_dict.copy()
    d = self.base.matches(b, d)
    if d is None:
        return None
    d = self.exp.xreplace(d).matches(e, d)
    if d is None:
        return Expr.matches(self, expr, repl_dict)
    return d

.sympy.core.symbol.Wild.matches

def matches(self, expr, repl_dict={}, old=False):
    if any((expr.has(x) for x in self.exclude)):
        return None
    if any((not f(expr) for f in self.properties)):
        return None
    repl_dict = repl_dict.copy()
    repl_dict[self] = expr
    return repl_dict

.sympy.core.basic.Atom.xreplace

def xreplace(self, rule, hack2=False):
    return rule.get(self, self)

.sympy.core.mul.Mul._combine_inverse

def _combine_inverse(lhs, rhs):
    from .symbol import Dummy
    if lhs == rhs:
        return S.One

    def check(l, r):
        if l.is_Float and r.is_comparable:
            return l.__add__(0) == r.evalf().__add__(0)
        return False
    if check(lhs, rhs) or check(rhs, lhs):
        return S.One
    if any((i.is_Pow or i.is_Mul for i in (lhs, rhs))):
        d = Dummy('I')
        _i = {S.ImaginaryUnit: d}
        i_ = {d: S.ImaginaryUnit}
        a = lhs.xreplace(_i).as_powers_dict()
        b = rhs.xreplace(_i).as_powers_dict()
        blen = len(b)
        for bi in tuple(b.keys()):
            if bi in a:
                a[bi] -= b.pop(bi)
                if not a[bi]:
                    a.pop(bi)
        if len(b) != blen:
            lhs = Mul(*[k ** v for k, v in a.items()]).xreplace(i_)
            rhs = Mul(*[k ** v for k, v in b.items()]).xreplace(i_)
    return lhs / rhs

.sympy.core.mul.Mul.check

def check(l, r):
    if l.is_Float and r.is_comparable:
        return l.__add__(0) == r.evalf().__add__(0)
    return False

.sympy.core.mul.Mul.as_powers_dict

def as_powers_dict(self):
    d = defaultdict(int)
    for term in self.args:
        for b, e in term.as_powers_dict().items():
            d[b] += e
    return d

.sympy.core.expr.Expr.as_powers_dict

def as_powers_dict(self):
    d = defaultdict(int)
    d.update(dict([self.as_base_exp()]))
    return d

.sympy.core.expr.Expr.count_ops

def count_ops(self, visual=None):
    from .function import count_ops
    return count_ops(self, visual)

.sympy.core.function.count_ops

def count_ops(expr, visual=False):
    from sympy import Integral, Symbol
    from sympy.core.relational import Relational
    from sympy.simplify.radsimp import fraction
    from sympy.logic.boolalg import BooleanFunction
    from sympy.utilities.misc import func_name
    expr = sympify(expr)
    if isinstance(expr, Expr) and (not expr.is_Relational):
        ops = []
        args = [expr]
        NEG = Symbol('NEG')
        DIV = Symbol('DIV')
        SUB = Symbol('SUB')
        ADD = Symbol('ADD')
        while args:
            a = args.pop()
            if a.is_Rational:
                if a is not S.One:
                    if a.p < 0:
                        ops.append(NEG)
                    if a.q != 1:
                        ops.append(DIV)
                    continue
            elif a.is_Mul or a.is_MatMul:
                if _coeff_isneg(a):
                    ops.append(NEG)
                    if a.args[0] is S.NegativeOne:
                        a = a.as_two_terms()[1]
                    else:
                        a = -a
                n, d = fraction(a)
                if n.is_Integer:
                    ops.append(DIV)
                    if n < 0:
                        ops.append(NEG)
                    args.append(d)
                    continue
                elif d is not S.One:
                    if not d.is_Integer:
                        args.append(d)
                    ops.append(DIV)
                    args.append(n)
                    continue
            elif a.is_Add or a.is_MatAdd:
                aargs = list(a.args)
                negs = 0
                for i, ai in enumerate(aargs):
                    if _coeff_isneg(ai):
                        negs += 1
                        args.append(-ai)
                        if i > 0:
                            ops.append(SUB)
                    else:
                        args.append(ai)
                        if i > 0:
                            ops.append(ADD)
                if negs == len(aargs):
                    ops.append(NEG)
                elif _coeff_isneg(aargs[0]):
                    ops.append(SUB - ADD)
                continue
            if a.is_Pow and a.exp is S.NegativeOne:
                ops.append(DIV)
                args.append(a.base)
                continue
            if a.is_Mul or a.is_Pow or a.is_Function or isinstance(a, Derivative) or isinstance(a, Integral):
                o = Symbol(a.func.__name__.upper())
                if a.is_Mul or isinstance(a, LatticeOp):
                    ops.append(o * (len(a.args) - 1))
                else:
                    ops.append(o)
            if not a.is_Symbol:
                args.extend(a.args)
    elif isinstance(expr, Dict):
        ops = [count_ops(k, visual=visual) + count_ops(v, visual=visual) for k, v in expr.items()]
    elif iterable(expr):
        ops = [count_ops(i, visual=visual) for i in expr]
    elif isinstance(expr, (Relational, BooleanFunction)):
        ops = []
        for arg in expr.args:
            ops.append(count_ops(arg, visual=True))
        o = Symbol(func_name(expr, short=True).upper())
        ops.append(o)
    elif not isinstance(expr, Basic):
        ops = []
    elif not isinstance(expr, Basic):
        raise TypeError('Invalid type of expr')
    else:
        ops = []
        args = [expr]
        while args:
            a = args.pop()
            if a.args:
                o = Symbol(a.func.__name__.upper())
                if a.is_Boolean:
                    ops.append(o * (len(a.args) - 1))
                else:
                    ops.append(o)
                args.extend(a.args)
    if not ops:
        if visual:
            return S.Zero
        return 0
    ops = Add(*ops)
    if visual:
        return ops
    if ops.is_Number:
        return int(ops)
    return sum((int((a.args or [1])[0]) for a in Add.make_args(ops)))

.sympy.solvers.solveset._solve_as_rational

def _solve_as_rational(f, symbol, domain):
    f = together(f, deep=True)
    g, h = fraction(f)
    if not h.has(symbol):
        try:
            return _solve_as_poly(g, symbol, domain)
        except NotImplementedError:
            return ConditionSet(symbol, Eq(f, 0), domain)
        except CoercionFailed:
            return S.EmptySet
    else:
        valid_solns = _solveset(g, symbol, domain)
        invalid_solns = _solveset(h, symbol, domain)
        return valid_solns - invalid_solns

.sympy.core.numbers.Integer._eval_power

def _eval_power(self, expt):
    from sympy.ntheory.factor_ import perfect_power
    if expt is S.Infinity:
        if self.p > S.One:
            return S.Infinity
        return S.Infinity + S.ImaginaryUnit * S.Infinity
    if expt is S.NegativeInfinity:
        return Rational(1, self) ** S.Infinity
    if not isinstance(expt, Number):
        if self.is_negative and expt.is_even:
            return (-self) ** expt
    if isinstance(expt, Float):
        return super(Integer, self)._eval_power(expt)
    if not isinstance(expt, Rational):
        return
    if expt is S.Half and self.is_negative:
        return S.ImaginaryUnit * Pow(-self, expt)
    if expt.is_negative:
        ne = -expt
        if self.is_negative:
            return S.NegativeOne ** expt * Rational(1, -self) ** ne
        else:
            return Rational(1, self.p) ** ne
    x, xexact = integer_nthroot(abs(self.p), expt.q)
    if xexact:
        result = Integer(x ** abs(expt.p))
        if self.is_negative:
            result *= S.NegativeOne ** expt
        return result
    b_pos = int(abs(self.p))
    p = perfect_power(b_pos)
    if p is not False:
        dict = {p[0]: p[1]}
    else:
        dict = Integer(b_pos).factors(limit=2 ** 15)
    out_int = 1
    out_rad = 1
    sqr_int = 1
    sqr_gcd = 0
    sqr_dict = {}
    for prime, exponent in dict.items():
        exponent *= expt.p
        div_e, div_m = divmod(exponent, expt.q)
        if div_e > 0:
            out_int *= prime ** div_e
        if div_m > 0:
            g = igcd(div_m, expt.q)
            if g != 1:
                out_rad *= Pow(prime, Rational(div_m // g, expt.q // g))
            else:
                sqr_dict[prime] = div_m
    for p, ex in sqr_dict.items():
        if sqr_gcd == 0:
            sqr_gcd = ex
        else:
            sqr_gcd = igcd(sqr_gcd, ex)
            if sqr_gcd == 1:
                break
    for k, v in sqr_dict.items():
        sqr_int *= k ** (v // sqr_gcd)
    if sqr_int == b_pos and out_int == 1 and (out_rad == 1):
        result = None
    else:
        result = out_int * out_rad * Pow(sqr_int, Rational(sqr_gcd, expt.q))
        if self.is_negative:
            result *= Pow(S.NegativeOne, expt)
    return result

.sympy.solvers.solveset._solve_as_poly

def _solve_as_poly(f, symbol, domain=S.Complexes):
    result = None
    if f.is_polynomial(symbol):
        solns = roots(f, symbol, cubics=True, quartics=True, quintics=True, domain='EX')
        num_roots = sum(solns.values())
        if degree(f, symbol) <= num_roots:
            result = FiniteSet(*solns.keys())
        else:
            poly = Poly(f, symbol)
            solns = poly.all_roots()
            if poly.degree() <= len(solns):
                result = FiniteSet(*solns)
            else:
                result = ConditionSet(symbol, Eq(f, 0), domain)
    else:
        poly = Poly(f)
        if poly is None:
            result = ConditionSet(symbol, Eq(f, 0), domain)
        gens = [g for g in poly.gens if g.has(symbol)]
        if len(gens) == 1:
            poly = Poly(poly, gens[0])
            gen = poly.gen
            deg = poly.degree()
            poly = Poly(poly.as_expr(), poly.gen, composite=True)
            poly_solns = FiniteSet(*roots(poly, cubics=True, quartics=True, quintics=True).keys())
            if len(poly_solns) < deg:
                result = ConditionSet(symbol, Eq(f, 0), domain)
            if gen != symbol:
                y = Dummy('y')
                inverter = invert_real if domain.is_subset(S.Reals) else invert_complex
                lhs, rhs_s = inverter(gen, y, symbol)
                if lhs == symbol:
                    result = Union(*[rhs_s.subs(y, s) for s in poly_solns])
                else:
                    result = ConditionSet(symbol, Eq(f, 0), domain)
        else:
            result = ConditionSet(symbol, Eq(f, 0), domain)
    if result is not None:
        if isinstance(result, FiniteSet):
            if all([s.atoms(Symbol, AppliedUndef) == set() and (not isinstance(s, RootOf)) for s in result]):
                s = Dummy('s')
                result = imageset(Lambda(s, expand_complex(s)), result)
        if isinstance(result, FiniteSet):
            result = result.intersection(domain)
        return result
    else:
        return ConditionSet(symbol, Eq(f, 0), domain)

.sympy.polys.polyroots.roots

def roots(f, *gens, **flags):
    from sympy.polys.polytools import to_rational_coeffs
    flags = dict(flags)
    auto = flags.pop('auto', True)
    cubics = flags.pop('cubics', True)
    trig = flags.pop('trig', False)
    quartics = flags.pop('quartics', True)
    quintics = flags.pop('quintics', False)
    multiple = flags.pop('multiple', False)
    filter = flags.pop('filter', None)
    predicate = flags.pop('predicate', None)
    if isinstance(f, list):
        if gens:
            raise ValueError('redundant generators given')
        x = Dummy('x')
        poly, i = ({}, len(f) - 1)
        for coeff in f:
            poly[i], i = (sympify(coeff), i - 1)
        f = Poly(poly, x, field=True)
    else:
        try:
            f = Poly(f, *gens, **flags)
            if f.length == 2 and f.degree() != 1:
                n = f.degree()
                npow_bases = []
                others = []
                expr = f.as_expr()
                con = expr.as_independent(*gens)[0]
                for p in Mul.make_args(con):
                    if p.is_Pow and (not p.exp % n):
                        npow_bases.append(p.base ** (p.exp / n))
                    else:
                        others.append(p)
                    if npow_bases:
                        b = Mul(*npow_bases)
                        B = Dummy()
                        d = roots(Poly(expr - con + B ** n * Mul(*others), *gens, **flags), *gens, **flags)
                        rv = {}
                        for k, v in d.items():
                            rv[k.subs(B, b)] = v
                        return rv
        except GeneratorsNeeded:
            if multiple:
                return []
            else:
                return {}
        if f.is_multivariate:
            raise PolynomialError('multivariate polynomials are not supported')

    def _update_dict(result, currentroot, k):
        if currentroot in result:
            result[currentroot] += k
        else:
            result[currentroot] = k

    def _try_decompose(f):
        factors, roots = (f.decompose(), [])
        for currentroot in _try_heuristics(factors[0]):
            roots.append(currentroot)
        for currentfactor in factors[1:]:
            previous, roots = (list(roots), [])
            for currentroot in previous:
                g = currentfactor - Poly(currentroot, f.gen)
                for currentroot in _try_heuristics(g):
                    roots.append(currentroot)
        return roots

    def _try_heuristics(f):
        if f.is_ground:
            return []
        if f.is_monomial:
            return [S.Zero] * f.degree()
        if f.length() == 2:
            if f.degree() == 1:
                return list(map(cancel, roots_linear(f)))
            else:
                return roots_binomial(f)
        result = []
        for i in [-1, 1]:
            if not f.eval(i):
                f = f.quo(Poly(f.gen - i, f.gen))
                result.append(i)
                break
        n = f.degree()
        if n == 1:
            result += list(map(cancel, roots_linear(f)))
        elif n == 2:
            result += list(map(cancel, roots_quadratic(f)))
        elif f.is_cyclotomic:
            result += roots_cyclotomic(f)
        elif n == 3 and cubics:
            result += roots_cubic(f, trig=trig)
        elif n == 4 and quartics:
            result += roots_quartic(f)
        elif n == 5 and quintics:
            result += roots_quintic(f)
        return result
    (k,), f = f.terms_gcd()
    if not k:
        zeros = {}
    else:
        zeros = {S.Zero: k}
    coeff, f = preprocess_roots(f)
    if auto and f.get_domain().is_Ring:
        f = f.to_field()
    rescale_x = None
    translate_x = None
    result = {}
    if not f.is_ground:
        dom = f.get_domain()
        if not dom.is_Exact and dom.is_Numerical:
            for r in f.nroots():
                _update_dict(result, r, 1)
        elif f.degree() == 1:
            result[roots_linear(f)[0]] = 1
        elif f.length() == 2:
            roots_fun = roots_quadratic if f.degree() == 2 else roots_binomial
            for r in roots_fun(f):
                _update_dict(result, r, 1)
        else:
            _, factors = Poly(f.as_expr()).factor_list()
            if len(factors) == 1 and f.degree() == 2:
                for r in roots_quadratic(f):
                    _update_dict(result, r, 1)
            elif len(factors) == 1 and factors[0][1] == 1:
                if f.get_domain().is_EX:
                    res = to_rational_coeffs(f)
                    if res:
                        if res[0] is None:
                            translate_x, f = res[2:]
                        else:
                            rescale_x, f = (res[1], res[-1])
                        result = roots(f)
                        if not result:
                            for currentroot in _try_decompose(f):
                                _update_dict(result, currentroot, 1)
                    else:
                        for r in _try_heuristics(f):
                            _update_dict(result, r, 1)
                else:
                    for currentroot in _try_decompose(f):
                        _update_dict(result, currentroot, 1)
            else:
                for currentfactor, k in factors:
                    for r in _try_heuristics(Poly(currentfactor, f.gen, field=True)):
                        _update_dict(result, r, k)
    if coeff is not S.One:
        _result, result = (result, {})
        for currentroot, k in _result.items():
            result[coeff * currentroot] = k
    if filter not in [None, 'C']:
        handlers = {'Z': lambda r: r.is_Integer, 'Q': lambda r: r.is_Rational, 'R': lambda r: all((a.is_real for a in r.as_numer_denom())), 'I': lambda r: r.is_imaginary}
        try:
            query = handlers[filter]
        except KeyError:
            raise ValueError('Invalid filter: %s' % filter)
        for zero in dict(result).keys():
            if not query(zero):
                del result[zero]
    if predicate is not None:
        for zero in dict(result).keys():
            if not predicate(zero):
                del result[zero]
    if rescale_x:
        result1 = {}
        for k, v in result.items():
            result1[k * rescale_x] = v
        result = result1
    if translate_x:
        result1 = {}
        for k, v in result.items():
            result1[k + translate_x] = v
        result = result1
    result.update(zeros)
    if not multiple:
        return result
    else:
        zeros = []
        for zero in ordered(result):
            zeros.extend([zero] * result[zero])
        return zeros

.sympy.polys.polyoptions.Domain.preprocess

def preprocess(cls, domain):
    if isinstance(domain, sympy.polys.domains.Domain):
        return domain
    elif hasattr(domain, 'to_domain'):
        return domain.to_domain()
    elif isinstance(domain, string_types):
        if domain in ['Z', 'ZZ']:
            return sympy.polys.domains.ZZ
        if domain in ['Q', 'QQ']:
            return sympy.polys.domains.QQ
        if domain == 'EX':
            return sympy.polys.domains.EX
        r = cls._re_realfield.match(domain)
        if r is not None:
            _, _, prec = r.groups()
            if prec is None:
                return sympy.polys.domains.RR
            else:
                return sympy.polys.domains.RealField(int(prec))
        r = cls._re_complexfield.match(domain)
        if r is not None:
            _, _, prec = r.groups()
            if prec is None:
                return sympy.polys.domains.CC
            else:
                return sympy.polys.domains.ComplexField(int(prec))
        r = cls._re_finitefield.match(domain)
        if r is not None:
            return sympy.polys.domains.FF(int(r.groups()[1]))
        r = cls._re_polynomial.match(domain)
        if r is not None:
            ground, gens = r.groups()
            gens = list(map(sympify, gens.split(',')))
            if ground in ['Z', 'ZZ']:
                return sympy.polys.domains.ZZ.poly_ring(*gens)
            elif ground in ['Q', 'QQ']:
                return sympy.polys.domains.QQ.poly_ring(*gens)
            elif ground in ['R', 'RR']:
                return sympy.polys.domains.RR.poly_ring(*gens)
            else:
                return sympy.polys.domains.CC.poly_ring(*gens)
        r = cls._re_fraction.match(domain)
        if r is not None:
            ground, gens = r.groups()
            gens = list(map(sympify, gens.split(',')))
            if ground in ['Z', 'ZZ']:
                return sympy.polys.domains.ZZ.frac_field(*gens)
            else:
                return sympy.polys.domains.QQ.frac_field(*gens)
        r = cls._re_algebraic.match(domain)
        if r is not None:
            gens = list(map(sympify, r.groups()[1].split(',')))
            return sympy.polys.domains.QQ.algebraic_field(*gens)
    raise OptionError('expected a valid domain specification, got %s' % domain)

.sympy.polys.polyoptions.Gens.preprocess

def preprocess(cls, gens):
    if isinstance(gens, Basic):
        gens = (gens,)
    elif len(gens) == 1 and hasattr(gens[0], '__iter__'):
        gens = gens[0]
    if gens == (None,):
        gens = ()
    elif has_dups(gens):
        raise GeneratorsError('duplicated generators: %s' % str(gens))
    elif any((gen.is_commutative is False for gen in gens)):
        raise GeneratorsError('non-commutative generators: %s' % str(gens))
    return tuple(gens)

.sympy.utilities.iterables.has_dups

def has_dups(seq):
    from sympy.core.containers import Dict
    from sympy.sets.sets import Set
    if isinstance(seq, (dict, set, Dict, Set)):
        return False
    uniq = set()
    return any((True for s in seq if s in uniq or uniq.add(s)))

.sympy.polys.polyutils._dict_from_expr_if_gens

def _dict_from_expr_if_gens(expr, opt):
    (poly,), gens = _parallel_dict_from_expr_if_gens((expr,), opt)
    return (poly, gens)

.sympy.polys.polyutils._parallel_dict_from_expr_if_gens

def _parallel_dict_from_expr_if_gens(exprs, opt):
    k, indices = (len(opt.gens), {})
    for i, g in enumerate(opt.gens):
        indices[g] = i
    polys = []
    for expr in exprs:
        poly = {}
        if expr.is_Equality:
            expr = expr.lhs - expr.rhs
        for term in Add.make_args(expr):
            coeff, monom = ([], [0] * k)
            for factor in Mul.make_args(term):
                if not _not_a_coeff(factor) and factor.is_Number:
                    coeff.append(factor)
                else:
                    try:
                        if opt.series is False:
                            base, exp = decompose_power(factor)
                            if exp < 0:
                                exp, base = (-exp, Pow(base, -S.One))
                        else:
                            base, exp = decompose_power_rat(factor)
                        monom[indices[base]] = exp
                    except KeyError:
                        if not factor.free_symbols.intersection(opt.gens):
                            coeff.append(factor)
                        else:
                            raise PolynomialError('%s contains an element of the set of generators.' % factor)
            monom = tuple(monom)
            if monom in poly:
                poly[monom] += Mul(*coeff)
            else:
                poly[monom] = Mul(*coeff)
        polys.append(poly)
    return (polys, opt.gens)

.sympy.polys.domains.expressiondomain.ExpressionDomain.from_sympy

def from_sympy(self, a):
    return self.dtype(a)

.sympy.polys.domains.expressiondomain.ExpressionDomain.Expression.__init__

def __init__(self):
    pass

.sympy.polys.domains.expressiondomain.ExpressionDomain.Expression.__nonzero__

def __nonzero__(f):
    return f.ex != 0

.sympy.polys.polytools.Poly.is_multivariate

def is_multivariate(f):
    return len(f.gens) != 1

.sympy.polys.polytools.Poly.terms_gcd

def terms_gcd(f):
    if hasattr(f.rep, 'terms_gcd'):
        J, result = f.rep.terms_gcd()
    else:
        raise OperationNotSupported(f, 'terms_gcd')
    return (J, f.per(result))

.sympy.polys.polyclasses.DMP.terms_gcd

def terms_gcd(f):
    J, F = dmp_terms_gcd(f.rep, f.lev, f.dom)
    return (J, f.per(F))

.sympy.polys.polyroots.preprocess_roots

def preprocess_roots(poly):
    coeff = S.One
    poly_func = poly.func
    try:
        _, poly = poly.clear_denoms(convert=True)
    except DomainError:
        return (coeff, poly)
    poly = poly.primitive()[1]
    poly = poly.retract()
    if poly.get_domain().is_Poly and all((c.is_term for c in poly.rep.coeffs())):
        poly = poly.inject()
        strips = list(zip(*poly.monoms()))
        gens = list(poly.gens[1:])
        base, strips = (strips[0], strips[1:])
        for gen, strip in zip(list(gens), strips):
            reverse = False
            if strip[0] < strip[-1]:
                strip = reversed(strip)
                reverse = True
            ratio = None
            for a, b in zip(base, strip):
                if not a and (not b):
                    continue
                elif not a or not b:
                    break
                elif b % a != 0:
                    break
                else:
                    _ratio = b // a
                    if ratio is None:
                        ratio = _ratio
                    elif ratio != _ratio:
                        break
            else:
                if reverse:
                    ratio = -ratio
                poly = poly.eval(gen, 1)
                coeff *= gen ** (-ratio)
                gens.remove(gen)
        if gens:
            poly = poly.eject(*gens)
    if poly.is_univariate and poly.get_domain().is_ZZ:
        basis = _integer_basis(poly)
        if basis is not None:
            n = poly.degree()

            def func(k, coeff):
                return coeff // basis ** (n - k[0])
            poly = poly.termwise(func)
            coeff *= basis
    if not isinstance(poly, poly_func):
        poly = poly_func(poly)
    return (coeff, poly)

.sympy.polys.polytools.Poly.clear_denoms

def clear_denoms(self, convert=False):
    f = self
    if not f.rep.dom.is_Field:
        return (S.One, f)
    dom = f.get_domain()
    if dom.has_assoc_Ring:
        dom = f.rep.dom.get_ring()
    if hasattr(f.rep, 'clear_denoms'):
        coeff, result = f.rep.clear_denoms()
    else:
        raise OperationNotSupported(f, 'clear_denoms')
    coeff, f = (dom.to_sympy(coeff), f.per(result))
    if not convert or not dom.has_assoc_Ring:
        return (coeff, f)
    else:
        return (coeff, f.to_ring())

