.sympy.solvers.solveset._domain_check

def _domain_check(f, symbol, p):
    if f.is_Atom and f.is_finite:
        return True
    elif f.subs(symbol, p).is_infinite:
        return False
    else:
        return all([_domain_check(g, symbol, p) for g in f.args])

.sympy.core.basic.Basic.subs

def subs(self, *args, **kwargs):
    from sympy.core.containers import Dict
    from sympy.utilities import default_sort_key
    from sympy import Dummy, Symbol
    unordered = False
    if len(args) == 1:
        sequence = args[0]
        if isinstance(sequence, set):
            unordered = True
        elif isinstance(sequence, (Dict, Mapping)):
            unordered = True
            sequence = sequence.items()
        elif not iterable(sequence):
            from sympy.utilities.misc import filldedent
            raise ValueError(filldedent('\n               When a single argument is passed to subs\n               it should be a dictionary of old: new pairs or an iterable\n               of (old, new) tuples.'))
    elif len(args) == 2:
        sequence = [args]
    else:
        raise ValueError('subs accepts either 1 or 2 arguments')
    sequence = list(sequence)
    for i, s in enumerate(sequence):
        if isinstance(s[0], string_types):
            s = (Symbol(s[0]), s[1])
        try:
            s = [sympify(_, strict=not isinstance(_, string_types)) for _ in s]
        except SympifyError:
            sequence[i] = None
            continue
        sequence[i] = None if _aresame(*s) else tuple(s)
    sequence = list(filter(None, sequence))
    if unordered:
        sequence = dict(sequence)
        if not all((k.is_Atom for k in sequence)):
            d = {}
            for o, n in sequence.items():
                try:
                    ops = (o.count_ops(), len(o.args))
                except TypeError:
                    ops = (0, 0)
                d.setdefault(ops, []).append((o, n))
            newseq = []
            for k in sorted(d.keys(), reverse=True):
                newseq.extend(sorted([v[0] for v in d[k]], key=default_sort_key))
            sequence = [(k, sequence[k]) for k in newseq]
            del newseq, d
        else:
            sequence = sorted([(k, v) for k, v in sequence.items()], key=default_sort_key)
    if kwargs.pop('simultaneous', False):
        reps = {}
        rv = self
        kwargs['hack2'] = True
        m = Dummy('subs_m')
        for old, new in sequence:
            com = new.is_commutative
            if com is None:
                com = True
            d = Dummy('subs_d', commutative=com)
            rv = rv._subs(old, d * m, **kwargs)
            if not isinstance(rv, Basic):
                break
            reps[d] = new
        reps[m] = S.One
        return rv.xreplace(reps)
    else:
        rv = self
        for old, new in sequence:
            rv = rv._subs(old, new, **kwargs)
            if not isinstance(rv, Basic):
                break
        return rv

.sympy.core.basic._aresame

def _aresame(a, b):
    from .numbers import Number
    from .function import AppliedUndef, UndefinedFunction as UndefFunc
    if isinstance(a, Number) and isinstance(b, Number):
        return a == b and a.__class__ == b.__class__
    for i, j in zip_longest(preorder_traversal(a), preorder_traversal(b)):
        if i != j or type(i) != type(j):
            if isinstance(i, UndefFunc) and isinstance(j, UndefFunc) or (isinstance(i, AppliedUndef) and isinstance(j, AppliedUndef)):
                if i.class_key() != j.class_key():
                    return False
            else:
                return False
    return True

.sympy.core.basic.Basic._subs

def _subs(self, old, new, **hints):

    def fallback(self, old, new):
        hit = False
        args = list(self.args)
        for i, arg in enumerate(args):
            if not hasattr(arg, '_eval_subs'):
                continue
            arg = arg._subs(old, new, **hints)
            if not _aresame(arg, args[i]):
                hit = True
                args[i] = arg
        if hit:
            rv = self.func(*args)
            hack2 = hints.get('hack2', False)
            if hack2 and self.is_Mul and (not rv.is_Mul):
                coeff = S.One
                nonnumber = []
                for i in args:
                    if i.is_Number:
                        coeff *= i
                    else:
                        nonnumber.append(i)
                nonnumber = self.func(*nonnumber)
                if coeff is S.One:
                    return nonnumber
                else:
                    return self.func(coeff, nonnumber, evaluate=False)
            return rv
        return self
    if _aresame(self, old):
        return new
    rv = self._eval_subs(old, new)
    if rv is None:
        rv = fallback(self, old, new)
    return rv

.sympy.core.add.Add._eval_subs

def _eval_subs(self, old, new):
    if not old.is_Add:
        if old is S.Infinity and -old in self.args:
            return self.xreplace({-old: -new})
        return None
    coeff_self, terms_self = self.as_coeff_Add()
    coeff_old, terms_old = old.as_coeff_Add()
    if coeff_self.is_Rational and coeff_old.is_Rational:
        if terms_self == terms_old:
            return self.func(new, coeff_self, -coeff_old)
        if terms_self == -terms_old:
            return self.func(-new, coeff_self, coeff_old)
    if coeff_self.is_Rational and coeff_old.is_Rational or coeff_self == coeff_old:
        args_old, args_self = (self.func.make_args(terms_old), self.func.make_args(terms_self))
        if len(args_old) < len(args_self):
            self_set = set(args_self)
            old_set = set(args_old)
            if old_set < self_set:
                ret_set = self_set - old_set
                return self.func(new, coeff_self, -coeff_old, *[s._subs(old, new) for s in ret_set])
            args_old = self.func.make_args(-terms_old)
            old_set = set(args_old)
            if old_set < self_set:
                ret_set = self_set - old_set
                return self.func(-new, coeff_self, coeff_old, *[s._subs(old, new) for s in ret_set])

.sympy.core.basic.Basic.fallback

def fallback(self, old, new):
    hit = False
    args = list(self.args)
    for i, arg in enumerate(args):
        if not hasattr(arg, '_eval_subs'):
            continue
        arg = arg._subs(old, new, **hints)
        if not _aresame(arg, args[i]):
            hit = True
            args[i] = arg
    if hit:
        rv = self.func(*args)
        hack2 = hints.get('hack2', False)
        if hack2 and self.is_Mul and (not rv.is_Mul):
            coeff = S.One
            nonnumber = []
            for i in args:
                if i.is_Number:
                    coeff *= i
                else:
                    nonnumber.append(i)
            nonnumber = self.func(*nonnumber)
            if coeff is S.One:
                return nonnumber
            else:
                return self.func(coeff, nonnumber, evaluate=False)
        return rv
    return self

.sympy.core.mul.Mul._eval_subs

def _eval_subs(self, old, new):
    from sympy.functions.elementary.complexes import sign
    from sympy.ntheory.factor_ import multiplicity
    from sympy.simplify.powsimp import powdenest
    from sympy.simplify.radsimp import fraction
    if not old.is_Mul:
        return None
    if old.args[0].is_Number and old.args[0] < 0:
        if self.args[0].is_Number:
            if self.args[0] < 0:
                return self._subs(-old, -new)
            return None

    def base_exp(a):
        from sympy import exp
        if a.is_Pow or isinstance(a, exp):
            return a.as_base_exp()
        return (a, S.One)

    def breakup(eq):
        c, nc = (defaultdict(int), list())
        for a in Mul.make_args(eq):
            a = powdenest(a)
            b, e = base_exp(a)
            if e is not S.One:
                co, _ = e.as_coeff_mul()
                b = Pow(b, e / co)
                e = co
            if a.is_commutative:
                c[b] += e
            else:
                nc.append([b, e])
        return (c, nc)

    def rejoin(b, co):
        b, e = base_exp(b)
        return Pow(b, e * co)

    def ndiv(a, b):
        if not b.q % a.q or not a.q % b.q:
            return int(a / b)
        return 0
    rv = None
    n, d = fraction(self)
    self2 = self
    if d is not S.One:
        self2 = n._subs(old, new) / d._subs(old, new)
        if not self2.is_Mul:
            return self2._subs(old, new)
        if self2 != self:
            rv = self2
    co_self = self2.args[0]
    co_old = old.args[0]
    co_xmul = None
    if co_old.is_Rational and co_self.is_Rational:
        if co_old != co_self:
            co_xmul = co_self.extract_multiplicatively(co_old)
    elif co_old.is_Rational:
        return rv
    c, nc = breakup(self2)
    old_c, old_nc = breakup(old)
    if co_xmul and co_xmul.is_Rational and (abs(co_old) != 1):
        mult = S(multiplicity(abs(co_old), co_self))
        c.pop(co_self)
        if co_old in c:
            c[co_old] += mult
        else:
            c[co_old] = mult
        co_residual = co_self / co_old ** mult
    else:
        co_residual = 1
    ok = True
    if len(old_nc) > len(nc):
        ok = False
    elif len(old_c) > len(c):
        ok = False
    elif set((i[0] for i in old_nc)).difference(set((i[0] for i in nc))):
        ok = False
    elif set(old_c).difference(set(c)):
        ok = False
    elif any((sign(c[b]) != sign(old_c[b]) for b in old_c)):
        ok = False
    if not ok:
        return rv
    if not old_c:
        cdid = None
    else:
        rat = []
        for b, old_e in old_c.items():
            c_e = c[b]
            rat.append(ndiv(c_e, old_e))
            if not rat[-1]:
                return rv
        cdid = min(rat)
    if not old_nc:
        ncdid = None
        for i in range(len(nc)):
            nc[i] = rejoin(*nc[i])
    else:
        ncdid = 0
        take = len(old_nc)
        limit = cdid or S.Infinity
        failed = []
        i = 0
        while limit and i + take <= len(nc):
            hit = False
            rat = []
            for j in range(take):
                if nc[i + j][0] != old_nc[j][0]:
                    break
                elif j == 0:
                    rat.append(ndiv(nc[i + j][1], old_nc[j][1]))
                elif j == take - 1:
                    rat.append(ndiv(nc[i + j][1], old_nc[j][1]))
                elif nc[i + j][1] != old_nc[j][1]:
                    break
                else:
                    rat.append(1)
                j += 1
            else:
                ndo = min(rat)
                if ndo:
                    if take == 1:
                        if cdid:
                            ndo = min(cdid, ndo)
                        nc[i] = Pow(new, ndo) * rejoin(nc[i][0], nc[i][1] - ndo * old_nc[0][1])
                    else:
                        ndo = 1
                        l = rejoin(nc[i][0], nc[i][1] - ndo * old_nc[0][1])
                        mid = new
                        ir = i + take - 1
                        r = (nc[ir][0], nc[ir][1] - ndo * old_nc[-1][1])
                        if r[1]:
                            if i + take < len(nc):
                                nc[i:i + take] = [l * mid, r]
                            else:
                                r = rejoin(*r)
                                nc[i:i + take] = [l * mid * r]
                        else:
                            nc[i:i + take] = [l * mid]
                    limit -= ndo
                    ncdid += ndo
                    hit = True
            if not hit:
                failed.append(i)
            i += 1
        else:
            if not ncdid:
                return rv
            failed.extend(range(i, len(nc)))
            for i in failed:
                nc[i] = rejoin(*nc[i]).subs(old, new)
    if cdid is None:
        do = ncdid
    elif ncdid is None:
        do = cdid
    else:
        do = min(ncdid, cdid)
    margs = []
    for b in c:
        if b in old_c:
            e = c[b] - old_c[b] * do
            margs.append(rejoin(b, e))
        else:
            margs.append(rejoin(b.subs(old, new), c[b]))
    if cdid and (not ncdid):
        margs = [Pow(new, cdid)] + margs
    return co_residual * self2.func(*margs) * self2.func(*nc)

.sympy.core.numbers.Number._eval_subs

def _eval_subs(self, old, new):
    if old == -self:
        return -new
    return self

.sympy.core.power.Pow._eval_subs

def _eval_subs(self, old, new):
    from sympy import exp, log, Symbol

    def _check(ct1, ct2, old):
        coeff1, terms1 = ct1
        coeff2, terms2 = ct2
        if terms1 == terms2:
            if old.is_commutative:
                pow = coeff1 / coeff2
                try:
                    as_int(pow, strict=False)
                    combines = True
                except ValueError:
                    combines = isinstance(Pow._eval_power(Pow(*old.as_base_exp(), evaluate=False), pow), (Pow, exp, Symbol))
                return (combines, pow, None)
            else:
                if not isinstance(terms1, tuple):
                    terms1 = (terms1,)
                if not all((term.is_integer for term in terms1)):
                    return (False, None, None)
                try:
                    pow, remainder = divmod(as_int(coeff1), as_int(coeff2))
                    if pow < 0 and remainder != 0:
                        pow += 1
                        remainder -= as_int(coeff2)
                    if remainder == 0:
                        remainder_pow = None
                    else:
                        remainder_pow = Mul(remainder, *terms1)
                    return (True, pow, remainder_pow)
                except ValueError:
                    pass
        return (False, None, None)
    if old == self.base:
        return new ** self.exp._subs(old, new)
    if isinstance(old, self.func) and self.exp == old.exp:
        l = log(self.base, old.base)
        if l.is_Number:
            return Pow(new, l)
    if isinstance(old, self.func) and self.base == old.base:
        if self.exp.is_Add is False:
            ct1 = self.exp.as_independent(Symbol, as_Add=False)
            ct2 = old.exp.as_independent(Symbol, as_Add=False)
            ok, pow, remainder_pow = _check(ct1, ct2, old)
            if ok:
                result = self.func(new, pow)
                if remainder_pow is not None:
                    result = Mul(result, Pow(old.base, remainder_pow))
                return result
        else:
            oarg = old.exp
            new_l = []
            o_al = []
            ct2 = oarg.as_coeff_mul()
            for a in self.exp.args:
                newa = a._subs(old, new)
                ct1 = newa.as_coeff_mul()
                ok, pow, remainder_pow = _check(ct1, ct2, old)
                if ok:
                    new_l.append(new ** pow)
                    if remainder_pow is not None:
                        o_al.append(remainder_pow)
                    continue
                elif not old.is_commutative and (not newa.is_integer):
                    return
                o_al.append(newa)
            if new_l:
                expo = Add(*o_al)
                new_l.append(Pow(self.base, expo, evaluate=False) if expo != 1 else self.base)
                return Mul(*new_l)
    if isinstance(old, exp) and self.exp.is_extended_real and self.base.is_positive:
        ct1 = old.args[0].as_independent(Symbol, as_Add=False)
        ct2 = (self.exp * log(self.base)).as_independent(Symbol, as_Add=False)
        ok, pow, remainder_pow = _check(ct1, ct2, old)
        if ok:
            result = self.func(new, pow)
            if remainder_pow is not None:
                result = Mul(result, Pow(old.base, remainder_pow))
            return result

.sympy.core.add.Add._eval_power

def _eval_power(self, e):
    if e.is_Rational and self.is_number:
        from sympy.core.evalf import pure_complex
        from sympy.core.mul import _unevaluated_Mul
        from sympy.core.exprtools import factor_terms
        from sympy.core.function import expand_multinomial
        from sympy.functions.elementary.complexes import sign
        from sympy.functions.elementary.miscellaneous import sqrt
        ri = pure_complex(self)
        if ri:
            r, i = ri
            if e.q == 2:
                D = sqrt(r ** 2 + i ** 2)
                if D.is_Rational:
                    root = sqrt(factor_terms((D - r) / 2)) ** e.p
                    return root * expand_multinomial(((D + r) / abs(i) + sign(i) * S.ImaginaryUnit) ** e.p)
            elif e == -1:
                return _unevaluated_Mul(r - i * S.ImaginaryUnit, 1 / (r ** 2 + i ** 2))
    elif e.is_Number and abs(e) != 1:
        c, m = zip(*[i.as_coeff_Mul() for i in self.args])
        if any((i.is_Float for i in c)):
            big = -1
            for i in c:
                if abs(i) >= big:
                    big = abs(i)
            if big > 0 and big != 1:
                from sympy.functions.elementary.complexes import sign
                bigs = (big, -big)
                c = [sign(i) if i in bigs else i / big for i in c]
                addpow = Add(*[c * m for c, m in zip(c, m)]) ** e
                return big ** e * addpow

.sympy.core.evalf.pure_complex

def pure_complex(v, or_real=False):
    h, t = v.as_coeff_Add()
    if not t:
        if or_real:
            return (h, t)
        return
    c, i = t.as_coeff_Mul()
    if i is S.ImaginaryUnit:
        return (h, c)

.sympy.core.operations.AssocOp._eval_evalf

def _eval_evalf(self, prec):
    from .add import Add
    from .mul import Mul
    from .symbol import Symbol
    from .function import AppliedUndef
    if isinstance(self, (Mul, Add)):
        x, tail = self.as_independent(Symbol, AppliedUndef)
        if not (tail is self.identity or (isinstance(x, AssocOp) and x.is_Function) or (x is self.identity and isinstance(tail, AssocOp))):
            x = x._evalf(prec) if x is not self.identity else self.identity
            args = []
            tail_args = tuple(self.func.make_args(tail))
            for a in tail_args:
                newa = a._eval_evalf(prec)
                if newa is None:
                    args.append(a)
                else:
                    args.append(newa)
            return self.func(x, *args)
    args = []
    for a in self.args:
        newa = a._eval_evalf(prec)
        if newa is None:
            args.append(a)
        else:
            args.append(newa)
    return self.func(*args)

.sympy.core.numbers.Rational._as_mpf_val

def _as_mpf_val(self, prec):
    return mlib.from_rational(self.p, self.q, prec, rnd)

.sympy.core.mul.Mul._eval_evalf

def _eval_evalf(self, prec):
    c, m = self.as_coeff_Mul()
    if c is S.NegativeOne:
        if m.is_Mul:
            rv = -AssocOp._eval_evalf(m, prec)
        else:
            mnew = m._eval_evalf(prec)
            if mnew is not None:
                m = mnew
            rv = -m
    else:
        rv = AssocOp._eval_evalf(self, prec)
    if rv.is_number:
        return rv.expand()
    return rv

.sympy.core.power.Pow._eval_evalf

def _eval_evalf(self, prec):
    base, exp = self.as_base_exp()
    base = base._evalf(prec)
    if not exp.is_Integer:
        exp = exp._evalf(prec)
    if exp.is_negative and base.is_number and (base.is_extended_real is False):
        base = base.conjugate() / (base * base.conjugate())._evalf(prec)
        exp = -exp
        return self.func(base, exp).expand()
    return self.func(base, exp)

.sympy.core.evalf.EvalfMixin._evalf

def _evalf(self, prec):
    r = self._eval_evalf(prec)
    if r is None:
        r = self
    return r

.sympy.core.numbers.Float._eval_is_negative

def _eval_is_negative(self):
    if self._mpf_ == _mpf_ninf or self._mpf_ == _mpf_inf:
        return False
    return self.num < 0

.sympy.core.numbers.Float.__nonzero__

def __nonzero__(self):
    return self._mpf_ != fzero

.sympy.core.numbers.Float._eval_is_integer

def _eval_is_integer(self):
    return self._mpf_ == fzero

.sympy.core.numbers.NaN._as_mpf_val

def _as_mpf_val(self, prec):
    return _mpf_nan

.sympy.core.numbers.Float._eval_power

def _eval_power(self, expt):
    if self == 0:
        if expt.is_positive:
            return S.Zero
        if expt.is_negative:
            return S.Infinity
    if isinstance(expt, Number):
        if isinstance(expt, Integer):
            prec = self._prec
            return Float._new(mlib.mpf_pow_int(self._mpf_, expt.p, prec, rnd), prec)
        elif isinstance(expt, Rational) and expt.p == 1 and expt.q % 2 and self.is_negative:
            return Pow(S.NegativeOne, expt, evaluate=False) * (-self)._eval_power(expt)
        expt, prec = expt._as_mpf_op(self._prec)
        mpfself = self._mpf_
        try:
            y = mpf_pow(mpfself, expt, prec, rnd)
            return Float._new(y, prec)
        except mlib.ComplexResult:
            re, im = mlib.mpc_pow((mpfself, fzero), (expt, fzero), prec, rnd)
            return Float._new(re, prec) + Float._new(im, prec) * S.ImaginaryUnit

.sympy.core.numbers.Float._as_mpf_op

def _as_mpf_op(self, prec):
    return (self._mpf_, max(prec, self._prec))

.sympy.core.numbers.Float.__mul__

def __mul__(self, other):
    if isinstance(other, Number) and global_evaluate[0]:
        rhs, prec = other._as_mpf_op(self._prec)
        return Float._new(mlib.mpf_mul(self._mpf_, rhs, prec, rnd), prec)
    return Number.__mul__(self, other)

.sympy.core.numbers.Number._as_mpf_op

def _as_mpf_op(self, prec):
    prec = max(prec, self._prec)
    return (self._as_mpf_val(prec), prec)

.sympy.core.numbers.Float.__add__

def __add__(self, other):
    if isinstance(other, Number) and global_evaluate[0]:
        rhs, prec = other._as_mpf_op(self._prec)
        return Float._new(mlib.mpf_add(self._mpf_, rhs, prec, rnd), prec)
    return Number.__add__(self, other)

.sympy.core.evalf.evalf_add

def evalf_add(v, prec, options):
    res = pure_complex(v)
    if res:
        h, c = res
        re, _, re_acc, _ = evalf(h, prec, options)
        im, _, im_acc, _ = evalf(c, prec, options)
        return (re, im, re_acc, im_acc)
    oldmaxprec = options.get('maxprec', DEFAULT_MAXPREC)
    i = 0
    target_prec = prec
    while 1:
        options['maxprec'] = min(oldmaxprec, 2 * prec)
        terms = [evalf(arg, prec + 10, options) for arg in v.args]
        re, re_acc = add_terms([a[0::2] for a in terms if a[0]], prec, target_prec)
        im, im_acc = add_terms([a[1::2] for a in terms if a[1]], prec, target_prec)
        acc = complex_accuracy((re, im, re_acc, im_acc))
        if acc >= target_prec:
            if options.get('verbose'):
                print('ADD: wanted', target_prec, 'accurate bits, got', re_acc, im_acc)
            break
        else:
            if prec - target_prec > options['maxprec']:
                break
            prec = prec + max(10 + 2 ** i, target_prec - acc)
            i += 1
            if options.get('verbose'):
                print('ADD: restarting with prec', prec)
    options['maxprec'] = oldmaxprec
    if iszero(re, scaled=True):
        re = scaled_zero(re)
    if iszero(im, scaled=True):
        im = scaled_zero(im)
    return (re, im, re_acc, im_acc)

.sympy.core.evalf.evalf_mul

def evalf_mul(v, prec, options):
    res = pure_complex(v)
    if res:
        _, h = res
        im, _, im_acc, _ = evalf(h, prec, options)
        return (None, im, None, im_acc)
    args = list(v.args)
    special = []
    from sympy.core.numbers import Float
    for arg in args:
        arg = evalf(arg, prec, options)
        if arg[0] is None:
            continue
        arg = Float._new(arg[0], 1)
        if arg is S.NaN or arg.is_infinite:
            special.append(arg)
    if special:
        from sympy.core.mul import Mul
        special = Mul(*special)
        return evalf(special, prec + 4, {})
    acc = prec
    working_prec = prec + len(args) + 5
    start = man, exp, bc = (MPZ(1), 0, 1)
    last = len(args)
    direction = 0
    args.append(S.One)
    complex_factors = []
    for i, arg in enumerate(args):
        if i != last and pure_complex(arg):
            args[-1] = (args[-1] * arg).expand()
            continue
        elif i == last and arg is S.One:
            continue
        re, im, re_acc, im_acc = evalf(arg, working_prec, options)
        if re and im:
            complex_factors.append((re, im, re_acc, im_acc))
            continue
        elif re:
            (s, m, e, b), w_acc = (re, re_acc)
        elif im:
            (s, m, e, b), w_acc = (im, im_acc)
            direction += 1
        else:
            return (None, None, None, None)
        direction += 2 * s
        man *= m
        exp += e
        bc += b
        if bc > 3 * working_prec:
            man >>= working_prec
            exp += working_prec
        acc = min(acc, w_acc)
    sign = (direction & 2) >> 1
    if not complex_factors:
        v = normalize(sign, man, exp, bitcount(man), prec, rnd)
        if direction & 1:
            return (None, v, None, acc)
        else:
            return (v, None, acc, None)
    else:
        if (man, exp, bc) != start:
            re, im = ((sign, man, exp, bitcount(man)), (0, MPZ(0), 0, 0))
            i0 = 0
        else:
            wre, wim, wre_acc, wim_acc = complex_factors[0]
            acc = min(acc, complex_accuracy((wre, wim, wre_acc, wim_acc)))
            re = wre
            im = wim
            i0 = 1
        for wre, wim, wre_acc, wim_acc in complex_factors[i0:]:
            acc = min(acc, complex_accuracy((wre, wim, wre_acc, wim_acc)))
            use_prec = working_prec
            A = mpf_mul(re, wre, use_prec)
            B = mpf_mul(mpf_neg(im), wim, use_prec)
            C = mpf_mul(re, wim, use_prec)
            D = mpf_mul(im, wre, use_prec)
            re = mpf_add(A, B, use_prec)
            im = mpf_add(C, D, use_prec)
        if options.get('verbose'):
            print('MUL: wanted', prec, 'accurate bits, got', acc)
        if direction & 1:
            re, im = (mpf_neg(im), re)
        return (re, im, acc, acc)

.sympy.core.expr.Expr.as_coeff_Add

def as_coeff_Add(self, rational=False):
    return (S.Zero, self)

.sympy.core.evalf.bitcount

def bitcount(n):
    return mpmath_bitcount(abs(int(n)))

.sympy.core.evalf.add_terms

def add_terms(terms, prec, target_prec):
    terms = [t for t in terms if not iszero(t[0])]
    if not terms:
        return (None, None)
    elif len(terms) == 1:
        return terms[0]
    special = []
    from sympy.core.numbers import Float
    for t in terms:
        arg = Float._new(t[0], 1)
        if arg is S.NaN or arg.is_infinite:
            special.append(arg)
    if special:
        from sympy.core.add import Add
        rv = evalf(Add(*special), prec + 4, {})
        return (rv[0], rv[2])
    working_prec = 2 * prec
    sum_man, sum_exp, absolute_error = (0, 0, MINUS_INF)
    for x, accuracy in terms:
        sign, man, exp, bc = x
        if sign:
            man = -man
        absolute_error = max(absolute_error, bc + exp - accuracy)
        delta = exp - sum_exp
        if exp >= sum_exp:
            if delta > working_prec and (not sum_man or delta - bitcount(abs(sum_man)) > working_prec):
                sum_man = man
                sum_exp = exp
            else:
                sum_man += man << delta
        else:
            delta = -delta
            if delta - bc > working_prec:
                if not sum_man:
                    sum_man, sum_exp = (man, exp)
            else:
                sum_man = (sum_man << delta) + man
                sum_exp = exp
    if not sum_man:
        return scaled_zero(absolute_error)
    if sum_man < 0:
        sum_sign = 1
        sum_man = -sum_man
    else:
        sum_sign = 0
    sum_bc = bitcount(sum_man)
    sum_accuracy = sum_exp + sum_bc - absolute_error
    r = (normalize(sum_sign, sum_man, sum_exp, sum_bc, target_prec, rnd), sum_accuracy)
    return r

.sympy.core.evalf.iszero

def iszero(mpf, scaled=False):
    if not scaled:
        return not mpf or (not mpf[1] and (not mpf[-1]))
    return mpf and type(mpf[0]) is list and (mpf[1] == mpf[-1] == 1)

.sympy.core.evalf.complex_accuracy

def complex_accuracy(result):
    re, im, re_acc, im_acc = result
    if not im:
        if not re:
            return INF
        return re_acc
    if not re:
        return im_acc
    re_size = fastlog(re)
    im_size = fastlog(im)
    absolute_error = max(re_size - re_acc, im_size - im_acc)
    relative_error = absolute_error - max(re_size, im_size)
    return -relative_error

.sympy.sets.fancysets.Integers._contains

def _contains(self, other):
    if not isinstance(other, Expr):
        return S.false
    return other.is_integer

.sympy.core.symbol.Symbol._eval_subs

def _eval_subs(self, old, new):
    from sympy.core.power import Pow
    if old.is_Pow:
        return Pow(self, S.One, evaluate=False)._eval_subs(old, new)

.sympy.core.numbers.Zero._eval_power

def _eval_power(self, expt):
    if expt.is_positive:
        return self
    if expt.is_negative:
        return S.ComplexInfinity
    if expt.is_extended_real is False:
        return S.NaN
    coeff, terms = expt.as_coeff_Mul()
    if coeff.is_negative:
        return S.ComplexInfinity ** terms
    if coeff is not S.One:
        return self ** terms

.sympy.polys.densearith.dmp_neg

def dmp_neg(f, u, K):
    if not u:
        return dup_neg(f, K)
    v = u - 1
    return [dmp_neg(cf, v, K) for cf in f]

.sympy.core.expr.Expr.as_coeff_mul

def as_coeff_mul(self, *deps, **kwargs):
    if deps:
        if not self.has(*deps):
            return (self, tuple())
    return (S.One, (self,))

.sympy.polys.densearith.dup_sqr

def dup_sqr(f, K):
    df, h = (len(f) - 1, [])
    for i in range(0, 2 * df + 1):
        c = K.zero
        jmin = max(0, i - df)
        jmax = min(i, df)
        n = jmax - jmin + 1
        jmax = jmin + n // 2 - 1
        for j in range(jmin, jmax + 1):
            c += f[j] * f[i - j]
        c += c
        if n & 1:
            elem = f[jmax + 1]
            c += elem ** 2
        h.append(c)
    return dup_strip(h)

.sympy.solvers.diophantine.base_solution_linear

def base_solution_linear(c, a, b, t=None):
    a, b, c = _remove_gcd(a, b, c)
    if c == 0:
        if t is not None:
            if b < 0:
                t = -t
            return (b * t, -a * t)
        else:
            return (0, 0)
    else:
        x0, y0, d = igcdex(abs(a), abs(b))
        x0 *= sign(a)
        y0 *= sign(b)
        if divisible(c, d):
            if t is not None:
                if b < 0:
                    t = -t
                return (c * x0 + b * t, c * y0 - a * t)
            else:
                return (c * x0, c * y0)
        else:
            return (None, None)

.sympy.core.numbers.Integer.__rsub__

def __rsub__(self, other):
    if global_evaluate[0]:
        if isinstance(other, integer_types):
            return Integer(other - self.p)
        elif isinstance(other, Rational):
            return Rational(other.p - self.p * other.q, other.q, 1)
        return Rational.__rsub__(self, other)
    return Rational.__rsub__(self, other)

.sympy.polys.densebasic._rec_inflate

def _rec_inflate(g, M, v, i, K):
    if not v:
        return dup_inflate(g, M[i], K)
    if M[i] <= 0:
        raise IndexError('all M[i] must be positive, got %s' % M[i])
    w, j = (v - 1, i + 1)
    g = [_rec_inflate(c, M, w, j, K) for c in g]
    result = [g[0]]
    for coeff in g[1:]:
        for _ in range(1, M[i]):
            result.append(dmp_zero(w))
        result.append(coeff)
    return result

.sympy.polys.densebasic.dup_inflate

def dup_inflate(f, m, K):
    if m <= 0:
        raise IndexError("'m' must be positive, got %s" % m)
    if m == 1 or not f:
        return f
    result = [f[0]]
    for coeff in f[1:]:
        result.extend([K.zero] * (m - 1))
        result.append(coeff)
    return result

.sympy.ntheory.primetest.mr

def mr(n, bases):
    from sympy.ntheory.factor_ import trailing
    from sympy.polys.domains import ZZ
    n = as_int(n)
    if n < 2:
        return False
    s = trailing(n - 1)
    t = n >> s
    for base in bases:
        if base >= n:
            base %= n
        if base >= 2:
            base = ZZ(base)
            if not _test(n, base, s, t):
                return False
    return True

.sympy.ntheory.primetest._test

def _test(n, base, s, t):
    b = pow(base, t, n)
    if b == 1 or b == n - 1:
        return True
    else:
        for j in range(1, s):
            b = pow(b, 2, n)
            if b == n - 1:
                return True
            if b == 1:
                return False
    return False

.sympy.core.numbers._literal_float

def _literal_float(f):
    return bool(_floatpat.match(f))

.sympy.core.numbers._decimal_to_Rational_prec

def _decimal_to_Rational_prec(dec):
    if not dec.is_finite():
        raise TypeError('dec must be finite, got %s.' % dec)
    s, d, e = dec.as_tuple()
    prec = len(d)
    if e >= 0:
        rv = Integer(int(dec))
    else:
        s = (-1) ** s
        d = sum([di * 10 ** i for i, di in enumerate(reversed(d))])
        rv = Rational(s * d, 10 ** (-e))
    return (rv, prec)

.sympy.printing.str.StrPrinter._print_Zero

def _print_Zero(self, expr):
    if self._settings.get('sympy_integers', False):
        return 'S(0)'
    return '0'

.sympy.ntheory.primetest.is_square

def is_square(n, prep=True):
    if prep:
        n = as_int(n)
        if n < 0:
            return False
        if n in [0, 1]:
            return True
    m = n & 127
    if not m * 2344881533 & m * 2716005841 & 1311242:
        m = n % 63
        if not m * 1028201975 & m * 3357846009 & 284246024:
            from sympy.core.power import integer_nthroot
            return integer_nthroot(n, 2)[1]
    return False

.sympy.core.function._mexpand

def _mexpand(expr, recursive=False):
    if expr is None:
        return
    was = None
    while was != expr:
        was, expr = (expr, expand_mul(expand_multinomial(expr)))
        if not recursive:
            break
    return expr

.sympy.core.function.expand_multinomial

def expand_multinomial(expr, deep=True):
    return sympify(expr).expand(deep=deep, mul=False, power_exp=False, power_base=False, basic=False, multinomial=True, log=False)

.sympy.core.function.expand_mul

def expand_mul(expr, deep=True):
    return sympify(expr).expand(deep=deep, mul=True, power_exp=False, power_base=False, basic=False, multinomial=False, log=False)

.sympy.ntheory.factor_._divisors

def _divisors(n, proper=False):
    factordict = factorint(n)
    ps = sorted(factordict.keys())

    def rec_gen(n=0):
        if n == len(ps):
            yield 1
        else:
            pows = [1]
            for j in range(factordict[ps[n]]):
                pows.append(pows[-1] * ps[n])
            for q in rec_gen(n + 1):
                for p in pows:
                    yield (p * q)
    if proper:
        for p in rec_gen():
            if p != n:
                yield p
    else:
        for p in rec_gen():
            yield p

.sympy.ntheory.factor_.rec_gen

def rec_gen(n=0):
    if n == len(ps):
        yield 1
    else:
        pows = [1]
        for j in range(factordict[ps[n]]):
            pows.append(pows[-1] * ps[n])
        for q in rec_gen(n + 1):
            for p in pows:
                yield (p * q)

.sympy.solvers.diophantine.is_solution_quad

def is_solution_quad(var, coeff, u, v):
    reps = dict(zip(var, (u, v)))
    eq = Add(*[j * i.xreplace(reps) for i, j in coeff.items()])
    return _mexpand(eq) == 0

.sympy.polys.densearith.dup_l1_norm

def dup_l1_norm(f, K):
    if not f:
        return K.zero
    else:
        return sum(dup_abs(f, K))

.sympy.core.numbers.Zero.as_coeff_Mul

def as_coeff_Mul(self, rational=False):
    return (S.One, self)

.sympy.polys.monomials.monomial_min

def monomial_min(*monoms):
    M = list(monoms[0])
    for N in monoms[1:]:
        for i, n in enumerate(N):
            M[i] = min(M[i], n)
    return tuple(M)

.sympy.polys.factortools._test_pl

def _test_pl(fc, q, pl):
    if q > pl // 2:
        q = q - pl
    if not q:
        return True
    return fc % q == 0

.sympy.polys.factortools.dmp_zz_wang_lead_coeffs

def dmp_zz_wang_lead_coeffs(f, T, cs, E, H, A, u, K):
    C, J, v = ([], [0] * len(E), u - 1)
    for h in H:
        c = dmp_one(v, K)
        d = dup_LC(h, K) * cs
        for i in reversed(range(len(E))):
            k, e, (t, _) = (0, E[i], T[i])
            while not d % e:
                d, k = (d // e, k + 1)
            if k != 0:
                c, J[i] = (dmp_mul(c, dmp_pow(t, k, v, K), v, K), 1)
        C.append(c)
    if any((not j for j in J)):
        raise ExtraneousFactors
    CC, HH = ([], [])
    for c, h in zip(C, H):
        d = dmp_eval_tail(c, A, v, K)
        lc = dup_LC(h, K)
        if K.is_one(cs):
            cc = lc // d
        else:
            g = K.gcd(lc, d)
            d, cc = (d // g, lc // g)
            h, cs = (dup_mul_ground(h, d, K), cs // d)
        c = dmp_mul_ground(c, cc, v, K)
        CC.append(c)
        HH.append(h)
    if K.is_one(cs):
        return (f, HH, CC)
    CCC, HHH = ([], [])
    for c, h in zip(CC, HH):
        CCC.append(dmp_mul_ground(c, cs, v, K))
        HHH.append(dmp_mul_ground(h, cs, 0, K))
    f = dmp_mul_ground(f, cs ** (len(H) - 1), u, K)
    return (f, HHH, CCC)

.sympy.polys.densebasic.dmp_one

def dmp_one(u, K):
    return dmp_ground(K.one, u)

.sympy.polys.densebasic.dmp_ground

def dmp_ground(c, u):
    if not c:
        return dmp_zero(u)
    for i in range(u + 1):
        c = [c]
    return c

.sympy.polys.factortools.dmp_zz_wang_hensel_lifting

def dmp_zz_wang_hensel_lifting(f, H, LC, A, p, u, K):
    S, n, v = ([f], len(A), u - 1)
    H = list(H)
    for i, a in enumerate(reversed(A[1:])):
        s = dmp_eval_in(S[0], a, n - i, u - i, K)
        S.insert(0, dmp_ground_trunc(s, p, v - i, K))
    d = max(dmp_degree_list(f, u)[1:])
    for j, s, a in zip(range(2, n + 2), S, A):
        G, w = (list(H), j - 1)
        I, J = (A[:j - 2], A[j - 1:])
        for i, (h, lc) in enumerate(zip(H, LC)):
            lc = dmp_ground_trunc(dmp_eval_tail(lc, J, v, K), p, w - 1, K)
            H[i] = [lc] + dmp_raise(h[1:], 1, w - 1, K)
        m = dmp_nest([K.one, -a], w, K)
        M = dmp_one(w, K)
        c = dmp_sub(s, dmp_expand(H, w, K), w, K)
        dj = dmp_degree_in(s, w, w)
        for k in K.map(range(0, dj)):
            if dmp_zero_p(c, w):
                break
            M = dmp_mul(M, m, w, K)
            C = dmp_diff_eval_in(c, k + 1, a, w, w, K)
            if not dmp_zero_p(C, w - 1):
                C = dmp_quo_ground(C, K.factorial(k + 1), w - 1, K)
                T = dmp_zz_diophantine(G, C, I, d, p, w - 1, K)
                for i, (h, t) in enumerate(zip(H, T)):
                    h = dmp_add_mul(h, dmp_raise(t, 1, w - 1, K), M, w, K)
                    H[i] = dmp_ground_trunc(h, p, w, K)
                h = dmp_sub(s, dmp_expand(H, w, K), w, K)
                c = dmp_ground_trunc(h, p, w, K)
    if dmp_expand(H, u, K) != f:
        raise ExtraneousFactors
    else:
        return H

.sympy.polys.densebasic.dmp_raise

def dmp_raise(f, l, u, K):
    if not l:
        return f
    if not u:
        if not f:
            return dmp_zero(l)
        k = l - 1
        return [dmp_ground(c, k) for c in f]
    v = u - 1
    return [dmp_raise(c, l, v, K) for c in f]

.sympy.polys.densebasic.dmp_nest

def dmp_nest(f, l, K):
    if not isinstance(f, list):
        return dmp_ground(f, l)
    for i in range(l):
        f = [f]
    return f

.sympy.polys.densearith.dmp_expand

def dmp_expand(polys, u, K):
    if not polys:
        return dmp_one(u, K)
    f = polys[0]
    for g in polys[1:]:
        f = dmp_mul(f, g, u, K)
    return f

.sympy.polys.densebasic._rec_degree_in

def _rec_degree_in(g, v, i, j):
    if i == j:
        return dmp_degree(g, v)
    v, i = (v - 1, i + 1)
    return max([_rec_degree_in(c, v, i, j) for c in g])

.sympy.polys.domains.domain.Domain.map

def map(self, seq):
    result = []
    for elt in seq:
        if isinstance(elt, list):
            result.append(self.map(elt))
        else:
            result.append(self(elt))
    return result

.sympy.polys.densetools.dmp_diff_eval_in

def dmp_diff_eval_in(f, m, a, j, u, K):
    if j > u:
        raise IndexError('-%s <= j < %s expected, got %s' % (u, u, j))
    if not j:
        return dmp_eval(dmp_diff(f, m, u, K), a, u, K)
    return _rec_diff_eval(f, m, a, u, 0, j, K)

.sympy.polys.densetools._rec_diff_eval

def _rec_diff_eval(g, m, a, v, i, j, K):
    if i == j:
        return dmp_eval(dmp_diff(g, m, v, K), a, v, K)
    v, i = (v - 1, i + 1)
    return dmp_strip([_rec_diff_eval(c, m, a, v, i, j, K) for c in g], v)

.sympy.polys.domains.pythonintegerring.PythonIntegerRing.factorial

def factorial(self, a):
    return python_factorial(a)

.sympy.polys.domains.groundtypes.python_factorial

def python_factorial(n):
    return int(mlib.ifac(n))

.sympy.polys.factortools.dmp_zz_diophantine

def dmp_zz_diophantine(F, c, A, d, p, u, K):
    if not A:
        S = [[] for _ in F]
        n = dup_degree(c)
        for i, coeff in enumerate(c):
            if not coeff:
                continue
            T = dup_zz_diophantine(F, n - i, p, K)
            for j, (s, t) in enumerate(zip(S, T)):
                t = dup_mul_ground(t, coeff, K)
                S[j] = dup_trunc(dup_add(s, t, K), p, K)
    else:
        n = len(A)
        e = dmp_expand(F, u, K)
        a, A = (A[-1], A[:-1])
        B, G = ([], [])
        for f in F:
            B.append(dmp_quo(e, f, u, K))
            G.append(dmp_eval_in(f, a, n, u, K))
        C = dmp_eval_in(c, a, n, u, K)
        v = u - 1
        S = dmp_zz_diophantine(G, C, A, d, p, v, K)
        S = [dmp_raise(s, 1, v, K) for s in S]
        for s, b in zip(S, B):
            c = dmp_sub_mul(c, s, b, u, K)
        c = dmp_ground_trunc(c, p, u, K)
        m = dmp_nest([K.one, -a], n, K)
        M = dmp_one(n, K)
        for k in K.map(range(0, d)):
            if dmp_zero_p(c, u):
                break
            M = dmp_mul(M, m, u, K)
            C = dmp_diff_eval_in(c, k + 1, a, n, u, K)
            if not dmp_zero_p(C, v):
                C = dmp_quo_ground(C, K.factorial(k + 1), v, K)
                T = dmp_zz_diophantine(G, C, A, d, p, v, K)
                for i, t in enumerate(T):
                    T[i] = dmp_mul(dmp_raise(t, 1, v, K), M, u, K)
                for i, (s, t) in enumerate(zip(S, T)):
                    S[i] = dmp_add(s, t, u, K)
                for t, b in zip(T, B):
                    c = dmp_sub_mul(c, t, b, u, K)
                c = dmp_ground_trunc(c, p, u, K)
        S = [dmp_ground_trunc(s, p, u, K) for s in S]
    return S

.sympy.polys.factortools.dup_zz_diophantine

def dup_zz_diophantine(F, m, p, K):
    if len(F) == 2:
        a, b = F
        f = gf_from_int_poly(a, p)
        g = gf_from_int_poly(b, p)
        s, t, G = gf_gcdex(g, f, p, K)
        s = gf_lshift(s, m, K)
        t = gf_lshift(t, m, K)
        q, s = gf_div(s, f, p, K)
        t = gf_add_mul(t, q, g, p, K)
        s = gf_to_int_poly(s, p)
        t = gf_to_int_poly(t, p)
        result = [s, t]
    else:
        G = [F[-1]]
        for f in reversed(F[1:-1]):
            G.insert(0, dup_mul(f, G[0], K))
        S, T = ([], [[1]])
        for f, g in zip(F, G):
            t, s = dmp_zz_diophantine([g, f], T[-1], [], 0, p, 1, K)
            T.append(t)
            S.append(s)
        result, S = ([], S + [T[-1]])
        for s, f in zip(S, F):
            s = gf_from_int_poly(s, p)
            f = gf_from_int_poly(f, p)
            r = gf_rem(gf_lshift(s, m, K), f, p, K)
            s = gf_to_int_poly(r, p)
            result.append(s)
    return result

.sympy.polys.galoistools.gf_lshift

def gf_lshift(f, n, K):
    if not f:
        return f
    else:
        return f + [K.zero] * n

.sympy.polys.galoistools.gf_add_mul

def gf_add_mul(f, g, h, p, K):
    return gf_add(f, gf_mul(g, h, p, K), p, K)

.sympy.polys.densearith.dmp_add_mul

def dmp_add_mul(f, g, h, u, K):
    return dmp_add(f, dmp_mul(g, h, u, K), u, K)

.sympy.core.numbers.Integer._eval_is_composite

def _eval_is_composite(self):
    if self > 1:
        return fuzzy_not(self.is_prime)
    else:
        return False

.sympy.core.numbers.Integer.__gt__

def __gt__(self, other):
    try:
        other = _sympify(other)
    except SympifyError:
        return NotImplemented
    if other.is_Integer:
        return _sympify(self.p > other.p)
    return Rational.__gt__(self, other)

from sympy.core import Basic, sympify, S
from sympy.core.mul import mul, Mul
from sympy.matrices.exceptions import NonInvertibleMatrixError
from sympy.matrices.matrixbase import MatrixBase
from .inverse import Inverse
from .matpow import MatPow
from .special import ZeroMatrix, Identity, GenericIdentity, OneMatrix

def combine_powers(mul):
    factor, args = mul.as_coeff_matrices()
    new_args = [args[0]]
    for i in range(1, len(args)):
        A = new_args[-1]
        B = args[i]
        if isinstance(B, Inverse) and isinstance(B.arg, MatMul):
            Bargs = B.arg.args
            l = len(Bargs)
            if list(Bargs) == new_args[-l:]:
                new_args = new_args[:-l] + [Identity(B.shape[0])]
                continue
        if isinstance(A, Inverse) and isinstance(A.arg, MatMul):
            Aargs = A.arg.args
            l = len(Aargs)
            if list(Aargs) == args[i:i + l]:
                identity = Identity(A.shape[0])
                new_args[-1] = identity
                for j in range(i, i + l):
                    args[j] = identity
                continue
        if A.is_square == False or B.is_square == False:
            new_args.append(B)
            continue
        if isinstance(A, MatPow):
            A_base, A_exp = A.args
        else:
            A_base, A_exp = (A, S.One)
        if isinstance(B, MatPow):
            B_base, B_exp = B.args
        else:
            B_base, B_exp = (B, S.One)
        if A_base == B_base:
            new_exp = A_exp + B_exp
            new_args[-1] = MatPow(A_base, new_exp).doit(deep=False)
            continue
        elif not isinstance(B_base, MatrixBase):
            try:
                B_base_inv = B_base.inverse()
            except NonInvertibleMatrixError:
                B_base_inv = None
            if B_base_inv is not None and A_base == B_base_inv:
                new_exp = A_exp - B_exp
                new_args[-1] = MatPow(A_base, new_exp).doit(deep=False)
                continue
        new_args.append(B)
    return newmul(factor, *new_args)

sympy.sympy.codegen.ast.__eq__

def __eq__(self, other):
    if not isinstance(other, self.__class__):
        return False
    for attr in self._fields:
        if getattr(self, attr) != getattr(other, attr):
            return False
    return True

sympy.sympy.core.basic.__eq__

def __eq__(self, other):
    """Return a boolean indicating whether a == b on the basis of
    their symbolic trees.

    This is the same as a.compare(b) == 0 but faster.

    Notes
    =====

    If a class that overrides __eq__() needs to retain the
    implementation of __hash__() from a parent class, the
    interpreter must be told this explicitly by setting
    __hash__ : Callable[[object], int] = <ParentClass>.__hash__.
    Otherwise the inheritance of __hash__() will be blocked,
    just as if __hash__ had been explicitly set to None.

    References
    ==========

    from https://docs.python.org/dev/reference/datamodel.html#object.__hash__
    """
    if self is other:
        return True

    if not isinstance(other, Basic):
        return self._do_eq_sympify(other)

    # check for pure number expr
    if  not (self.is_Number and other.is_Number) and (
            type(self) != type(other)):
        return False
    a, b = self._hashable_content(), other._hashable_content()
    if a != b:
        return False
    # check number *in* an expression
    for a, b in zip(a, b):
        if not isinstance(a, Basic):
            continue
        if a.is_Number and type(a) != type(b):
            return False
    return True

sympy.sympy.core.basic.args

@property
def args(self) -> tuple[Basic, ...]:
    """Returns a tuple of arguments of 'self'.

    Examples
    ========

    >>> from sympy import cot
    >>> from sympy.abc import x, y

    >>> cot(x).args
    (x,)

    >>> cot(x).args[0]
    x

    >>> (x*y).args
    (x, y)

    >>> (x*y).args[1]
    y

    Notes
    =====

    Never use self._args, always use self.args.
    Only use _args in __new__ when creating a new function.
    Do not override .args() from Basic (so that it is easy to
    change the interface in the future if needed).
    """
    return self._args

sympy.sympy.core.decorators._func

@wraps(func)
def _func(self, other):
    # XXX: The check for _op_priority here should be removed. It is
    # needed to stop mutable matrices from being sympified to
    # immutable matrices which breaks things in quantum...
    if not hasattr(other, '_op_priority'):
        try:
            other = sympify(other, strict=True)
        except SympifyError:
            return retval
    if not isinstance(other, expectedcls):
        return retval
    return func(self, other)

sympy.sympy.core.decorators.__sympifyit_wrapper

@wraps(func)
def __sympifyit_wrapper(a, b):
    try:
        # If an external class has _op_priority, it knows how to deal
        # with SymPy objects. Otherwise, it must be converted.
        if not hasattr(b, '_op_priority'):
            b = sympify(b, strict=True)
        return func(a, b)
    except SympifyError:
        return retval

sympy.sympy.core.numbers.__add__

def __add__(self, other):
    if global_parameters.evaluate:
        if isinstance(other, int):
            return Integer(self.p + other)
        elif isinstance(other, Integer):
            return Integer(self.p + other.p)
        elif isinstance(other, Rational):
            return Rational._new(self.p*other.q + other.p, other.q, 1)
        return Rational.__add__(self, other)
    else:
        return Add(self, other)

sympy.sympy.core.numbers.__sub__

def __sub__(self, other):
    if global_parameters.evaluate:
        if isinstance(other, int):
            return Integer(self.p - other)
        elif isinstance(other, Integer):
            return Integer(self.p - other.p)
        elif isinstance(other, Rational):
            return Rational._new(self.p*other.q - other.p, other.q, 1)
        return Rational.__sub__(self, other)
    return Rational.__sub__(self, other)

sympy.sympy.matrices.expressions.inverse.arg

@property
def arg(self):
    return self.args[0]

sympy.sympy.matrices.expressions.inverse.shape

@property
