.sympy.core.exprtools.decompose_power

def decompose_power(expr):
    base, exp = expr.as_base_exp()
    if exp.is_Number:
        if exp.is_Rational:
            if not exp.is_Integer:
                base = Pow(base, Rational(1, exp.q))
            exp = exp.p
        else:
            base, exp = (expr, 1)
    else:
        exp, tail = exp.as_coeff_Mul(rational=True)
        if exp is S.NegativeOne:
            base, exp = (Pow(base, tail), -1)
        elif exp is not S.One:
            tail = _keep_coeff(Rational(1, exp.q), tail)
            base, exp = (Pow(base, tail), exp.p)
        else:
            base, exp = (expr, 1)
    return (base, exp)

.sympy.core.power.Pow.as_base_exp

def as_base_exp(self):
    b, e = self.args
    if b.is_Rational and b.p == 1 and (b.q != 1):
        return (Integer(b.q), -e)
    return (b, e)

.sympy.polys.polyoptions.Options.clone

def clone(self, updates={}):
    obj = dict.__new__(self.__class__)
    for option, value in self.items():
        obj[option] = value
    for option, value in updates.items():
        obj[option] = value
    return obj

.sympy.polys.polytools.Poly._from_dict

def _from_dict(cls, rep, opt):
    gens = opt.gens
    if not gens:
        raise GeneratorsNeeded("can't initialize from 'dict' without generators")
    level = len(gens) - 1
    domain = opt.domain
    if domain is None:
        domain, rep = construct_domain(rep, opt=opt)
    else:
        for monom, coeff in rep.items():
            rep[monom] = domain.convert(coeff)
    return cls.new(DMP.from_dict(rep, level, domain), *gens)

.sympy.polys.polyoptions.Option.default

def default(cls):
    return None

.sympy.polys.constructor.construct_domain

def construct_domain(obj, **args):
    opt = build_options(args)
    if hasattr(obj, '__iter__'):
        if isinstance(obj, dict):
            if not obj:
                monoms, coeffs = ([], [])
            else:
                monoms, coeffs = list(zip(*list(obj.items())))
        else:
            coeffs = obj
    else:
        coeffs = [obj]
    coeffs = list(map(sympify, coeffs))
    result = _construct_simple(coeffs, opt)
    if result is not None:
        if result is not False:
            domain, coeffs = result
        else:
            domain, coeffs = _construct_expression(coeffs, opt)
    else:
        if opt.composite is False:
            result = None
        else:
            result = _construct_composite(coeffs, opt)
        if result is not None:
            domain, coeffs = result
        else:
            domain, coeffs = _construct_expression(coeffs, opt)
    if hasattr(obj, '__iter__'):
        if isinstance(obj, dict):
            return (domain, dict(list(zip(monoms, coeffs))))
        else:
            return (domain, coeffs)
    else:
        return (domain, coeffs[0])

.sympy.polys.constructor._construct_simple

def _construct_simple(coeffs, opt):
    result, rationals, reals, algebraics = ({}, False, False, False)
    if opt.extension is True:
        is_algebraic = lambda coeff: coeff.is_number and coeff.is_algebraic
    else:
        is_algebraic = lambda coeff: False
    for coeff in coeffs:
        if coeff.is_Rational:
            if not coeff.is_Integer:
                rationals = True
        elif coeff.is_Float:
            if not algebraics:
                reals = True
            else:
                return False
        elif is_algebraic(coeff):
            if not reals:
                algebraics = True
            else:
                return False
        else:
            return None
    if algebraics:
        domain, result = _construct_algebraic(coeffs, opt)
    else:
        if reals:
            max_prec = max([c._prec for c in coeffs])
            domain = RealField(prec=max_prec)
        elif opt.field or rationals:
            domain = QQ
        else:
            domain = ZZ
        result = []
        for coeff in coeffs:
            result.append(domain.from_sympy(coeff))
    return (domain, result)

.sympy.polys.domains.pythonintegerring.PythonIntegerRing.from_sympy

def from_sympy(self, a):
    if a.is_Integer:
        return PythonInteger(a.p)
    elif a.is_Float and int(a) == a:
        return PythonInteger(int(a))
    else:
        raise CoercionFailed('expected an integer, got %s' % a)

.sympy.polys.polyclasses.DMP.from_dict

def from_dict(cls, rep, lev, dom):
    return cls(dmp_from_dict(rep, lev, dom), dom, lev)

.sympy.polys.densebasic.dmp_from_dict

def dmp_from_dict(f, u, K):
    if not u:
        return dup_from_dict(f, K)
    if not f:
        return dmp_zero(u)
    coeffs = {}
    for monom, coeff in f.items():
        head, tail = (monom[0], monom[1:])
        if head in coeffs:
            coeffs[head][tail] = coeff
        else:
            coeffs[head] = {tail: coeff}
    n, v, h = (max(coeffs.keys()), u - 1, [])
    for k in range(n, -1, -1):
        coeff = coeffs.get(k)
        if coeff is not None:
            h.append(dmp_from_dict(coeff, v, K))
        else:
            h.append(dmp_zero(v))
    return dmp_strip(h, u)

.sympy.polys.densebasic.dup_from_dict

def dup_from_dict(f, K):
    if not f:
        return []
    n, h = (max(f.keys()), [])
    if type(n) is int:
        for k in range(n, -1, -1):
            h.append(f.get(k, K.zero))
    else:
        n, = n
        for k in range(n, -1, -1):
            h.append(f.get((k,), K.zero))
    return dup_strip(h)

.sympy.polys.densebasic.dup_strip

def dup_strip(f):
    if not f or f[0]:
        return f
    i = 0
    for cf in f:
        if cf:
            break
        else:
            i += 1
    return f[i:]

.sympy.polys.polyclasses.DMP.__init__

def __init__(self, rep, dom, lev=None, ring=None):
    if lev is not None:
        if type(rep) is dict:
            rep = dmp_from_dict(rep, lev, dom)
        elif type(rep) is not list:
            rep = dmp_ground(dom.convert(rep), lev)
    else:
        rep, lev = dmp_validate(rep)
    self.rep = rep
    self.lev = lev
    self.dom = dom
    self.ring = ring

.sympy.polys.polytools.Poly.new

def new(cls, rep, *gens):
    if not isinstance(rep, DMP):
        raise PolynomialError('invalid polynomial representation: %s' % rep)
    elif rep.lev != len(gens) - 1:
        raise PolynomialError('invalid arguments: %s, %s' % (rep, gens))
    obj = Basic.__new__(cls)
    obj.rep = rep
    obj.gens = gens
    return obj

.sympy.polys.polyroots.roots

def roots(f, *gens, **flags):
    from sympy.polys.polytools import to_rational_coeffs
    flags = dict(flags)
    auto = flags.pop('auto', True)
    cubics = flags.pop('cubics', True)
    trig = flags.pop('trig', False)
    quartics = flags.pop('quartics', True)
    quintics = flags.pop('quintics', False)
    multiple = flags.pop('multiple', False)
    filter = flags.pop('filter', None)
    predicate = flags.pop('predicate', None)
    if isinstance(f, list):
        if gens:
            raise ValueError('redundant generators given')
        x = Dummy('x')
        poly, i = ({}, len(f) - 1)
        for coeff in f:
            poly[i], i = (sympify(coeff), i - 1)
        f = Poly(poly, x, field=True)
    else:
        try:
            f = Poly(f, *gens, **flags)
            if f.length == 2 and f.degree() != 1:
                n = f.degree()
                npow_bases = []
                expr = f.as_expr()
                con = expr.as_independent(*gens)[0]
                for p in Mul.make_args(con):
                    if p.is_Pow and (not p.exp % n):
                        npow_bases.append(p.base ** (p.exp / n))
                    else:
                        other.append(p)
                    if npow_bases:
                        b = Mul(*npow_bases)
                        B = Dummy()
                        d = roots(Poly(expr - con + B ** n * Mul(*others), *gens, **flags), *gens, **flags)
                        rv = {}
                        for k, v in d.items():
                            rv[k.subs(B, b)] = v
                        return rv
        except GeneratorsNeeded:
            if multiple:
                return []
            else:
                return {}
        if f.is_multivariate:
            raise PolynomialError('multivariate polynomials are not supported')

    def _update_dict(result, root, k):
        if root in result:
            result[root] += k
        else:
            result[root] = k

    def _try_decompose(f):
        factors, roots = (f.decompose(), [])
        for root in _try_heuristics(factors[0]):
            roots.append(root)
        for factor in factors[1:]:
            previous, roots = (list(roots), [])
            for root in previous:
                g = factor - Poly(root, f.gen)
                for root in _try_heuristics(g):
                    roots.append(root)
        return roots

    def _try_heuristics(f):
        if f.is_ground:
            return []
        if f.is_monomial:
            return [S(0)] * f.degree()
        if f.length() == 2:
            if f.degree() == 1:
                return list(map(cancel, roots_linear(f)))
            else:
                return roots_binomial(f)
        result = []
        for i in [-1, 1]:
            if not f.eval(i):
                f = f.quo(Poly(f.gen - i, f.gen))
                result.append(i)
                break
        n = f.degree()
        if n == 1:
            result += list(map(cancel, roots_linear(f)))
        elif n == 2:
            result += list(map(cancel, roots_quadratic(f)))
        elif f.is_cyclotomic:
            result += roots_cyclotomic(f)
        elif n == 3 and cubics:
            result += roots_cubic(f, trig=trig)
        elif n == 4 and quartics:
            result += roots_quartic(f)
        elif n == 5 and quintics:
            result += roots_quintic(f)
        return result
    (k,), f = f.terms_gcd()
    if not k:
        zeros = {}
    else:
        zeros = {S(0): k}
    coeff, f = preprocess_roots(f)
    if auto and f.get_domain().is_Ring:
        f = f.to_field()
    rescale_x = None
    translate_x = None
    result = {}
    if not f.is_ground:
        if not f.get_domain().is_Exact:
            for r in f.nroots():
                _update_dict(result, r, 1)
        elif f.degree() == 1:
            result[roots_linear(f)[0]] = 1
        elif f.length() == 2:
            roots_fun = roots_quadratic if f.degree() == 2 else roots_binomial
            for r in roots_fun(f):
                _update_dict(result, r, 1)
        else:
            _, factors = Poly(f.as_expr()).factor_list()
            if len(factors) == 1 and f.degree() == 2:
                for r in roots_quadratic(f):
                    _update_dict(result, r, 1)
            elif len(factors) == 1 and factors[0][1] == 1:
                if f.get_domain().is_EX:
                    res = to_rational_coeffs(f)
                    if res:
                        if res[0] is None:
                            translate_x, f = res[2:]
                        else:
                            rescale_x, f = (res[1], res[-1])
                        result = roots(f)
                        if not result:
                            for root in _try_decompose(f):
                                _update_dict(result, root, 1)
                    else:
                        for r in _try_heuristics(f):
                            _update_dict(result, r, 1)
                else:
                    for root in _try_decompose(f):
                        _update_dict(result, root, 1)
            else:
                for factor, k in factors:
                    for r in _try_heuristics(Poly(factor, f.gen, field=True)):
                        _update_dict(result, r, k)
    if coeff is not S.One:
        _result, result = (result, {})
        for root, k in _result.items():
            result[coeff * root] = k
    result.update(zeros)
    if filter not in [None, 'C']:
        handlers = {'Z': lambda r: r.is_Integer, 'Q': lambda r: r.is_Rational, 'R': lambda r: r.is_real, 'I': lambda r: r.is_imaginary}
        try:
            query = handlers[filter]
        except KeyError:
            raise ValueError('Invalid filter: %s' % filter)
        for zero in dict(result).keys():
            if not query(zero):
                del result[zero]
    if predicate is not None:
        for zero in dict(result).keys():
            if not predicate(zero):
                del result[zero]
    if rescale_x:
        result1 = {}
        for k, v in result.items():
            result1[k * rescale_x] = v
        result = result1
    if translate_x:
        result1 = {}
        for k, v in result.items():
            result1[k + translate_x] = v
        result = result1
    if not multiple:
        return result
    else:
        zeros = []
        for zero in ordered(result):
            zeros.extend([zero] * result[zero])
        return zeros

