.sympy.polys.densebasic.dmp_terms_gcd

def dmp_terms_gcd(f, u, K):
    if dmp_ground_TC(f, u, K) or dmp_zero_p(f, u):
        return ((0,) * (u + 1), f)
    F = dmp_to_dict(f, u)
    G = monomial_min(*list(F.keys()))
    if all((g == 0 for g in G)):
        return (G, f)
    f = {}
    for monom, coeff in F.items():
        f[monomial_div(monom, G)] = coeff
    return (G, dmp_from_dict(f, u, K))

.sympy.polys.densebasic.dmp_ground_TC

def dmp_ground_TC(f, u, K):
    while u:
        f = dmp_TC(f, K)
        u -= 1
    return dup_TC(f, K)

.sympy.polys.densebasic.poly_TC

def poly_TC(f, K):
    if not f:
        return K.zero
    else:
        return f[-1]

.sympy.polys.densebasic.dmp_zero_p

def dmp_zero_p(f, u):
    while u:
        if len(f) != 1:
            return False
        f = f[0]
        u -= 1
    return not f

.sympy.polys.densebasic.dmp_to_dict

def dmp_to_dict(f, u, K=None, zero=False):
    if not u:
        return dup_to_dict(f, K, zero=zero)
    if dmp_zero_p(f, u) and zero:
        return {(0,) * (u + 1): K.zero}
    n, v, result = (dmp_degree(f, u), u - 1, {})
    if n == -oo:
        n = -1
    for k in range(0, n + 1):
        h = dmp_to_dict(f[n - k], v)
        for exp, coeff in h.items():
            result[(k,) + exp] = coeff
    return result

.sympy.polys.densebasic.dup_to_dict

def dup_to_dict(f, K=None, zero=False):
    if not f and zero:
        return {(0,): K.zero}
    n, result = (len(f) - 1, {})
    for k in range(0, n + 1):
        if f[n - k]:
            result[k,] = f[n - k]
    return result

.sympy.polys.monomials.monomial_min

def monomial_min(*monoms):
    M = list(monoms[0])
    for N in monoms[1:]:
        for i, n in enumerate(N):
            M[i] = min(M[i], n)
    return tuple(M)

.sympy.polys.monomials.monomial_div

def monomial_div(A, B):
    C = monomial_ldiv(A, B)
    if all((c >= 0 for c in C)):
        return tuple(C)
    else:
        return None

.sympy.polys.monomials.monomial_ldiv

def monomial_ldiv(A, B):
    return tuple([a - b for a, b in zip(A, B)])

.sympy.polys.polyclasses.DMP.per

def per(f, rep, dom=None, kill=False, ring=None):
    lev = f.lev
    if kill:
        if not lev:
            return rep
        else:
            lev -= 1
    if dom is None:
        dom = f.dom
    if ring is None:
        ring = f.ring
    return DMP(rep, dom, lev, ring)

.sympy.polys.polytools.Poly.per

def per(f, rep, gens=None, remove=None):
    if gens is None:
        gens = f.gens
    if remove is not None:
        gens = gens[:remove] + gens[remove + 1:]
        if not gens:
            return f.rep.dom.to_sympy(rep)
    return f.__class__.new(rep, *gens)

.sympy.polys.polyroots.preprocess_roots

def preprocess_roots(poly):
    coeff = S.One
    try:
        _, poly = poly.clear_denoms(convert=True)
    except DomainError:
        return (coeff, poly)
    poly = poly.primitive()[1]
    poly = poly.retract()
    if poly.get_domain().is_Poly and all((c.is_term for c in poly.rep.coeffs())):
        poly = poly.inject()
        strips = list(zip(*poly.monoms()))
        gens = list(poly.gens[1:])
        base, strips = (strips[0], strips[1:])
        for gen, strip in zip(list(gens), strips):
            reverse = False
            if strip[0] < strip[-1]:
                strip = reversed(strip)
                reverse = True
            ratio = None
            for a, b in zip(base, strip):
                if not a and (not b):
                    continue
                elif not a or not b:
                    break
                elif b % a != 0:
                    break
                else:
                    _ratio = b // a
                    if ratio is None:
                        ratio = _ratio
                    elif ratio != _ratio:
                        break
            else:
                if reverse:
                    ratio = -ratio
                poly = poly.eval(gen, 1)
                coeff *= gen ** (-ratio)
                gens.remove(gen)
        if gens:
            poly = poly.eject(*gens)
    if poly.is_univariate and poly.get_domain().is_ZZ:
        basis = _integer_basis(poly)
        if basis is not None:
            n = poly.degree()

            def func(k, coeff):
                return coeff // basis ** (n - k[0])
            poly = poly.termwise(func)
            coeff *= basis
    return (coeff, poly)

.sympy.polys.polytools.Poly.clear_denoms

def clear_denoms(self, convert=False):
    f = self
    if not f.rep.dom.is_Field:
        return (S.One, f)
    dom = f.get_domain()
    if dom.has_assoc_Ring:
        dom = f.rep.dom.get_ring()
    if hasattr(f.rep, 'clear_denoms'):
        coeff, result = f.rep.clear_denoms()
    else:
        raise OperationNotSupported(f, 'clear_denoms')
    coeff, f = (dom.to_sympy(coeff), f.per(result))
    if not convert or not dom.has_assoc_Ring:
        return (coeff, f)
    else:
        return (coeff, f.to_ring())

