.sympy.polys.polyoptions.Domain.preprocess

def preprocess(cls, domain):
    if isinstance(domain, sympy.polys.domains.Domain):
        return domain
    elif hasattr(domain, 'to_domain'):
        return domain.to_domain()
    elif isinstance(domain, string_types):
        if domain in ['Z', 'ZZ']:
            return sympy.polys.domains.ZZ
        if domain in ['Q', 'QQ']:
            return sympy.polys.domains.QQ
        if domain == 'EX':
            return sympy.polys.domains.EX
        r = cls._re_realfield.match(domain)
        if r is not None:
            _, _, prec = r.groups()
            if prec is None:
                return sympy.polys.domains.RR
            else:
                return sympy.polys.domains.RealField(int(prec))
        r = cls._re_complexfield.match(domain)
        if r is not None:
            _, _, prec = r.groups()
            if prec is None:
                return sympy.polys.domains.CC
            else:
                return sympy.polys.domains.ComplexField(int(prec))
        r = cls._re_finitefield.match(domain)
        if r is not None:
            return sympy.polys.domains.FF(int(r.groups()[1]))
        r = cls._re_polynomial.match(domain)
        if r is not None:
            ground, gens = r.groups()
            gens = list(map(sympify, gens.split(',')))
            if ground in ['Z', 'ZZ']:
                return sympy.polys.domains.ZZ.poly_ring(*gens)
            else:
                return sympy.polys.domains.QQ.poly_ring(*gens)
        r = cls._re_fraction.match(domain)
        if r is not None:
            ground, gens = r.groups()
            gens = list(map(sympify, gens.split(',')))
            if ground in ['Z', 'ZZ']:
                return sympy.polys.domains.ZZ.frac_field(*gens)
            else:
                return sympy.polys.domains.QQ.frac_field(*gens)
        r = cls._re_algebraic.match(domain)
        if r is not None:
            gens = list(map(sympify, r.groups()[1].split(',')))
            return sympy.polys.domains.QQ.algebraic_field(*gens)
    raise OptionError('expected a valid domain specification, got %s' % domain)

.sympy.polys.domains.domain.Domain.convert

def convert(self, element, base=None):
    if base is not None:
        return self.convert_from(element, base)
    if self.of_type(element):
        return element
    from sympy.polys.domains import PythonIntegerRing, GMPYIntegerRing, GMPYRationalField, RealField, ComplexField
    if isinstance(element, integer_types):
        return self.convert_from(element, PythonIntegerRing())
    if HAS_GMPY:
        integers = GMPYIntegerRing()
        if isinstance(element, integers.tp):
            return self.convert_from(element, integers)
        rationals = GMPYRationalField()
        if isinstance(element, rationals.tp):
            return self.convert_from(element, rationals)
    if isinstance(element, float):
        parent = RealField(tol=False)
        return self.convert_from(parent(element), parent)
    if isinstance(element, complex):
        parent = ComplexField(tol=False)
        return self.convert_from(parent(element), parent)
    if isinstance(element, DomainElement):
        return self.convert_from(element, element.parent())
    if self.is_Numerical and getattr(element, 'is_ground', False):
        return self.convert(element.LC())
    if isinstance(element, Basic):
        try:
            return self.from_sympy(element)
        except (TypeError, ValueError):
            pass
    elif not is_sequence(element):
        try:
            element = sympify(element)
            if isinstance(element, Basic):
                return self.from_sympy(element)
        except (TypeError, ValueError):
            pass
    raise CoercionFailed("can't convert %s of type %s to %s" % (element, type(element), self))

