.sympy.core.assumptions._ask

def _ask(fact, obj):
    assumptions = obj._assumptions
    handler_map = obj._prop_handler
    assumptions._tell(fact, None)
    try:
        evaluate = handler_map[fact]
    except KeyError:
        pass
    else:
        a = evaluate(obj)
        if a is not None:
            assumptions.deduce_all_facts(((fact, a),))
            return a
    prereq = list(_assume_rules.prereq[fact])
    shuffle(prereq)
    for pk in prereq:
        if pk in assumptions:
            continue
        if pk in handler_map:
            _ask(pk, obj)
            ret_val = assumptions.get(fact)
            if ret_val is not None:
                return ret_val
    return None

.sympy.core.facts.FactKB._tell

def _tell(self, k, v):
    if k in self and self[k] is not None:
        if self[k] == v:
            return False
        else:
            raise InconsistentAssumptions(self, k, v)
    else:
        self[k] = v
        return True

.sympy.core.numbers.Rational._eval_is_zero

def _eval_is_zero(self):
    return self.p == 0

.sympy.core.facts.FactKB.deduce_all_facts

def deduce_all_facts(self, facts):
    full_implications = self.rules.full_implications
    beta_triggers = self.rules.beta_triggers
    beta_rules = self.rules.beta_rules
    if isinstance(facts, dict):
        facts = facts.items()
    while facts:
        beta_maytrigger = set()
        for k, v in facts:
            if not self._tell(k, v) or v is None:
                continue
            for key, value in full_implications[k, v]:
                self._tell(key, value)
            beta_maytrigger.update(beta_triggers[k, v])
        facts = []
        for bidx in beta_maytrigger:
            bcond, bimpl = beta_rules[bidx]
            if all((self.get(k) is v for k, v in bcond)):
                facts.append(bimpl)

.sympy.functions.elementary.trigonometric.TrigonometricFunction._period

def _period(self, general_period, symbol=None):
    f = self.args[0]
    if symbol is None:
        symbol = tuple(f.free_symbols)[0]
    if not f.has(symbol):
        return S.Zero
    if f == symbol:
        return general_period
    if symbol in f.free_symbols:
        p, q = (Wild('p'), Wild('q'))
        if f.is_Mul:
            g, h = f.as_independent(symbol)
            if h == symbol:
                return general_period / abs(g)
        if f.is_Add:
            a, h = f.as_independent(symbol)
            g, h = h.as_independent(symbol, as_Add=False)
            if h == symbol:
                return general_period / abs(g)
    raise NotImplementedError('Use the periodicity function instead.')

.sympy.core.basic.Basic.has

def has(self, *patterns):
    return any((self._has(pattern) for pattern in patterns))

.sympy.core.basic.Basic._has

def _has(self, pattern):
    from sympy.core.function import UndefinedFunction, Function
    if isinstance(pattern, UndefinedFunction):
        return any((f.func == pattern or f == pattern for f in self.atoms(Function, UndefinedFunction)))
    pattern = sympify(pattern)
    if isinstance(pattern, BasicMeta):
        return any((isinstance(arg, pattern) for arg in preorder_traversal(self)))
    try:
        match = pattern._has_matcher()
        return any((match(arg) for arg in preorder_traversal(self)))
    except AttributeError:
        return any((arg == pattern for arg in preorder_traversal(self)))

.sympy.core.basic.Basic._has_matcher

def _has_matcher(self):
    return lambda other: self == other

.sympy.functions.elementary.trigonometric.tan.eval

def eval(cls, arg):
    from sympy.calculus.util import AccumBounds
    if arg.is_Number:
        if arg is S.NaN:
            return S.NaN
        elif arg is S.Zero:
            return S.Zero
        elif arg is S.Infinity or arg is S.NegativeInfinity:
            return AccumBounds(S.NegativeInfinity, S.Infinity)
    if isinstance(arg, AccumBounds):
        min, max = (arg.min, arg.max)
        d = floor(min / S.Pi)
        if min is not S.NegativeInfinity:
            min = min - d * S.Pi
        if max is not S.Infinity:
            max = max - d * S.Pi
        if AccumBounds(min, max).intersection(FiniteSet(S.Pi / 2, 3 * S.Pi / 2)):
            return AccumBounds(S.NegativeInfinity, S.Infinity)
        else:
            return AccumBounds(tan(min), tan(max))
    if arg.could_extract_minus_sign():
        return -cls(-arg)
    i_coeff = arg.as_coefficient(S.ImaginaryUnit)
    if i_coeff is not None:
        return S.ImaginaryUnit * tanh(i_coeff)
    pi_coeff = _pi_coeff(arg, 2)
    if pi_coeff is not None:
        if pi_coeff.is_integer:
            return S.Zero
        if not pi_coeff.is_Rational:
            narg = pi_coeff * S.Pi
            if narg != arg:
                return cls(narg)
            return None
        if pi_coeff.is_Rational:
            if not pi_coeff.q % 2:
                narg = pi_coeff * S.Pi * 2
                cresult, sresult = (cos(narg), cos(narg - S.Pi / 2))
                if not isinstance(cresult, cos) and (not isinstance(sresult, cos)):
                    if sresult == 0:
                        return S.ComplexInfinity
                    return (1 - cresult) / sresult
            table2 = {12: (3, 4), 20: (4, 5), 30: (5, 6), 15: (6, 10), 24: (6, 8), 40: (8, 10), 60: (20, 30), 120: (40, 60)}
            q = pi_coeff.q
            p = pi_coeff.p % q
            if q in table2:
                nvala, nvalb = (cls(p * S.Pi / table2[q][0]), cls(p * S.Pi / table2[q][1]))
                if None == nvala or None == nvalb:
                    return None
                return (nvala - nvalb) / (1 + nvala * nvalb)
            narg = ((pi_coeff + S.Half) % 1 - S.Half) * S.Pi
            cresult, sresult = (cos(narg), cos(narg - S.Pi / 2))
            if not isinstance(cresult, cos) and (not isinstance(sresult, cos)):
                if cresult == 0:
                    return S.ComplexInfinity
                return sresult / cresult
            if narg != arg:
                return cls(narg)
    if arg.is_Add:
        x, m = _peeloff_pi(arg)
        if m:
            tanm = tan(m)
            tanx = tan(x)
            if tanm is S.ComplexInfinity:
                return -cot(x)
            return (tanm + tanx) / (1 - tanm * tanx)
    if arg.func is atan:
        return arg.args[0]
    if arg.func is atan2:
        y, x = arg.args
        return y / x
    if arg.func is asin:
        x = arg.args[0]
        return x / sqrt(1 - x ** 2)
    if arg.func is acos:
        x = arg.args[0]
        return sqrt(1 - x ** 2) / x
    if arg.func is acot:
        x = arg.args[0]
        return 1 / x
    if arg.func is acsc:
        x = arg.args[0]
        return 1 / (sqrt(1 - 1 / x ** 2) * x)
    if arg.func is asec:
        x = arg.args[0]
        return sqrt(1 - 1 / x ** 2) * x

.sympy.functions.elementary.trigonometric.tan.period

def period(self, symbol=None):
    return self._period(pi, symbol)

import sys
import typing
from typing import Any, Callable, Dict, Generator, List, Tuple, TypeVar, Union
from docutils import nodes
from docutils.parsers.rst.states import Inliner
from typing import ForwardRef
from typing import _ForwardRef
DirectiveOption = Callable[[str], Any]
TextlikeNode = Union[nodes.Text, nodes.TextElement]
NoneType = type(None)
PathMatcher = Callable[[str], bool]
RoleFunction = Callable[[str, str, str, int, Inliner, Dict[str, Any], List[str]], Tuple[List[nodes.Node], List[nodes.system_message]]]
TitleGetter = Callable[[nodes.Node], str]
Inventory = Dict[str, Dict[str, Tuple[str, str, str, str]]]

def _stringify_py37(annotation: Any) -> str:
    module = getattr(annotation, '__module__', None)
    if module == 'typing':
        if getattr(annotation, '_name', None):
            qualname = annotation._name
        elif getattr(annotation, '__qualname__', None):
            qualname = annotation.__qualname__
        elif getattr(annotation, '__forward_arg__', None):
            qualname = annotation.__forward_arg__
        else:
            qualname = stringify(annotation.__origin__)
    elif hasattr(annotation, '__qualname__'):
        qualname = '%s.%s' % (module, annotation.__qualname__)
    elif hasattr(annotation, '__origin__'):
        qualname = stringify(annotation.__origin__)
    else:
        return repr(annotation)
    if getattr(annotation, '__args__', None):
        if not isinstance(annotation.__args__, (list, tuple)):
            pass
        elif qualname == 'Union':
            if len(annotation.__args__) > 1 and annotation.__args__[-1] is NoneType:
                if len(annotation.__args__) > 2:
                    args = ', '.join((stringify(a) for a in annotation.__args__[:-1]))
                    return 'Optional[Union[%s]]' % args
                else:
                    return 'Optional[%s]' % stringify(annotation.__args__[0])
            else:
                args = ', '.join((stringify(a) for a in annotation.__args__))
                return 'Union[%s]' % args
        elif qualname == 'Callable':
            args = ', '.join((stringify(a) for a in annotation.__args__[:-1]))
            returns = stringify(annotation.__args__[-1])
            return '%s[[%s], %s]' % (qualname, args, returns)
        elif str(annotation).startswith('typing.Annotated'):
            return stringify(annotation.__args__[0])
        elif all((is_system_TypeVar(a) for a in annotation.__args__)):
            return qualname
        else:
            args = ', '.join((stringify(a) for a in annotation.__args__))
            return '%s[%s]' % (qualname, args)
    return qualname

.sphinx.util.typing.is_system_TypeVar

def is_system_TypeVar(typ: Any) -> bool:
    modname = getattr(typ, '__module__', '')
    return modname == 'typing' and isinstance(typ, TypeVar)

.sphinx.util.typing.stringify

def stringify(annotation: Any) -> str:
    if isinstance(annotation, str):
        if annotation.startswith("'") and annotation.endswith("'"):
            return annotation[1:-2]
        else:
            return annotation
    elif isinstance(annotation, TypeVar):
        return annotation.__name__
    elif not annotation:
        return repr(annotation)
    elif annotation is NoneType:
        return 'None'
    elif getattr(annotation, '__module__', None) == 'builtins' and hasattr(annotation, '__qualname__'):
        return annotation.__qualname__
    elif annotation is Ellipsis:
        return '...'
    if sys.version_info >= (3, 7):
        return _stringify_py37(annotation)
    else:
        return _stringify_py36(annotation)

import numbers
import array
from collections.abc import Iterable
import numpy as np
from scipy import linalg
import scipy.sparse as sp
from ..preprocessing import MultiLabelBinarizer
from ..utils import check_array, check_random_state
from ..utils import shuffle as util_shuffle
from ..utils.random import sample_without_replacement

def make_classification(n_samples=100, n_features=20, n_informative=2, n_redundant=2, n_repeated=0, n_classes=2, n_clusters_per_class=2, weights=None, flip_y=0.01, class_sep=1.0, hypercube=True, shift=0.0, scale=1.0, shuffle=True, random_state=None):
    generator = check_random_state(random_state)
    if n_informative + n_redundant + n_repeated > n_features:
        raise ValueError('Number of informative, redundant and repeated features must sum to less than the number of total features')
    if n_informative < np.log2(n_classes * n_clusters_per_class):
        msg = 'n_classes({}) * n_clusters_per_class({}) must be'
        msg += ' smaller or equal 2**n_informative({})={}'
        raise ValueError(msg.format(n_classes, n_clusters_per_class, n_informative, 2 ** n_informative))
    if weights is not None:
        if len(weights) not in [n_classes, n_classes - 1]:
            raise ValueError('Weights specified but incompatible with number of classes.')
        if len(weights) == n_classes - 1:
            if isinstance(weights, list):
                weights = weights + [1.0 - sum(weights)]
            else:
                weights = np.resize(weights, n_classes)
                weights[-1] = 1.0 - sum(weights[:-1])
    else:
        weights = [1.0 / n_classes] * n_classes
    n_useless = n_features - n_informative - n_redundant - n_repeated
    n_clusters = n_classes * n_clusters_per_class
    n_samples_per_cluster = [int(n_samples * weights[k % n_classes] / n_clusters_per_class) for k in range(n_clusters)]
    for i in range(n_samples - sum(n_samples_per_cluster)):
        n_samples_per_cluster[i % n_clusters] += 1
    X = np.zeros((n_samples, n_features))
    y = np.zeros(n_samples, dtype=np.int)
    centroids = _generate_hypercube(n_clusters, n_informative, generator).astype(float, copy=False)
    centroids *= 2 * class_sep
    centroids -= class_sep
    if not hypercube:
        centroids *= generator.rand(n_clusters, 1)
        centroids *= generator.rand(1, n_informative)
    X[:, :n_informative] = generator.randn(n_samples, n_informative)
    stop = 0
    for k, centroid in enumerate(centroids):
        start, stop = (stop, stop + n_samples_per_cluster[k])
        y[start:stop] = k % n_classes
        X_k = X[start:stop, :n_informative]
        A = 2 * generator.rand(n_informative, n_informative) - 1
        X_k[...] = np.dot(X_k, A)
        X_k += centroid
    if n_redundant > 0:
        B = 2 * generator.rand(n_informative, n_redundant) - 1
        X[:, n_informative:n_informative + n_redundant] = np.dot(X[:, :n_informative], B)
    if n_repeated > 0:
        n = n_informative + n_redundant
        indices = ((n - 1) * generator.rand(n_repeated) + 0.5).astype(np.intp)
        X[:, n:n + n_repeated] = X[:, indices]
    if n_useless > 0:
        X[:, -n_useless:] = generator.randn(n_samples, n_useless)
    if flip_y >= 0.0:
        flip_mask = generator.rand(n_samples) < flip_y
        y[flip_mask] = generator.randint(n_classes, size=flip_mask.sum())
    if shift is None:
        shift = (2 * generator.rand(n_features) - 1) * class_sep
    X += shift
    if scale is None:
        scale = 1 + 100 * generator.rand(n_features)
    X *= scale
    if shuffle:
        X, y = util_shuffle(X, y, random_state=generator)
        indices = np.arange(n_features)
        generator.shuffle(indices)
        X[:, :] = X[:, indices]
    return (X, y)

.sklearn.utils.validation.check_random_state

def check_random_state(seed):
    if seed is None or seed is np.random:
        return np.random.mtrand._rand
    if isinstance(seed, numbers.Integral):
        return np.random.RandomState(seed)
    if isinstance(seed, np.random.RandomState):
        return seed
    raise ValueError('%r cannot be used to seed a numpy.random.RandomState instance' % seed)

.sklearn.datasets.samples_generator._generate_hypercube

def _generate_hypercube(samples, dimensions, rng):
    if dimensions > 30:
        return np.hstack([rng.randint(2, size=(samples, dimensions - 30)), _generate_hypercube(samples, 30, rng)])
    out = sample_without_replacement(2 ** dimensions, samples, random_state=rng).astype(dtype='>u4', copy=False)
    out = np.unpackbits(out.view('>u1')).reshape((-1, 32))[:, -dimensions:]
    return out

.sklearn.utils.__init__.shuffle

def shuffle(*arrays, **options):
    options['replace'] = False
    return resample(*arrays, **options)

.sklearn.utils.__init__.resample

def resample(*arrays, **options):
    random_state = check_random_state(options.pop('random_state', None))
    replace = options.pop('replace', True)
    max_n_samples = options.pop('n_samples', None)
    stratify = options.pop('stratify', None)
    if options:
        raise ValueError('Unexpected kw arguments: %r' % options.keys())
    if len(arrays) == 0:
        return None
    first = arrays[0]
    n_samples = first.shape[0] if hasattr(first, 'shape') else len(first)
    if max_n_samples is None:
        max_n_samples = n_samples
    elif max_n_samples > n_samples and (not replace):
        raise ValueError('Cannot sample %d out of arrays with dim %d when replace is False' % (max_n_samples, n_samples))
    check_consistent_length(*arrays)
    if stratify is None:
        if replace:
            indices = random_state.randint(0, n_samples, size=(max_n_samples,))
        else:
            indices = np.arange(n_samples)
            random_state.shuffle(indices)
            indices = indices[:max_n_samples]
    else:
        y = check_array(stratify, ensure_2d=False, dtype=None)
        if y.ndim == 2:
            y = np.array([' '.join(row.astype('str')) for row in y])
        classes, y_indices = np.unique(y, return_inverse=True)
        n_classes = classes.shape[0]
        class_counts = np.bincount(y_indices)
        class_indices = np.split(np.argsort(y_indices, kind='mergesort'), np.cumsum(class_counts)[:-1])
        n_i = _approximate_mode(class_counts, max_n_samples, random_state)
        indices = []
        for i in range(n_classes):
            indices_i = random_state.choice(class_indices[i], n_i[i], replace=replace)
            indices.extend(indices_i)
        indices = random_state.permutation(indices)
    arrays = [a.tocsr() if issparse(a) else a for a in arrays]
    resampled_arrays = [safe_indexing(a, indices) for a in arrays]
    if len(resampled_arrays) == 1:
        return resampled_arrays[0]
    else:
        return resampled_arrays

.sklearn.utils.validation.check_consistent_length

def check_consistent_length(*arrays):
    lengths = [_num_samples(X) for X in arrays if X is not None]
    uniques = np.unique(lengths)
    if len(uniques) > 1:
        raise ValueError('Found input variables with inconsistent numbers of samples: %r' % [int(l) for l in lengths])

.sklearn.utils.validation._num_samples

def _num_samples(x):
    message = 'Expected sequence or array-like, got %s' % type(x)
    if hasattr(x, 'fit') and callable(x.fit):
        raise TypeError(message)
    if not hasattr(x, '__len__') and (not hasattr(x, 'shape')):
        if hasattr(x, '__array__'):
            x = np.asarray(x)
        else:
            raise TypeError(message)
    if hasattr(x, 'shape') and x.shape is not None:
        if len(x.shape) == 0:
            raise TypeError('Singleton array %r cannot be considered a valid collection.' % x)
        if isinstance(x.shape[0], numbers.Integral):
            return x.shape[0]
    try:
        return len(x)
    except TypeError:
        raise TypeError(message)

.sklearn.utils.__init__.safe_indexing

def safe_indexing(X, indices, axis=0):
    if axis == 0:
        return _safe_indexing_row(X, indices)
    elif axis == 1:
        return _safe_indexing_column(X, indices)
    else:
        raise ValueError("'axis' should be either 0 (to index rows) or 1 (to index  column). Got {} instead.".format(axis))

.sklearn.utils.__init__._safe_indexing_row

def _safe_indexing_row(X, indices):
    if hasattr(X, 'iloc'):
        indices = np.asarray(indices)
        indices = indices if indices.flags.writeable else indices.copy()
        try:
            return X.iloc[indices]
        except ValueError:
            warnings.warn('Copying input dataframe for slicing.', DataConversionWarning)
            return X.copy().iloc[indices]
    elif hasattr(X, 'shape'):
        if hasattr(X, 'take') and (hasattr(indices, 'dtype') and indices.dtype.kind == 'i'):
            return X.take(indices, axis=0)
        else:
            return _array_indexing(X, indices, axis=0)
    else:
        return [X[idx] for idx in indices]

