sympy.sympy.matrices.expressions.kronecker._entry

def _entry(self, i, j, **kwargs):
    result = 1
    for mat in reversed(self.args):
        i, m = divmod(i, mat.rows)
        j, n = divmod(j, mat.cols)
        result *= mat[m, n]
    return result

