    def strslice(x):
        x = list(x)
        if x[2] == 1:
            del x[2]
        if x[1] == x[0] + 1:
            del x[1]
        if x[0] == 0:
            x[0] = ''
        return ':'.join(map(self._print, x))
    return self._print(expr.parent) + '[' + strslice(expr.rowslice) + ', ' + strslice(expr.colslice) + ']'

