from ._compat import PY_3_10_PLUS, PY_3_11_PLUS, PY_3_13_PLUS, _AnnotationExtractor, _get_annotations, get_generic_base

class Converter:
    __slots__ = ('__call__', '_first_param_type', '_global_name', 'converter', 'takes_field', 'takes_self')

    def __init__(self, converter, *, takes_self=False, takes_field=False):
        self.converter = converter
        self.takes_self = takes_self
        self.takes_field = takes_field
        ex = _AnnotationExtractor(converter)
        self._first_param_type = ex.get_first_param_type()
        if not (self.takes_self or self.takes_field):
            self.__call__ = lambda value, _, __: self.converter(value)
        elif self.takes_self and (not self.takes_field):
            self.__call__ = lambda value, instance, __: self.converter(value, instance)
        elif not self.takes_self and self.takes_field:
            self.__call__ = lambda value, __, field: self.converter(value, field)
        else:
            self.__call__ = lambda value, instance, field: self.converter(value, instance, field)
        rt = ex.get_return_type()
        if rt is not None:
            self.__call__.__annotations__['return'] = rt

    @staticmethod
    def _get_global_name(attr_name: str) -> str:
        return f'__attr_converter_{attr_name}'

    def _fmt_converter_call(self, attr_name: str, value_var: str) -> str:
        if not (self.takes_self or self.takes_field):
            return f'{self._get_global_name(attr_name)}({value_var})'
        if self.takes_self and self.takes_field:
            return f"{self._get_global_name(attr_name)}({value_var}, self, attr_dict['{attr_name}'])"
        if self.takes_self:
            return f'{self._get_global_name(attr_name)}({value_var}, self)'
        return f"{self._get_global_name(attr_name)}({value_var}, attr_dict['{attr_name}'])"

attrs.src.attr._make._get_global_name

@staticmethod
def _get_global_name(attr_name: str) -> str:
    """
    Return the name that a converter for an attribute name *attr_name*
    would have.
    """
    return f"__attr_converter_{attr_name}"

class ComplexCalculator:

    def __init__(self):
        pass

    @staticmethod
    def subtract(c1, c2):
        real = c1.real - c2.real
        imaginary = c1.imag - c2.imag
        return complex(real, imaginary)

from typing import TYPE_CHECKING, overload
from sympy.core.singleton import S
from sympy.core.relational import is_eq
from sympy.functions.elementary.complexes import conjugate, im, re, sign
from sympy.functions.elementary.miscellaneous import sqrt
from sympy.functions.elementary.trigonometric import acos, asin, atan2
from sympy.simplify.trigsimp import trigsimp
from sympy.core.expr import Expr

class Quaternion(Expr):
    _op_priority = 11.0
    is_commutative = False
    if TYPE_CHECKING:

        @property
        def args(self) -> tuple[Expr, Expr, Expr, Expr]:
            ...
        _real_field: bool
        _norm: Expr | None

    @property
    def a(self) -> Expr:
        return self.args[0]

    @property
    def b(self) -> Expr:
        return self.args[1]

    @property
    def c(self) -> Expr:
        return self.args[2]

    @property
    def d(self) -> Expr:
        return self.args[3]

    def to_euler(self, seq: str, angle_addition: bool=True, avoid_square_root: bool=False) -> tuple[Expr, Expr, Expr]:
        if self.is_zero_quaternion():
            raise ValueError('Cannot convert a quaternion with norm 0.')
        extrinsic = _is_extrinsic(seq)
        i1, j1, k1 = list(seq.lower())
        i = 'xyz'.index(i1) + 1
        j = 'xyz'.index(j1) + 1
        k = 'xyz'.index(k1) + 1
        if not extrinsic:
            i, k = (k, i)
        symmetric = i == k
        if symmetric:
            k = 6 - i - j
        sign = (i - j) * (j - k) * (k - i) // 2
        elements = [self.a, self.b, self.c, self.d]
        a = elements[0]
        b = elements[i]
        c = elements[j]
        d = elements[k] * sign
        if not symmetric:
            a, b, c, d = (a - c, b + d, c + a, d - b)
        if avoid_square_root:
            if symmetric:
                n2 = self.norm() ** 2
                angles1 = acos((a * a + b * b - c * c - d * d) / n2)
            else:
                n2 = 2 * self.norm() ** 2
                angles1 = asin((c * c + d * d - a * a - b * b) / n2)
        else:
            angles1 = 2 * atan2(sqrt(c * c + d * d), sqrt(a * a + b * b))
            if not symmetric:
                angles1 -= S.Pi / 2
        case = 0
        if is_eq(c, S.Zero) and is_eq(d, S.Zero):
            case = 1
        if is_eq(a, S.Zero) and is_eq(b, S.Zero):
            case = 2
        if case == 0:
            if angle_addition:
                angles0 = atan2(b, a) + atan2(d, c)
                angles2 = atan2(b, a) - atan2(d, c)
            else:
                angles0 = atan2(b * c + a * d, a * c - b * d)
                angles2 = atan2(b * c - a * d, a * c + b * d)
        elif case == 1:
            if extrinsic:
                angles0 = S.Zero
                angles2 = 2 * atan2(b, a)
            else:
                angles0 = 2 * atan2(b, a)
                angles2 = S.Zero
        elif extrinsic:
            angles0 = S.Zero
            angles2 = -2 * atan2(d, c)
        else:
            angles0 = 2 * atan2(d, c)
            angles2 = S.Zero
        if not symmetric:
            angles0 *= sign
        if extrinsic:
            return (angles2, angles1, angles0)
        else:
            return (angles0, angles1, angles2)

    def norm(self) -> Expr:
        if self._norm is None:
            q = self
            return sqrt(trigsimp(q.a ** 2 + q.b ** 2 + q.c ** 2 + q.d ** 2))
        return self._norm

    def is_zero_quaternion(self) -> bool | None:
        return self.norm().is_zero

sympy.sympy.algebras.quaternion.is_zero_quaternion

def is_zero_quaternion(self) -> bool | None:
    """
    Returns true if the quaternion is a zero quaternion or false if it is not a zero quaternion
    and None if the value is unknown.

    Explanation
    ===========

    A zero quaternion is a quaternion with both scalar part and
    vector part equal to 0.

    Examples
    ========

    >>> from sympy.algebras.quaternion import Quaternion
    >>> q = Quaternion(1, 0, 0, 0)
    >>> q.is_zero_quaternion()
    False

    >>> q = Quaternion(0, 0, 0, 0)
    >>> q.is_zero_quaternion()
    True

    See Also
    ========
    scalar_part
    vector_part

    """

    return self.norm().is_zero

sympy.sympy.algebras.quaternion.a

@property
def a(self) -> Expr:
    return self.args[0]

sympy.sympy.algebras.quaternion.b

@property
def b(self) -> Expr:
    return self.args[1]

sympy.sympy.algebras.quaternion.c

@property
def c(self) -> Expr:
    return self.args[2]

