.sympy.core.add.Add.primitive

def primitive(self):
    terms = []
    inf = False
    for a in self.args:
        c, m = a.as_coeff_Mul()
        if not c.is_Rational:
            c = S.One
            m = a
        inf = inf or m is S.ComplexInfinity
        terms.append((c.p, c.q, m))
    if not inf:
        ngcd = reduce(igcd, [t[0] for t in terms], 0)
        dlcm = reduce(ilcm, [t[1] for t in terms], 1)
    else:
        ngcd = reduce(igcd, [t[0] for t in terms if t[1]], 0)
        dlcm = reduce(ilcm, [t[1] for t in terms if t[1]], 1)
    if ngcd == dlcm == 1:
        return (S.One, self)
    if not inf:
        for i, (p, q, term) in enumerate(terms):
            terms[i] = _keep_coeff(Rational(p // ngcd * (dlcm // q)), term)
    else:
        for i, (p, q, term) in enumerate(terms):
            if q:
                terms[i] = _keep_coeff(Rational(p // ngcd * (dlcm // q)), term)
            else:
                terms[i] = _keep_coeff(Rational(p, q), term)
    if terms[0].is_Number or terms[0] is S.ComplexInfinity:
        c = terms.pop(0)
    else:
        c = None
    _addsort(terms)
    if c:
        terms.insert(0, c)
    return (Rational(ngcd, dlcm), self._new_rawargs(*terms))

.sympy.core.numbers.igcd

def igcd(*args):
    if len(args) < 2:
        raise TypeError('igcd() takes at least 2 arguments (%s given)' % len(args))
    if 1 in args:
        a = 1
        k = 0
    else:
        a = abs(as_int(args[0]))
        k = 1
    if a != 1:
        while k < len(args):
            b = args[k]
            k += 1
            try:
                a = _gcdcache[a, b]
            except KeyError:
                b = as_int(b)
                if not b:
                    continue
                if b == 1:
                    a = 1
                    break
                if b < 0:
                    b = -b
                t = (a, b)
                a = igcd2(a, b)
                _gcdcache[t] = _gcdcache[t[1], t[0]] = a
    while k < len(args):
        ok = as_int(args[k])
        k += 1
    return a

.sympy.core.compatibility.as_int

def as_int(n):
    try:
        result = int(n)
        if result != n:
            raise TypeError
    except TypeError:
        raise ValueError('%s is not an integer' % (n,))
    return result

.sympy.core.numbers.ilcm

def ilcm(*args):
    if len(args) < 2:
        raise TypeError('ilcm() takes at least 2 arguments (%s given)' % len(args))
    if 0 in args:
        return 0
    a = args[0]
    for b in args[1:]:
        a = a * b // igcd(a, b)
    return a

