.sympy.core.numbers.Rational.__div__

def __div__(self, other):
    if global_evaluate[0]:
        if isinstance(other, Integer):
            if self.p and other.p == S.Zero:
                return S.ComplexInfinity
            else:
                return Rational(self.p, self.q * other.p, igcd(self.p, other.p))
        elif isinstance(other, Rational):
            return Rational(self.p * other.q, self.q * other.p, igcd(self.p, other.p) * igcd(self.q, other.q))
        elif isinstance(other, Float):
            return self * (1 / other)
        else:
            return Number.__div__(self, other)
    return Number.__div__(self, other)

.sympy.core.expr.Expr._eval_is_negative

def _eval_is_negative(self):
    from sympy.polys.numberfields import minimal_polynomial
    from sympy.polys.polyerrors import NotAlgebraic
    if self.is_number:
        if self.is_real is False:
            return False
        try:
            n2 = self._eval_evalf(2)
            if n2 is None:
                raise AttributeError
            if n2._prec == 1:
                raise AttributeError
            if n2 == S.NaN:
                raise AttributeError
        except (AttributeError, ValueError):
            return None
        n, i = self.evalf(2).as_real_imag()
        if not i.is_Number or not n.is_Number:
            return False
        if n._prec != 1 and i._prec != 1:
            return bool(not i and n < 0)
        elif n._prec == 1 and (not i or i._prec == 1) and self.is_algebraic and (not self.has(Function)):
            try:
                if minimal_polynomial(self).is_Symbol:
                    return False
            except (NotAlgebraic, NotImplementedError):
                pass

.sympy.core.numbers.Number._eval_evalf

def _eval_evalf(self, prec):
    return Float._new(self._as_mpf_val(prec), prec)

.sympy.core.numbers.NaN._as_mpf_val

def _as_mpf_val(self, prec):
    return _mpf_nan

.sympy.core.numbers.Float.__lt__

def __lt__(self, other):
    try:
        other = _sympify(other)
    except SympifyError:
        raise TypeError('Invalid comparison %s < %s' % (self, other))
    if isinstance(other, NumberSymbol):
        return other.__gt__(self)
    if other.is_real and other.is_number:
        other = other.evalf()
    if isinstance(other, Number) and other is not S.NaN:
        return _sympify(bool(mlib.mpf_lt(self._mpf_, other._as_mpf_val(self._prec))))
    return Expr.__lt__(self, other)

.sympy.core.add.Add.class_key

def class_key(cls):
    return (3, 1, cls.__name__)

.sympy.core.basic.Basic.xreplace

def xreplace(self, rule):
    value, _ = self._xreplace(rule)
    return value

.sympy.core.basic.Basic._xreplace

def _xreplace(self, rule):
    if self in rule:
        return (rule[self], True)
    elif rule:
        args = []
        changed = False
        for a in self.args:
            try:
                a_xr = a._xreplace(rule)
                args.append(a_xr[0])
                changed |= a_xr[1]
            except AttributeError:
                args.append(a)
        args = tuple(args)
        if changed:
            return (self.func(*args), True)
    return (self, False)

.sympy.simplify.cse_opts.sub_post

def sub_post(e):
    replacements = []
    for node in preorder_traversal(e):
        if isinstance(node, Mul) and node.args[0] is S.One and (node.args[1] is S.NegativeOne):
            replacements.append((node, -Mul._from_args(node.args[2:])))
    for node, replacement in replacements:
        e = e.xreplace({node: replacement})
    return e

.sympy.simplify.simplify.bottom_up

def bottom_up(rv, F, atoms=False, nonbasic=False):
    try:
        if rv.args:
            args = tuple([bottom_up(a, F, atoms, nonbasic) for a in rv.args])
            if args != rv.args:
                rv = rv.func(*args)
            rv = F(rv)
        elif atoms:
            rv = F(rv)
    except AttributeError:
        if nonbasic:
            try:
                rv = F(rv)
            except TypeError:
                pass
    return rv

.sympy.core.expr.Expr.normal

def normal(self):
    from .mul import _unevaluated_Mul
    n, d = self.as_numer_denom()
    if d is S.One:
        return n
    if d.is_Number:
        if d is S.One:
            return n
        else:
            return _unevaluated_Mul(n, 1 / d)
    else:
        return n / d

.sympy.core.expr.Expr.as_numer_denom

def as_numer_denom(self):
    return (self, S.One)

.sympy.core.power.Pow.as_numer_denom

def as_numer_denom(self):
    if not self.is_commutative:
        return (self, S.One)
    base, exp = self.as_base_exp()
    n, d = base.as_numer_denom()
    neg_exp = exp.is_negative
    if not neg_exp and (not (-exp).is_negative):
        neg_exp = _coeff_isneg(exp)
    int_exp = exp.is_integer
    if not (d.is_real or int_exp):
        n = base
        d = S.One
    dnonpos = d.is_nonpositive
    if dnonpos:
        n, d = (-n, -d)
    elif dnonpos is None and (not int_exp):
        n = base
        d = S.One
    if neg_exp:
        n, d = (d, n)
        exp = -exp
    if exp.is_infinite:
        if n is S.One and d is not S.One:
            return (n, self.func(d, exp))
        if n is not S.One and d is S.One:
            return (self.func(n, exp), d)
    return (self.func(n, exp), self.func(d, exp))

.sympy.core.numbers.Integer.__abs__

def __abs__(self):
    if self.p >= 0:
        return self
    else:
        return Integer(-self.p)

.sympy.core.mul.Mul.as_numer_denom

def as_numer_denom(self):
    numers, denoms = list(zip(*[f.as_numer_denom() for f in self.args]))
    return (self.func(*numers), self.func(*denoms))

.sympy.core.numbers.Integer.as_numer_denom

def as_numer_denom(self):
    return (self, S.One)

.sympy.core.add.Add.as_numer_denom

def as_numer_denom(self):
    content, expr = self.primitive()
    ncon, dcon = content.as_numer_denom()
    nd = defaultdict(list)
    for f in expr.args:
        ni, di = f.as_numer_denom()
        nd[di].append(ni)
    if S.Zero in nd:
        n = nd.pop(S.Zero)
        assert len(n) == 1
        n = n[0]
        nd[S.One].append(n / S.Zero)
    if len(nd) == 1:
        d, n = nd.popitem()
        return (self.func(*[_keep_coeff(ncon, ni) for ni in n]), _keep_coeff(dcon, d))
    for d, n in nd.items():
        if len(n) == 1:
            nd[d] = n[0]
        else:
            nd[d] = self.func(*n)
    denoms, numers = [list(i) for i in zip(*iter(nd.items()))]
    n, d = (self.func(*[Mul(*denoms[:i] + [numers[i]] + denoms[i + 1:]) for i in range(len(numers))]), Mul(*denoms))
    return (_keep_coeff(ncon, n), _keep_coeff(dcon, d))

.sympy.core.add.Add.flatten

def flatten(cls, seq):
    from sympy.calculus.util import AccumBounds
    from sympy.matrices.expressions import MatrixExpr
    rv = None
    if len(seq) == 2:
        a, b = seq
        if b.is_Rational:
            a, b = (b, a)
        if a.is_Rational:
            if b.is_Mul:
                rv = ([a, b], [], None)
        if rv:
            if all((s.is_commutative for s in rv[0])):
                return rv
            return ([], rv[0], None)
    terms = {}
    coeff = S.Zero
    order_factors = []
    for o in seq:
        if o.is_Order:
            for o1 in order_factors:
                if o1.contains(o):
                    o = None
                    break
            if o is None:
                continue
            order_factors = [o] + [o1 for o1 in order_factors if not o.contains(o1)]
            continue
        elif o.is_Number:
            if o is S.NaN or (coeff is S.ComplexInfinity and o.is_finite is False):
                return ([S.NaN], [], None)
            if coeff.is_Number:
                coeff += o
                if coeff is S.NaN:
                    return ([S.NaN], [], None)
            continue
        elif isinstance(o, AccumBounds):
            coeff = o.__add__(coeff)
            continue
        elif isinstance(o, MatrixExpr):
            coeff = o.__add__(coeff) if coeff else o
            continue
        elif o is S.ComplexInfinity:
            if coeff.is_finite is False:
                return ([S.NaN], [], None)
            coeff = S.ComplexInfinity
            continue
        elif o.is_Add:
            seq.extend(o.args)
            continue
        elif o.is_Mul:
            c, s = o.as_coeff_Mul()
        elif o.is_Pow:
            b, e = o.as_base_exp()
            if b.is_Number and (e.is_Integer or (e.is_Rational and e.is_negative)):
                seq.append(b ** e)
                continue
            c, s = (S.One, o)
        else:
            c = S.One
            s = o
        if s in terms:
            terms[s] += c
            if terms[s] is S.NaN:
                return ([S.NaN], [], None)
        else:
            terms[s] = c
    newseq = []
    noncommutative = False
    for s, c in terms.items():
        if c is S.Zero:
            continue
        elif c is S.One:
            newseq.append(s)
        elif s.is_Mul:
            cs = s._new_rawargs(*(c,) + s.args)
            newseq.append(cs)
        elif s.is_Add:
            newseq.append(Mul(c, s, evaluate=False))
        else:
            newseq.append(Mul(c, s))
        noncommutative = noncommutative or not s.is_commutative
    if coeff is S.Infinity:
        newseq = [f for f in newseq if not (f.is_nonnegative or (f.is_real and f.is_finite))]
    elif coeff is S.NegativeInfinity:
        newseq = [f for f in newseq if not (f.is_nonpositive or (f.is_real and f.is_finite))]
    if coeff is S.ComplexInfinity:
        newseq = [c for c in newseq if not (c.is_finite and c.is_real is not None)]
    if order_factors:
        newseq2 = []
        for t in newseq:
            for o in order_factors:
                if o.contains(t):
                    t = None
                    break
            if t is not None:
                newseq2.append(t)
        newseq = newseq2 + order_factors
        for o in order_factors:
            if o.contains(coeff):
                coeff = S.Zero
                break
    _addsort(newseq)
    if coeff is not S.Zero:
        newseq.insert(0, coeff)
    if noncommutative:
        return ([], newseq, None)
    else:
        return (newseq, [], None)

.sympy.core.numbers.Integer.__add__

def __add__(self, other):
    if global_evaluate[0]:
        if isinstance(other, integer_types):
            return Integer(self.p + other)
        elif isinstance(other, Integer):
            return Integer(self.p + other.p)
        elif isinstance(other, Rational):
            return Rational(self.p * other.q + other.p, other.q, 1)
        return Rational.__add__(self, other)
    else:
        return Add(self, other)

.sympy.simplify.powsimp.powsimp

def powsimp(expr, deep=False, combine='all', force=False, measure=count_ops):
    from sympy.matrices.expressions.matexpr import MatrixSymbol

    def recurse(arg, **kwargs):
        _deep = kwargs.get('deep', deep)
        _combine = kwargs.get('combine', combine)
        _force = kwargs.get('force', force)
        _measure = kwargs.get('measure', measure)
        return powsimp(arg, _deep, _combine, _force, _measure)
    expr = sympify(expr)
    if not isinstance(expr, Basic) or isinstance(expr, MatrixSymbol) or (expr.is_Atom or expr in (exp_polar(0), exp_polar(1))):
        return expr
    if deep or expr.is_Add or (expr.is_Mul and _y not in expr.args):
        expr = expr.func(*[recurse(w) for w in expr.args])
    if expr.is_Pow:
        return recurse(expr * _y, deep=False) / _y
    if not expr.is_Mul:
        return expr
    if combine in ('exp', 'all'):
        c_powers = defaultdict(list)
        nc_part = []
        newexpr = []
        coeff = S.One
        for term in expr.args:
            if term.is_Rational:
                coeff *= term
                continue
            if term.is_Pow:
                term = _denest_pow(term)
            if term.is_commutative:
                b, e = term.as_base_exp()
                if deep:
                    b, e = [recurse(i) for i in [b, e]]
                if b.is_Pow or isinstance(b, exp):
                    b, e = (b ** e, S.One)
                c_powers[b].append(e)
            else:
                if nc_part:
                    b1, e1 = nc_part[-1].as_base_exp()
                    b2, e2 = term.as_base_exp()
                    if b1 == b2 and e1.is_commutative and e2.is_commutative:
                        nc_part[-1] = Pow(b1, Add(e1, e2))
                        continue
                nc_part.append(term)
        for b, e in ordered(iter(c_powers.items())):
            if b and b.is_Rational and (not all((ei.is_Number for ei in e))) and (coeff is not S.One) and (b not in (S.One, S.NegativeOne)):
                m = multiplicity(abs(b), abs(coeff))
                if m:
                    e.append(m)
                    coeff /= b ** m
            c_powers[b] = Add(*e)
        if coeff is not S.One:
            if coeff in c_powers:
                c_powers[coeff] += S.One
            else:
                c_powers[coeff] = S.One
        c_powers = dict(c_powers)
        be = list(c_powers.items())
        skip = set()
        for b, e in be:
            if b in skip:
                continue
            bpos = b.is_positive or b.is_polar
            if bpos:
                binv = 1 / b
                if b != binv and binv in c_powers:
                    if b.as_numer_denom()[0] is S.One:
                        c_powers.pop(b)
                        c_powers[binv] -= e
                    else:
                        skip.add(binv)
                        e = c_powers.pop(binv)
                        c_powers[b] -= e
        be = list(c_powers.items())
        _n = S.NegativeOne
        for i, (b, e) in enumerate(be):
            if ((-b).is_Symbol or b.is_Add) and -b in c_powers:
                if b.is_positive in (0, 1) or e.is_integer:
                    c_powers[-b] += c_powers.pop(b)
                    if _n in c_powers:
                        c_powers[_n] += e
                    else:
                        c_powers[_n] = e
        c_powers = [(b, e) for b, e in c_powers.items() if e]

        def ratq(x):
            return bkey(x)[0][1]

        def bkey(b, e=None):
            if e is not None:
                if e.is_Integer:
                    return ((b, S.One), e)
                elif e.is_Rational:
                    return ((b, Integer(e.q)), Integer(e.p))
                else:
                    c, m = e.as_coeff_Mul(rational=True)
                    if c is not S.One:
                        if m.is_integer:
                            return ((b, Integer(c.q)), m * Integer(c.p))
                        return ((b ** m, Integer(c.q)), Integer(c.p))
                    else:
                        return ((b ** e, S.One), S.One)
            else:
                return bkey(*b.as_base_exp())

        def update(b):
            newe, r = divmod(common_b[b], b[1])
            if not r:
                common_b.pop(b)
                if newe:
                    for m in Mul.make_args(b[0] ** newe):
                        b, e = bkey(m)
                        if b not in common_b:
                            common_b[b] = 0
                        common_b[b] += e
                        if b[1] != 1:
                            bases.append(b)
        common_b = {}
        done = []
        bases = []
        for b, e in c_powers:
            b, e = bkey(b, e)
            if b in common_b:
                common_b[b] = common_b[b] + e
            else:
                common_b[b] = e
            if b[1] != 1 and b[0].is_Mul:
                bases.append(b)
        c_powers = [(b, e) for b, e in common_b.items() if e]
        bases.sort(key=default_sort_key)
        bases.sort(key=measure, reverse=True)
        for base in bases:
            if base not in common_b:
                continue
            b, exponent = base
            last = False
            qlcm = 1
            while True:
                bstart = b
                qstart = qlcm
                bb = []
                ee = []
                for bi in Mul.make_args(b):
                    bib, bie = bkey(bi)
                    if bib not in common_b or common_b[bib] < bie:
                        ee = bb = []
                        break
                    ee.append([bie, common_b[bib]])
                    bb.append(bib)
                if ee:
                    min1 = ee[0][1] / ee[0][0]
                    for i in range(len(ee)):
                        rat = ee[i][1] / ee[i][0]
                        if rat < 1:
                            break
                        min1 = min(min1, rat)
                    else:
                        for i in range(len(bb)):
                            common_b[bb[i]] -= min1 * ee[i][0]
                            update(bb[i])
                        common_b[base] += min1 * qstart * exponent
                if last or len(common_b) == 1 or all((k[1] == 1 for k in common_b)):
                    break
                qlcm = lcm([ratq(bi) for bi in Mul.make_args(bstart)])
                if qlcm == 1:
                    break
                b = bstart ** qlcm
                qlcm *= qstart
                if all((ratq(bi) == 1 for bi in Mul.make_args(b))):
                    last = True
            b, q = base
            done.append((b, common_b.pop(base) * Rational(1, q)))
        c_powers = done
        for (b, q), e in common_b.items():
            if (b.is_Pow or isinstance(b, exp)) and q is not S.One and (not b.exp.is_Rational):
                b, be = b.as_base_exp()
                b = b ** (be / q)
            else:
                b = root(b, q)
            c_powers.append((b, e))
        check = len(c_powers)
        c_powers = dict(c_powers)
        assert len(c_powers) == check
        newexpr = expr.func(*newexpr + [Pow(b, e) for b, e in c_powers.items()])
        if combine == 'exp':
            return expr.func(newexpr, expr.func(*nc_part))
        else:
            return recurse(expr.func(*nc_part), combine='base') * recurse(newexpr, combine='base')
    elif combine == 'base':
        c_powers = []
        nc_part = []
        for term in expr.args:
            if term.is_commutative:
                c_powers.append(list(term.as_base_exp()))
            else:
                nc_part.append(term)
        for i in range(len(c_powers)):
            b, e = c_powers[i]
            if not (all((x.is_nonnegative for x in b.as_numer_denom())) or e.is_integer or force or b.is_polar):
                continue
            exp_c, exp_t = e.as_coeff_Mul(rational=True)
            if exp_c is not S.One and exp_t is not S.One:
                c_powers[i] = [Pow(b, exp_c), exp_t]
        c_exp = defaultdict(list)
        for b, e in c_powers:
            if deep:
                e = recurse(e)
            c_exp[e].append(b)
        del c_powers
        c_powers = defaultdict(list)
        for e in c_exp:
            bases = c_exp[e]
            if len(bases) == 1:
                new_base = bases[0]
            elif e.is_integer or force:
                new_base = expr.func(*bases)
            else:
                unk = []
                nonneg = []
                neg = []
                for bi in bases:
                    if bi.is_negative:
                        neg.append(bi)
                    elif bi.is_nonnegative:
                        nonneg.append(bi)
                    elif bi.is_polar:
                        nonneg.append(bi)
                    else:
                        unk.append(bi)
                if len(unk) == 1 and (not neg) or (len(neg) == 1 and (not unk)):
                    nonneg.extend(unk + neg)
                    unk = neg = []
                elif neg:
                    israt = False
                    if e.is_Rational:
                        israt = True
                    else:
                        p, d = e.as_numer_denom()
                        if p.is_integer and d.is_integer:
                            israt = True
                    if israt:
                        neg = [-w for w in neg]
                        unk.extend([S.NegativeOne] * len(neg))
                    else:
                        unk.extend(neg)
                        neg = []
                    del israt
                for b in unk:
                    c_powers[b].append(e)
                new_base = expr.func(*nonneg + neg)

                def _terms(e):
                    if e.is_Add:
                        return sum([_terms(ai) for ai in e.args])
                    if e.is_Mul:
                        return prod([_terms(mi) for mi in e.args])
                    return 1
                xnew_base = expand_mul(new_base, deep=False)
                if len(Add.make_args(xnew_base)) < _terms(new_base):
                    new_base = factor_terms(xnew_base)
            c_powers[new_base].append(e)
        c_part = [Pow(b, ei) for b, e in c_powers.items() for ei in e]
        return expr.func(*c_part + nc_part)
    else:
        raise ValueError("combine must be one of ('all', 'exp', 'base').")

.sympy.sets.fancysets.Naturals0._contains

def _contains(self, other):
    if not isinstance(other, Expr):
        return S.false
    elif other.is_integer and other.is_nonnegative:
        return S.true
    elif other.is_integer is False or other.is_nonnegative is False:
        return S.false

.sympy.core.function.Application.eval

def eval(cls, *args):
    return

.sympy.core.singleton.Singleton.__call__

def __call__(self, *args, **kwargs):
    if self not in Singleton._instances:
        Singleton._instances[self] = super(Singleton, self).__call__(*args, **kwargs)
    return Singleton._instances[self]

    def __getnewargs__(self):
        return ()
    self.__getnewargs__ = __getnewargs__

.sympy.core.function.Function._should_evalf

def _should_evalf(cls, arg):
    from sympy.core.symbol import Wild
    if arg.is_Float:
        return arg._prec
    if not arg.is_Add:
        return -1
    a, b = (Wild('a'), Wild('b'))
    m = arg.match(a + b * S.ImaginaryUnit)
    if not m or not (m[a].is_Float or m[b].is_Float):
        return -1
    l = [m[i]._prec for i in m if m[i].is_Float]
    l.append(-1)
    return max(l)

.sympy.simplify.powsimp.recurse

def recurse(arg, **kwargs):
    _deep = kwargs.get('deep', deep)
    _combine = kwargs.get('combine', combine)
    _force = kwargs.get('force', force)
    _measure = kwargs.get('measure', measure)
    return powsimp(arg, _deep, _combine, _force, _measure)

.sympy.core.add.Add.as_content_primitive

def as_content_primitive(self, radical=False, clear=True):
    con, prim = self.func(*[_keep_coeff(*a.as_content_primitive(radical=radical, clear=clear)) for a in self.args]).primitive()
    if not clear and (not con.is_Integer) and prim.is_Add:
        con, d = con.as_numer_denom()
        _p = prim / d
        if any((a.as_coeff_Mul()[0].is_Integer for a in _p.args)):
            prim = _p
        else:
            con /= d
    if radical and prim.is_Add:
        args = prim.args
        rads = []
        common_q = None
        for m in args:
            term_rads = defaultdict(list)
            for ai in Mul.make_args(m):
                if ai.is_Pow:
                    b, e = ai.as_base_exp()
                    if e.is_Rational and b.is_Integer:
                        term_rads[e.q].append(abs(int(b)) ** e.p)
            if not term_rads:
                break
            if common_q is None:
                common_q = set(term_rads.keys())
            else:
                common_q = common_q & set(term_rads.keys())
                if not common_q:
                    break
            rads.append(term_rads)
        else:
            for r in rads:
                for q in list(r.keys()):
                    if q not in common_q:
                        r.pop(q)
                for q in r:
                    r[q] = prod(r[q])
            G = []
            for q in common_q:
                g = reduce(igcd, [r[q] for r in rads], 0)
                if g != 1:
                    G.append(g ** Rational(1, q))
            if G:
                G = Mul(*G)
                args = [ai / G for ai in args]
                prim = G * prim.func(*args)
    return (con, prim)

.sympy.core.numbers.Rational.as_content_primitive

def as_content_primitive(self, radical=False, clear=True):
    if self:
        if self.is_positive:
            return (self, S.One)
        return (-self, S.NegativeOne)
    return (S.One, self)

.sympy.core.expr.Expr.as_content_primitive

def as_content_primitive(self, radical=False, clear=True):
    return (S.One, self)

.sympy.polys.polytools.cancel

def cancel(f, *gens, **args):
    from sympy.core.exprtools import factor_terms
    from sympy.functions.elementary.piecewise import Piecewise
    options.allowed_flags(args, ['polys'])
    f = sympify(f)
    if not isinstance(f, (tuple, Tuple)):
        if f.is_Number or isinstance(f, Relational) or (not isinstance(f, Expr)):
            return f
        f = factor_terms(f, radical=True)
        p, q = f.as_numer_denom()
    elif len(f) == 2:
        p, q = f
    elif isinstance(f, Tuple):
        return factor_terms(f)
    else:
        raise ValueError('unexpected argument: %s' % f)
    try:
        (F, G), opt = parallel_poly_from_expr((p, q), *gens, **args)
    except PolificationFailed:
        if not isinstance(f, (tuple, Tuple)):
            return f
        else:
            return (S.One, p, q)
    except PolynomialError as msg:
        if f.is_commutative and (not f.has(Piecewise)):
            raise PolynomialError(msg)
        if f.is_Add or f.is_Mul:
            sifted = sift(f.args, lambda x: x.is_commutative is True and (not x.has(Piecewise)))
            c, nc = (sifted[True], sifted[False])
            nc = [cancel(i) for i in nc]
            return f.func(cancel(f.func._from_args(c)), *nc)
        else:
            reps = []
            pot = preorder_traversal(f)
            next(pot)
            for e in pot:
                if isinstance(e, (tuple, Tuple, BooleanAtom)):
                    continue
                try:
                    reps.append((e, cancel(e)))
                    pot.skip()
                except NotImplementedError:
                    pass
            return f.xreplace(dict(reps))
    c, P, Q = F.cancel(G)
    if not isinstance(f, (tuple, Tuple)):
        return c * (P.as_expr() / Q.as_expr())
    elif not opt.polys:
        return (c, P.as_expr(), Q.as_expr())
    else:
        return (c, P, Q)

.sympy.polys.polyoptions.allowed_flags

def allowed_flags(args, flags):
    flags = set(flags)
    for arg in args.keys():
        try:
            if Options.__options__[arg].is_Flag and (not arg in flags):
                raise FlagError("'%s' flag is not allowed in this context" % arg)
        except KeyError:
            raise OptionError("'%s' is not a valid option" % arg)

.sympy.core.exprtools.factor_terms

def factor_terms(expr, radical=False, clear=False, fraction=False, sign=True):

    def do(expr):
        from sympy.concrete.summations import Sum
        from sympy.simplify.simplify import factor_sum
        is_iterable = iterable(expr)
        if not isinstance(expr, Basic) or expr.is_Atom:
            if is_iterable:
                return type(expr)([do(i) for i in expr])
            return expr
        if expr.is_Pow or expr.is_Function or is_iterable or (not hasattr(expr, 'args_cnc')):
            args = expr.args
            newargs = tuple([do(i) for i in args])
            if newargs == args:
                return expr
            return expr.func(*newargs)
        if isinstance(expr, Sum):
            return factor_sum(expr, radical=radical, clear=clear, fraction=fraction, sign=sign)
        cont, p = expr.as_content_primitive(radical=radical, clear=clear)
        if p.is_Add:
            list_args = [do(a) for a in Add.make_args(p)]
            if all((a.as_coeff_Mul()[0] < 0 for a in list_args)):
                cont = -cont
                list_args = [-a for a in list_args]
            special = {}
            for i, a in enumerate(list_args):
                b, e = a.as_base_exp()
                if e.is_Mul and e != Mul(*e.args):
                    list_args[i] = Dummy()
                    special[list_args[i]] = a
            p = Add._from_args(list_args)
            p = gcd_terms(p, isprimitive=True, clear=clear, fraction=fraction).xreplace(special)
        elif p.args:
            p = p.func(*[do(a) for a in p.args])
        rv = _keep_coeff(cont, p, clear=clear, sign=sign)
        return rv
    expr = sympify(expr)
    return do(expr)

.sympy.core.exprtools.do

def do(expr):
    from sympy.concrete.summations import Sum
    from sympy.simplify.simplify import factor_sum
    is_iterable = iterable(expr)
    if not isinstance(expr, Basic) or expr.is_Atom:
        if is_iterable:
            return type(expr)([do(i) for i in expr])
        return expr
    if expr.is_Pow or expr.is_Function or is_iterable or (not hasattr(expr, 'args_cnc')):
        args = expr.args
        newargs = tuple([do(i) for i in args])
        if newargs == args:
            return expr
        return expr.func(*newargs)
    if isinstance(expr, Sum):
        return factor_sum(expr, radical=radical, clear=clear, fraction=fraction, sign=sign)
    cont, p = expr.as_content_primitive(radical=radical, clear=clear)
    if p.is_Add:
        list_args = [do(a) for a in Add.make_args(p)]
        if all((a.as_coeff_Mul()[0] < 0 for a in list_args)):
            cont = -cont
            list_args = [-a for a in list_args]
        special = {}
        for i, a in enumerate(list_args):
            b, e = a.as_base_exp()
            if e.is_Mul and e != Mul(*e.args):
                list_args[i] = Dummy()
                special[list_args[i]] = a
        p = Add._from_args(list_args)
        p = gcd_terms(p, isprimitive=True, clear=clear, fraction=fraction).xreplace(special)
    elif p.args:
        p = p.func(*[do(a) for a in p.args])
    rv = _keep_coeff(cont, p, clear=clear, sign=sign)
    return rv

.sympy.core.compatibility.iterable

def iterable(i, exclude=(string_types, dict, NotIterable)):
    if hasattr(i, '_iterable'):
        return i._iterable
    try:
        iter(i)
    except TypeError:
        return False
    if exclude:
        return not isinstance(i, exclude)
    return True

.sympy.core.mul.Mul.as_content_primitive

def as_content_primitive(self, radical=False, clear=True):
    coef = S.One
    args = []
    for i, a in enumerate(self.args):
        c, p = a.as_content_primitive(radical=radical, clear=clear)
        coef *= c
        if p is not S.One:
            args.append(p)
    return (coef, self.func(*args))

.sympy.core.power.Pow.as_content_primitive

def as_content_primitive(self, radical=False, clear=True):
    b, e = self.as_base_exp()
    b = _keep_coeff(*b.as_content_primitive(radical=radical, clear=clear))
    ce, pe = e.as_content_primitive(radical=radical, clear=clear)
    if b.is_Rational:
        h, t = pe.as_coeff_Add()
        if h.is_Rational:
            ceh = ce * h
            c = self.func(b, ceh)
            r = S.Zero
            if not c.is_Rational:
                iceh, r = divmod(ceh.p, ceh.q)
                c = self.func(b, iceh)
            return (c, self.func(b, _keep_coeff(ce, t + r / ce / ceh.q)))
    e = _keep_coeff(ce, pe)
    if e.is_Rational and b.is_Mul:
        h, t = b.as_content_primitive(radical=radical, clear=clear)
        c, m = self.func(h, e).as_coeff_Mul()
        m, me = m.as_base_exp()
        if m is S.One or me == e:
            return (c, self.func(_keep_coeff(m, t), e))
    return (S.One, self.func(b, e))

.sympy.core.exprtools.gcd_terms

def gcd_terms(terms, isprimitive=False, clear=True, fraction=True):

    def mask(terms):
        args = [(a, []) if a.is_commutative else a.args_cnc() for a in terms]
        reps = []
        for i, (c, nc) in enumerate(args):
            if nc:
                nc = Mul._from_args(nc)
                d = Dummy()
                reps.append((d, nc))
                c.append(d)
                args[i] = Mul._from_args(c)
            else:
                args[i] = c
        return (args, dict(reps))
    isadd = isinstance(terms, Add)
    addlike = isadd or (not isinstance(terms, Basic) and is_sequence(terms, include=set) and (not isinstance(terms, Dict)))
    if addlike:
        if isadd:
            terms = list(terms.args)
        else:
            terms = sympify(terms)
        terms, reps = mask(terms)
        cont, numer, denom = _gcd_terms(terms, isprimitive, fraction)
        numer = numer.xreplace(reps)
        coeff, factors = cont.as_coeff_Mul()
        if not clear:
            c, _coeff = coeff.as_coeff_Mul()
            if not c.is_Integer and (not clear) and numer.is_Add:
                n, d = c.as_numer_denom()
                _numer = numer / d
                if any((a.as_coeff_Mul()[0].is_Integer for a in _numer.args)):
                    numer = _numer
                    coeff = n * _coeff
        return _keep_coeff(coeff, factors * numer / denom, clear=clear)
    if not isinstance(terms, Basic):
        return terms
    if terms.is_Atom:
        return terms
    if terms.is_Mul:
        c, args = terms.as_coeff_mul()
        return _keep_coeff(c, Mul(*[gcd_terms(i, isprimitive, clear, fraction) for i in args]), clear=clear)

    def handle(a):
        if not isinstance(a, Expr):
            if isinstance(a, Basic):
                return a.func(*[handle(i) for i in a.args])
            return type(a)([handle(i) for i in a])
        return gcd_terms(a, isprimitive, clear, fraction)
    if isinstance(terms, Dict):
        return Dict(*[(k, handle(v)) for k, v in terms.args])
    return terms.func(*[handle(i) for i in terms.args])

.sympy.core.exprtools.mask

def mask(terms):
    args = [(a, []) if a.is_commutative else a.args_cnc() for a in terms]
    reps = []
    for i, (c, nc) in enumerate(args):
        if nc:
            nc = Mul._from_args(nc)
            d = Dummy()
            reps.append((d, nc))
            c.append(d)
            args[i] = Mul._from_args(c)
        else:
            args[i] = c
    return (args, dict(reps))

.sympy.core.exprtools._gcd_terms

def _gcd_terms(terms, isprimitive=False, fraction=True):
    if isinstance(terms, Basic) and (not isinstance(terms, Tuple)):
        terms = Add.make_args(terms)
    terms = list(map(Term, [t for t in terms if t]))
    if len(terms) == 0:
        return (S.Zero, S.Zero, S.One)
    if len(terms) == 1:
        cont = terms[0].coeff
        numer = terms[0].numer.as_expr()
        denom = terms[0].denom.as_expr()
    else:
        cont = terms[0]
        for term in terms[1:]:
            cont = cont.gcd(term)
        for i, term in enumerate(terms):
            terms[i] = term.quo(cont)
        if fraction:
            denom = terms[0].denom
            for term in terms[1:]:
                denom = denom.lcm(term.denom)
            numers = []
            for term in terms:
                numer = term.numer.mul(denom.quo(term.denom))
                numers.append(term.coeff * numer.as_expr())
        else:
            numers = [t.as_expr() for t in terms]
            denom = Term(S(1)).numer
        cont = cont.as_expr()
        numer = Add(*numers)
        denom = denom.as_expr()
    if not isprimitive and numer.is_Add:
        _cont, numer = numer.primitive()
        cont *= _cont
    return (cont, numer, denom)

.sympy.core.exprtools.Term.__init__

def __init__(self, term, numer=None, denom=None):
    if numer is None and denom is None:
        if not term.is_commutative:
            raise NonCommutativeExpression('commutative expression expected')
        coeff, factors = term.as_coeff_mul()
        numer, denom = (defaultdict(int), defaultdict(int))
        for factor in factors:
            base, exp = decompose_power(factor)
            if base.is_Add:
                cont, base = base.primitive()
                coeff *= cont ** exp
            if exp > 0:
                numer[base] += exp
            else:
                denom[base] += -exp
        numer = Factors(numer)
        denom = Factors(denom)
    else:
        coeff = term
        if numer is None:
            numer = Factors()
        if denom is None:
            denom = Factors()
    self.coeff = coeff
    self.numer = numer
    self.denom = denom

.sympy.core.expr.Expr.as_coeff_mul

def as_coeff_mul(self, *deps, **kwargs):
    if deps:
        if not self.has(*deps):
            return (self, tuple())
    return (S.One, (self,))

.sympy.core.exprtools.decompose_power

def decompose_power(expr):
    base, exp = expr.as_base_exp()
    if exp.is_Number:
        if exp.is_Rational:
            if not exp.is_Integer:
                base = Pow(base, Rational(1, exp.q))
            exp = exp.p
        else:
            base, exp = (expr, 1)
    else:
        exp, tail = exp.as_coeff_Mul(rational=True)
        if exp is S.NegativeOne:
            base, exp = (Pow(base, tail), -1)
        elif exp is not S.One:
            tail = _keep_coeff(Rational(1, exp.q), tail)
            base, exp = (Pow(base, tail), exp.p)
        else:
            base, exp = (expr, 1)
    return (base, exp)

.sympy.core.exprtools.Factors.__init__

def __init__(self, factors=None):
    if isinstance(factors, (SYMPY_INTS, float)):
        factors = S(factors)
    if isinstance(factors, Factors):
        factors = factors.factors.copy()
    elif factors is None or factors is S.One:
        factors = {}
    elif factors is S.Zero or factors == 0:
        factors = {S.Zero: S.One}
    elif isinstance(factors, Number):
        n = factors
        factors = {}
        if n < 0:
            factors[S.NegativeOne] = S.One
            n = -n
        if n is not S.One:
            if n.is_Float or n.is_Integer or n is S.Infinity:
                factors[n] = S.One
            elif n.is_Rational:
                if n.p != 1:
                    factors[Integer(n.p)] = S.One
                factors[Integer(n.q)] = S.NegativeOne
            else:
                raise ValueError('Expected Float|Rational|Integer, not %s' % n)
    elif isinstance(factors, Basic) and (not factors.args):
        factors = {factors: S.One}
    elif isinstance(factors, Expr):
        c, nc = factors.args_cnc()
        i = c.count(I)
        for _ in range(i):
            c.remove(I)
        factors = dict(Mul._from_args(c).as_powers_dict())
        if i:
            factors[I] = S.One * i
        if nc:
            factors[Mul(*nc, evaluate=False)] = S.One
    else:
        factors = factors.copy()
        handle = []
        for k in factors:
            if k is I or k in (-1, 1):
                handle.append(k)
        if handle:
            i1 = S.One
            for k in handle:
                if not _isnumber(factors[k]):
                    continue
                i1 *= k ** factors.pop(k)
            if i1 is not S.One:
                for a in i1.args if i1.is_Mul else [i1]:
                    if a is S.NegativeOne:
                        factors[a] = S.One
                    elif a is I:
                        factors[I] = S.One
                    elif a.is_Pow:
                        if S.NegativeOne not in factors:
                            factors[S.NegativeOne] = S.Zero
                        factors[S.NegativeOne] += a.exp
                    elif a == 1:
                        factors[a] = S.One
                    elif a == -1:
                        factors[-a] = S.One
                        factors[S.NegativeOne] = S.One
                    else:
                        raise ValueError('unexpected factor in i1: %s' % a)
    self.factors = factors
    try:
        self.gens = frozenset(factors.keys())
    except AttributeError:
        raise TypeError('expecting Expr or dictionary')

.sympy.core.exprtools.Term.gcd

def gcd(self, other):
    return Term(self.coeff.gcd(other.coeff), self.numer.gcd(other.numer), self.denom.gcd(other.denom))

.sympy.core.numbers.Rational.gcd

def gcd(self, other):
    if isinstance(other, Rational):
        if other is S.Zero:
            return other
        return Rational(Integer(igcd(self.p, other.p)), Integer(ilcm(self.q, other.q)))
    return Number.gcd(self, other)

.sympy.core.exprtools.Factors.gcd

def gcd(self, other):
    if not isinstance(other, Factors):
        other = Factors(other)
        if other.is_zero:
            return Factors(self.factors)
    factors = {}
    for factor, exp in self.factors.items():
        factor, exp = (sympify(factor), sympify(exp))
        if factor in other.factors:
            lt = (exp - other.factors[factor]).is_negative
            if lt == True:
                factors[factor] = exp
            elif lt == False:
                factors[factor] = other.factors[factor]
    return Factors(factors)

.sympy.core.exprtools.Term.quo

def quo(self, other):
    return self.mul(other.inv())

.sympy.core.exprtools.Term.inv

def inv(self):
    return Term(1 / self.coeff, self.denom, self.numer)

.sympy.core.expr.Expr.__rdiv__

def __rdiv__(self, other):
    return Mul(other, Pow(self, S.NegativeOne))

.sympy.core.exprtools.Term.mul

def mul(self, other):
    coeff = self.coeff * other.coeff
    numer = self.numer.mul(other.numer)
    denom = self.denom.mul(other.denom)
    numer, denom = numer.normal(denom)
    return Term(coeff, numer, denom)

.sympy.core.exprtools.Factors.mul

def mul(self, other):
    if not isinstance(other, Factors):
        other = Factors(other)
    if any((f.is_zero for f in (self, other))):
        return Factors(S.Zero)
    factors = dict(self.factors)
    for factor, exp in other.factors.items():
        if factor in factors:
            exp = factors[factor] + exp
            if not exp:
                del factors[factor]
                continue
        factors[factor] = exp
    return Factors(factors)

.sympy.core.exprtools.Factors.is_zero

def is_zero(self):
    f = self.factors
    return len(f) == 1 and S.Zero in f

.sympy.core.exprtools.Factors.normal

def normal(self, other):
    if not isinstance(other, Factors):
        other = Factors(other)
        if other.is_zero:
            return (Factors(), Factors(S.Zero))
        if self.is_zero:
            return (Factors(S.Zero), Factors())
    self_factors = dict(self.factors)
    other_factors = dict(other.factors)
    for factor, self_exp in self.factors.items():
        try:
            other_exp = other.factors[factor]
        except KeyError:
            continue
        exp = self_exp - other_exp
        if not exp:
            del self_factors[factor]
            del other_factors[factor]
        elif _isnumber(exp):
            if exp > 0:
                self_factors[factor] = exp
                del other_factors[factor]
            else:
                del self_factors[factor]
                other_factors[factor] = -exp
        else:
            r = self_exp.extract_additively(other_exp)
            if r is not None:
                if r:
                    self_factors[factor] = r
                    del other_factors[factor]
                else:
                    del self_factors[factor]
                    del other_factors[factor]
            else:
                sc, sa = self_exp.as_coeff_Add()
                if sc:
                    oc, oa = other_exp.as_coeff_Add()
                    diff = sc - oc
                    if diff > 0:
                        self_factors[factor] -= oc
                        other_exp = oa
                    elif diff < 0:
                        self_factors[factor] -= sc
                        other_factors[factor] -= sc
                        other_exp = oa - diff
                    else:
                        self_factors[factor] = sa
                        other_exp = oa
                if other_exp:
                    other_factors[factor] = other_exp
                else:
                    del other_factors[factor]
    return (Factors(self_factors), Factors(other_factors))

.sympy.core.exprtools.Term.as_expr

def as_expr(self):
    return self.coeff * (self.numer.as_expr() / self.denom.as_expr())

.sympy.core.exprtools.Factors.as_expr

def as_expr(self):
    args = []
    for factor, exp in self.factors.items():
        if exp != 1:
            b, e = factor.as_base_exp()
            if isinstance(exp, int):
                e = _keep_coeff(Integer(exp), e)
            elif isinstance(exp, Rational):
                e = _keep_coeff(exp, e)
            else:
                e *= exp
            args.append(b ** e)
        else:
            args.append(factor)
    return Mul(*args)

.sympy.core.expr.Expr.__pow__

def __pow__(self, other):
    return Pow(self, other)

.sympy.core.numbers.Number.as_coeff_mul

def as_coeff_mul(self, *deps, **kwargs):
    if self.is_Rational or not kwargs.pop('rational', True):
        return (self, tuple())
    elif self.is_negative:
        return (S.NegativeOne, (-self,))
    return (S.One, (self,))

.sympy.core.mul.Mul._eval_is_real

def _eval_is_real(self):
    return self._eval_real_imag(True)

.sympy.core.mul.Mul._eval_real_imag

def _eval_real_imag(self, real):
    zero = False
    t_not_re_im = None
    for t in self.args:
        if not t.is_complex:
            return t.is_complex
        elif t.is_imaginary:
            real = not real
        elif t.is_real:
            if not zero:
                z = t.is_zero
                if not z and zero is False:
                    zero = z
                elif z:
                    if all((a.is_finite for a in self.args)):
                        return True
                    return
        elif t.is_real is False:
            if t_not_re_im:
                return
            t_not_re_im = t
        elif t.is_imaginary is False:
            if t_not_re_im:
                return
            t_not_re_im = t
        else:
            return
    if t_not_re_im:
        if t_not_re_im.is_real is False:
            if real:
                return zero
        if t_not_re_im.is_imaginary is False:
            if not real:
                return zero
    elif zero is False:
        return real
    elif real:
        return real

.sympy.core.logic._fuzzy_group

def _fuzzy_group(args, quick_exit=False):
    saw_other = False
    for a in args:
        if a is True:
            continue
        if a is None:
            return
        if quick_exit and saw_other:
            return
        saw_other = True
    return not saw_other

.sympy.core.power.Pow._eval_is_complex

def _eval_is_complex(self):
    if all((a.is_complex for a in self.args)):
        return True

.sympy.core.add.Add._eval_is_imaginary

def _eval_is_imaginary(self):
    nz = []
    im_I = []
    for a in self.args:
        if a.is_real:
            if a.is_zero:
                pass
            elif a.is_zero is False:
                nz.append(a)
            else:
                return
        elif a.is_imaginary:
            im_I.append(a * S.ImaginaryUnit)
        elif (S.ImaginaryUnit * a).is_real:
            im_I.append(a * S.ImaginaryUnit)
        else:
            return
    b = self.func(*nz)
    if b.is_zero:
        return fuzzy_not(self.func(*im_I).is_zero)
    elif b.is_zero is False:
        return False

.sympy.core.power.Pow._eval_is_real

def _eval_is_real(self):
    from sympy import arg, exp, log, Mul
    real_b = self.base.is_real
    if real_b is None:
        if self.base.func == exp and self.base.args[0].is_imaginary:
            return self.exp.is_imaginary
        return
    real_e = self.exp.is_real
    if real_e is None:
        return
    if real_b and real_e:
        if self.base.is_positive:
            return True
        elif self.base.is_nonnegative:
            if self.exp.is_nonnegative:
                return True
        elif self.exp.is_integer:
            return True
        elif self.base.is_negative:
            if self.exp.is_Rational:
                return False
    if real_e and self.exp.is_negative:
        return Pow(self.base, -self.exp).is_real
    im_b = self.base.is_imaginary
    im_e = self.exp.is_imaginary
    if im_b:
        if self.exp.is_integer:
            if self.exp.is_even:
                return True
            elif self.exp.is_odd:
                return False
        elif im_e and log(self.base).is_imaginary:
            return True
        elif self.exp.is_Add:
            c, a = self.exp.as_coeff_Add()
            if c and c.is_Integer:
                return Mul(self.base ** c, self.base ** a, evaluate=False).is_real
        elif self.base in (-S.ImaginaryUnit, S.ImaginaryUnit):
            if (self.exp / 2).is_integer is False:
                return False
    if real_b and im_e:
        if self.base is S.NegativeOne:
            return True
        c = self.exp.coeff(S.ImaginaryUnit)
        if c:
            ok = (c * log(self.base) / S.Pi).is_Integer
            if ok is not None:
                return ok
    if real_b is False:
        i = arg(self.base) * self.exp / S.Pi
        return i.is_integer

.sympy.core.power.Pow._eval_is_zero

def _eval_is_zero(self):
    if self.base.is_zero:
        if self.exp.is_positive:
            return True
        elif self.exp.is_nonpositive:
            return False
    elif self.base.is_zero is False:
        if self.exp.is_finite:
            return False
        elif self.exp.is_infinite:
            if (1 - abs(self.base)).is_positive:
                return self.exp.is_positive
            elif (1 - abs(self.base)).is_negative:
                return self.exp.is_negative
    else:
        return None

.sympy.core.add.Add._eval_is_zero

def _eval_is_zero(self):
    if self.is_commutative is False:
        return
    nz = []
    z = 0
    im_or_z = False
    im = False
    for a in self.args:
        if a.is_real:
            if a.is_zero:
                z += 1
            elif a.is_zero is False:
                nz.append(a)
            else:
                return
        elif a.is_imaginary:
            im = True
        elif (S.ImaginaryUnit * a).is_real:
            im_or_z = True
        else:
            return
    if z == len(self.args):
        return True
    if len(nz) == len(self.args):
        return None
    b = self.func(*nz)
    if b.is_zero:
        if not im_or_z and (not im):
            return True
        if im and (not im_or_z):
            return False
    if b.is_zero is False:
        return False

.sympy.core.add.Add._eval_is_nonpositive

def _eval_is_nonpositive(self):
    from sympy.core.exprtools import _monotonic_sign
    if not self.is_number:
        c, a = self.as_coeff_Add()
        if not c.is_zero and a.is_nonpositive:
            v = _monotonic_sign(a)
            if v is not None:
                s = v + c
                if s != self and s.is_nonpositive:
                    return True
                if len(self.free_symbols) == 1:
                    v = _monotonic_sign(self)
                    if v is not None and v != self and v.is_nonpositive:
                        return True

.sympy.core.add.Add._eval_is_negative

def _eval_is_negative(self):
    from sympy.core.exprtools import _monotonic_sign
    if self.is_number:
        return super(Add, self)._eval_is_negative()
    c, a = self.as_coeff_Add()
    if not c.is_zero:
        v = _monotonic_sign(a)
        if v is not None:
            s = v + c
            if s != self and s.is_negative and a.is_nonpositive:
                return True
            if len(self.free_symbols) == 1:
                v = _monotonic_sign(self)
                if v is not None and v != self and v.is_negative:
                    return True
    neg = nonpos = nonneg = unknown_sign = False
    saw_INF = set()
    args = [a for a in self.args if not a.is_zero]
    if not args:
        return False
    for a in args:
        isneg = a.is_negative
        infinite = a.is_infinite
        if infinite:
            saw_INF.add(fuzzy_or((isneg, a.is_nonpositive)))
            if True in saw_INF and False in saw_INF:
                return
        if isneg:
            neg = True
            continue
        elif a.is_nonpositive:
            nonpos = True
            continue
        elif a.is_nonnegative:
            nonneg = True
            continue
        if infinite is None:
            return
        unknown_sign = True
    if saw_INF:
        if len(saw_INF) > 1:
            return
        return saw_INF.pop()
    elif unknown_sign:
        return
    elif not nonneg and (not nonpos) and neg:
        return True
    elif not nonneg and neg:
        return True
    elif not neg and (not nonpos):
        return False

.sympy.core.operations.AssocOp._eval_evalf

def _eval_evalf(self, prec):
    from .add import Add
    from .mul import Mul
    from .symbol import Symbol
    from .function import AppliedUndef
    if isinstance(self, (Mul, Add)):
        x, tail = self.as_independent(Symbol, AppliedUndef)
        if not (tail is self.identity or (isinstance(x, AssocOp) and x.is_Function) or (x is self.identity and isinstance(tail, AssocOp))):
            x = x._evalf(prec) if x is not self.identity else self.identity
            args = []
            tail_args = tuple(self.func.make_args(tail))
            for a in tail_args:
                newa = a._eval_evalf(prec)
                if newa is None:
                    args.append(a)
                else:
                    args.append(newa)
            return self.func(x, *args)
    args = []
    for a in self.args:
        newa = a._eval_evalf(prec)
        if newa is None:
            args.append(a)
        else:
            args.append(newa)
    return self.func(*args)

.sympy.core.expr.Expr.as_independent

def as_independent(self, *deps, **hint):
    from .symbol import Symbol
    from .add import _unevaluated_Add
    from .mul import _unevaluated_Mul
    from sympy.utilities.iterables import sift
    if self.is_zero:
        return (S.Zero, S.Zero)
    func = self.func
    if hint.get('as_Add', func is Add):
        want = Add
    else:
        want = Mul
    sym = set()
    other = []
    for d in deps:
        if isinstance(d, Symbol):
            sym.add(d)
        else:
            other.append(d)

    def has(e):
        has_other = e.has(*other)
        if not sym:
            return has_other
        return has_other or e.has(*e.free_symbols & sym)
    if want is not func or (func is not Add and func is not Mul):
        if has(self):
            return (want.identity, self)
        else:
            return (self, want.identity)
    elif func is Add:
        args = list(self.args)
    else:
        args, nc = self.args_cnc()
    d = sift(args, lambda x: has(x))
    depend = d[True]
    indep = d[False]
    if func is Add:
        return (Add(*indep), _unevaluated_Add(*depend))
    else:
        for i, n in enumerate(nc):
            if has(n):
                depend.extend(nc[i:])
                break
            indep.append(n)
        return (Mul(*indep), Mul(*depend, evaluate=False) if nc else _unevaluated_Mul(*depend))

.sympy.utilities.iterables.sift

def sift(seq, keyfunc):
    m = defaultdict(list)
    for i in seq:
        m[keyfunc(i)].append(i)
    return m

.sympy.core.expr.Expr.has

def has(e):
    has_other = e.has(*other)
    if not sym:
        return has_other
    return has_other or e.has(*e.free_symbols & sym)

.sympy.core.basic.Basic.has

def has(self, *patterns):
    return any((self._has(pattern) for pattern in patterns))

.sympy.core.basic.Basic._has

def _has(self, pattern):
    from sympy.core.function import UndefinedFunction, Function
    if isinstance(pattern, UndefinedFunction):
        return any((f.func == pattern or f == pattern for f in self.atoms(Function, UndefinedFunction)))
    pattern = sympify(pattern)
    if isinstance(pattern, BasicMeta):
        return any((isinstance(arg, pattern) for arg in preorder_traversal(self)))
    try:
        match = pattern._has_matcher()
        return any((match(arg) for arg in preorder_traversal(self)))
    except AttributeError:
        return any((arg == pattern for arg in preorder_traversal(self)))

.sympy.core.add._unevaluated_Add

def _unevaluated_Add(*args):
    args = list(args)
    newargs = []
    co = S.Zero
    while args:
        a = args.pop()
        if a.is_Add:
            args.extend(a.args)
        elif a.is_Number:
            co += a
        else:
            newargs.append(a)
    _addsort(newargs)
    if co:
        newargs.insert(0, co)
    return Add._from_args(newargs)

.sympy.core.power.Pow._eval_evalf

def _eval_evalf(self, prec):
    base, exp = self.as_base_exp()
    base = base._evalf(prec)
    if not exp.is_Integer:
        exp = exp._evalf(prec)
    if exp.is_negative and base.is_number and (base.is_real is False):
        base = base.conjugate() / (base * base.conjugate())._evalf(prec)
        exp = -exp
        return self.func(base, exp).expand()
    return self.func(base, exp)

.sympy.core.evalf.EvalfMixin._evalf

def _evalf(self, prec):
    r = self._eval_evalf(prec)
    if r is None:
        r = self
    return r

.sympy.core.function.Function._eval_evalf

def _eval_evalf(self, prec):
    fname = self.func.__name__
    try:
        if not hasattr(mpmath, fname):
            from sympy.utilities.lambdify import MPMATH_TRANSLATIONS
            fname = MPMATH_TRANSLATIONS[fname]
        func = getattr(mpmath, fname)
    except (AttributeError, KeyError):
        try:
            return Float(self._imp_(*[i.evalf(prec) for i in self.args]), prec)
        except (AttributeError, TypeError, ValueError):
            return
    try:
        args = [arg._to_mpmath(prec + 5) for arg in self.args]

        def bad(m):
            from mpmath import mpf, mpc
            if isinstance(m, mpf):
                m = m._mpf_
                return m[1] != 1 and m[-1] == 1
            elif isinstance(m, mpc):
                m, n = m._mpc_
                return m[1] != 1 and m[-1] == 1 and (n[1] != 1) and (n[-1] == 1)
            else:
                return False
        if any((bad(a) for a in args)):
            raise ValueError
    except ValueError:
        return
    with mpmath.workprec(prec):
        v = func(*args)
    return Expr._from_mpmath(v, prec)

.sympy.core.evalf.EvalfMixin._to_mpmath

def _to_mpmath(self, prec, allow_ints=True):
    errmsg = 'cannot convert to mpmath number'
    if allow_ints and self.is_Integer:
        return self.p
    if hasattr(self, '_as_mpf_val'):
        return make_mpf(self._as_mpf_val(prec))
    try:
        re, im, _, _ = evalf(self, prec, {})
        if im:
            if not re:
                re = fzero
            return make_mpc((re, im))
        elif re:
            return make_mpf(re)
        else:
            return make_mpf(fzero)
    except NotImplementedError:
        v = self._eval_evalf(prec)
        if v is None:
            raise ValueError(errmsg)
        if v.is_Float:
            return make_mpf(v._mpf_)
        re, im = v.as_real_imag()
        if allow_ints and re.is_Integer:
            re = from_int(re.p)
        elif re.is_Float:
            re = re._mpf_
        else:
            raise ValueError(errmsg)
        if allow_ints and im.is_Integer:
            im = from_int(im.p)
        elif im.is_Float:
            im = im._mpf_
        else:
            raise ValueError(errmsg)
        return make_mpc((re, im))

.sympy.core.function.Function.bad

def bad(m):
    from mpmath import mpf, mpc
    if isinstance(m, mpf):
        m = m._mpf_
        return m[1] != 1 and m[-1] == 1
    elif isinstance(m, mpc):
        m, n = m._mpc_
        return m[1] != 1 and m[-1] == 1 and (n[1] != 1) and (n[-1] == 1)
    else:
        return False

.sympy.core.expr.Expr._from_mpmath

def _from_mpmath(x, prec):
    from sympy import Float
    if hasattr(x, '_mpf_'):
        return Float._new(x._mpf_, prec)
    elif hasattr(x, '_mpc_'):
        re, im = x._mpc_
        re = Float._new(re, prec)
        im = Float._new(im, prec) * S.ImaginaryUnit
        return re + im
    else:
        raise TypeError('expected mpmath number (mpf or mpc)')

.sympy.core.numbers.Float._eval_is_negative

def _eval_is_negative(self):
    if self._mpf_ == _mpf_ninf:
        return True
    if self._mpf_ == _mpf_inf:
        return False
    return self.num < 0

.sympy.core.numbers.Float.num

def num(self):
    return mpmath.mpf(self._mpf_)

.sympy.core.numbers.Float._eval_power

def _eval_power(self, expt):
    if self == 0:
        if expt.is_positive:
            return S.Zero
        if expt.is_negative:
            return Float('inf')
    if isinstance(expt, Number):
        if isinstance(expt, Integer):
            prec = self._prec
            return Float._new(mlib.mpf_pow_int(self._mpf_, expt.p, prec, rnd), prec)
        elif isinstance(expt, Rational) and expt.p == 1 and expt.q % 2 and self.is_negative:
            return Pow(S.NegativeOne, expt, evaluate=False) * (-self)._eval_power(expt)
        expt, prec = expt._as_mpf_op(self._prec)
        mpfself = self._mpf_
        try:
            y = mpf_pow(mpfself, expt, prec, rnd)
            return Float._new(y, prec)
        except mlib.ComplexResult:
            re, im = mlib.mpc_pow((mpfself, _mpf_zero), (expt, _mpf_zero), prec, rnd)
            return Float._new(re, prec) + Float._new(im, prec) * S.ImaginaryUnit

.sympy.core.numbers.Rational.__add__

def __add__(self, other):
    if global_evaluate[0]:
        if isinstance(other, Integer):
            return Rational(self.p + self.q * other.p, self.q, 1)
        elif isinstance(other, Rational):
            return Rational(self.p * other.q + self.q * other.p, self.q * other.q)
        elif isinstance(other, Float):
            return other + self
        else:
            return Number.__add__(self, other)
    return Number.__add__(self, other)

.sympy.core.numbers.Float.__add__

def __add__(self, other):
    if isinstance(other, Number) and global_evaluate[0]:
        rhs, prec = other._as_mpf_op(self._prec)
        return Float._new(mlib.mpf_add(self._mpf_, rhs, prec, rnd), prec)
    return Number.__add__(self, other)

.sympy.core.numbers.Number._as_mpf_op

def _as_mpf_op(self, prec):
    prec = max(prec, self._prec)
    return (self._as_mpf_val(prec), prec)

.sympy.core.numbers.Float._as_mpf_op

def _as_mpf_op(self, prec):
    return (self._mpf_, max(prec, self._prec))

.sympy.core.add.Add._eval_is_positive

def _eval_is_positive(self):
    from sympy.core.exprtools import _monotonic_sign
    if self.is_number:
        return super(Add, self)._eval_is_positive()
    c, a = self.as_coeff_Add()
    if not c.is_zero:
        v = _monotonic_sign(a)
        if v is not None:
            s = v + c
            if s != self and s.is_positive and a.is_nonnegative:
                return True
            if len(self.free_symbols) == 1:
                v = _monotonic_sign(self)
                if v is not None and v != self and v.is_positive:
                    return True
    pos = nonneg = nonpos = unknown_sign = False
    saw_INF = set()
    args = [a for a in self.args if not a.is_zero]
    if not args:
        return False
    for a in args:
        ispos = a.is_positive
        infinite = a.is_infinite
        if infinite:
            saw_INF.add(fuzzy_or((ispos, a.is_nonnegative)))
            if True in saw_INF and False in saw_INF:
                return
        if ispos:
            pos = True
            continue
        elif a.is_nonnegative:
            nonneg = True
            continue
        elif a.is_nonpositive:
            nonpos = True
            continue
        if infinite is None:
            return
        unknown_sign = True
    if saw_INF:
        if len(saw_INF) > 1:
            return
        return saw_INF.pop()
    elif unknown_sign:
        return
    elif not nonpos and (not nonneg) and pos:
        return True
    elif not nonpos and pos:
        return True
    elif not pos and (not nonneg):
        return False

.sympy.core.expr.Expr._eval_is_positive

def _eval_is_positive(self):
    from sympy.polys.numberfields import minimal_polynomial
    from sympy.polys.polyerrors import NotAlgebraic
    if self.is_number:
        if self.is_real is False:
            return False
        try:
            n2 = self._eval_evalf(2)
            if n2 is None:
                raise AttributeError
            if n2._prec == 1:
                raise AttributeError
            if n2 == S.NaN:
                raise AttributeError
        except (AttributeError, ValueError):
            return None
        n, i = self.evalf(2).as_real_imag()
        if not i.is_Number or not n.is_Number:
            return False
        if n._prec != 1 and i._prec != 1:
            return bool(not i and n > 0)
        elif n._prec == 1 and (not i or i._prec == 1) and self.is_algebraic and (not self.has(Function)):
            try:
                if minimal_polynomial(self).is_Symbol:
                    return False
            except (NotAlgebraic, NotImplementedError):
                pass

.sympy.core.numbers.Float.__gt__

def __gt__(self, other):
    try:
        other = _sympify(other)
    except SympifyError:
        raise TypeError('Invalid comparison %s > %s' % (self, other))
    if isinstance(other, NumberSymbol):
        return other.__lt__(self)
    if other.is_comparable:
        other = other.evalf()
    if isinstance(other, Number) and other is not S.NaN:
        return _sympify(bool(mlib.mpf_gt(self._mpf_, other._as_mpf_val(self._prec))))
    return Expr.__gt__(self, other)

.sympy.core.basic.Basic.is_comparable

def is_comparable(self):
    is_real = self.is_real
    if is_real is False:
        return False
    is_number = self.is_number
    if is_number is False:
        return False
    n, i = [p.evalf(2) if not p.is_Number else p for p in self.as_real_imag()]
    if not i.is_Number or not n.is_Number:
        return False
    if i:
        return False
    else:
        return n._prec != 1

.sympy.core.power.Pow._eval_is_rational

def _eval_is_rational(self):
    p = self.func(*self.as_base_exp())
    if not p.is_Pow:
        return p.is_rational
    b, e = p.as_base_exp()
    if e.is_Rational and b.is_Rational:
        return False
    if e.is_integer:
        if b.is_rational:
            if fuzzy_not(b.is_zero) or e.is_nonnegative:
                return True
            if b == e:
                return True
        elif b.is_irrational:
            return e.is_zero

.sympy.core.add.Add._eval_is_odd

def _eval_is_odd(self):
    l = [f for f in self.args if not f.is_even is True]
    if not l:
        return False
    if l[0].is_odd:
        return self._new_rawargs(*l[1:]).is_even

.sympy.core.power.Pow._eval_is_algebraic

def _eval_is_algebraic(self):

    def _is_one(expr):
        try:
            return (expr - 1).is_zero
        except ValueError:
            return False
    if self.base.is_zero or _is_one(self.base):
        return True
    elif self.exp.is_rational:
        if self.base.is_algebraic is False:
            return self.exp.is_zero
        return self.base.is_algebraic
    elif self.base.is_algebraic and self.exp.is_algebraic:
        if fuzzy_not(self.base.is_zero) and fuzzy_not(_is_one(self.base)) or self.base.is_integer is False or self.base.is_irrational:
            return self.exp.is_rational

.sympy.core.power.Pow._is_one

def _is_one(expr):
    try:
        return (expr - 1).is_zero
    except ValueError:
        return False

.sympy.core.add.Add._eval_is_irrational

def _eval_is_irrational(self):
    for t in self.args:
        a = t.is_irrational
        if a:
            others = list(self.args)
            others.remove(t)
            if all((x.is_rational is True for x in others)):
                return True
            return None
        if a is None:
            return
    return False

.sympy.core.expr.Expr.as_base_exp

def as_base_exp(self):
    return (self, S.One)

.sympy.core.mul.Mul.as_base_exp

def as_base_exp(self):
    e1 = None
    bases = []
    nc = 0
    for m in self.args:
        b, e = m.as_base_exp()
        if not b.is_commutative:
            nc += 1
        if e1 is None:
            e1 = e
        elif e != e1 or nc > 1:
            return (self, S.One)
        bases.append(b)
    return (self.func(*bases), e1)

.sympy.core.numbers.Integer.__ne__

def __ne__(self, other):
    return not self == other

.sympy.core.mul.Mul.as_coeff_mul

def as_coeff_mul(self, *deps, **kwargs):
    rational = kwargs.pop('rational', True)
    if deps:
        l1 = []
        l2 = []
        for f in self.args:
            if f.has(*deps):
                l2.append(f)
            else:
                l1.append(f)
        return (self._new_rawargs(*l1), tuple(l2))
    args = self.args
    if args[0].is_Number:
        if not rational or args[0].is_Rational:
            return (args[0], args[1:])
        elif args[0].is_negative:
            return (S.NegativeOne, (-args[0],) + args[1:])
    return (S.One, args)

.sympy.core.numbers.Integer._eval_power

def _eval_power(self, expt):
    from sympy import perfect_power
    if expt is S.Infinity:
        if self.p > S.One:
            return S.Infinity
        return S.Infinity + S.ImaginaryUnit * S.Infinity
    if expt is S.NegativeInfinity:
        return Rational(1, self) ** S.Infinity
    if not isinstance(expt, Number):
        if self.is_negative and expt.is_even:
            return (-self) ** expt
    if isinstance(expt, Float):
        return super(Integer, self)._eval_power(expt)
    if not isinstance(expt, Rational):
        return
    if expt is S.Half and self.is_negative:
        return S.ImaginaryUnit * Pow(-self, expt)
    if expt.is_negative:
        ne = -expt
        if self.is_negative:
            if expt.q != 1:
                return -S.NegativeOne ** (expt.p % expt.q / S(expt.q)) * Rational(1, -self) ** ne
            else:
                return S.NegativeOne ** ne * Rational(1, -self) ** ne
        else:
            return Rational(1, self.p) ** ne
    x, xexact = integer_nthroot(abs(self.p), expt.q)
    if xexact:
        result = Integer(x ** abs(expt.p))
        if self.is_negative:
            result *= S.NegativeOne ** expt
        return result
    b_pos = int(abs(self.p))
    p = perfect_power(b_pos)
    if p is not False:
        dict = {p[0]: p[1]}
    else:
        dict = Integer(self).factors(limit=2 ** 15)
    if self.is_negative:
        dict[-1] = 1
    out_int = 1
    out_rad = 1
    sqr_int = 1
    sqr_gcd = 0
    sqr_dict = {}
    for prime, exponent in dict.items():
        exponent *= expt.p
        div_e, div_m = divmod(exponent, expt.q)
        if div_e > 0:
            out_int *= prime ** div_e
        if div_m > 0:
            g = igcd(div_m, expt.q)
            if g != 1:
                out_rad *= Pow(prime, Rational(div_m // g, expt.q // g))
            else:
                sqr_dict[prime] = div_m
    for p, ex in sqr_dict.items():
        if sqr_gcd == 0:
            sqr_gcd = ex
        else:
            sqr_gcd = igcd(sqr_gcd, ex)
            if sqr_gcd == 1:
                break
    for k, v in sqr_dict.items():
        sqr_int *= k ** (v // sqr_gcd)
    if sqr_int == self and out_int == 1 and (out_rad == 1):
        result = None
    else:
        result = out_int * out_rad * Pow(sqr_int, Rational(sqr_gcd, expt.q))
    return result

