.sympy.core.exprtools.Factors.lcm

def lcm(self, other):
    if not isinstance(other, Factors):
        other = Factors(other)
        if any((f.is_zero for f in (self, other))):
            return Factors(S.Zero)
    factors = dict(self.factors)
    for factor, exp in other.factors.items():
        if factor in factors:
            exp = max(exp, factors[factor])
        factors[factor] = exp
    return Factors(factors)

.sympy.core.exprtools.Factors.quo

def quo(self, other):
    return self.div(other)[0]

.sympy.core.exprtools.Factors.div

def div(self, other):
    quo, rem = (dict(self.factors), {})
    if not isinstance(other, Factors):
        other = Factors(other)
        if other.is_zero:
            raise ZeroDivisionError
        if self.is_zero:
            return (Factors(S.Zero), Factors())
    for factor, exp in other.factors.items():
        if factor in quo:
            d = quo[factor] - exp
            if _isnumber(d):
                if d <= 0:
                    del quo[factor]
                if d >= 0:
                    if d:
                        quo[factor] = d
                    continue
                exp = -d
            else:
                r = quo[factor].extract_additively(exp)
                if r is not None:
                    if r:
                        quo[factor] = r
                    else:
                        del quo[factor]
                else:
                    other_exp = exp
                    sc, sa = quo[factor].as_coeff_Add()
                    if sc:
                        oc, oa = other_exp.as_coeff_Add()
                        diff = sc - oc
                        if diff > 0:
                            quo[factor] -= oc
                            other_exp = oa
                        elif diff < 0:
                            quo[factor] -= sc
                            other_exp = oa - diff
                        else:
                            quo[factor] = sa
                            other_exp = oa
                    if other_exp:
                        rem[factor] = other_exp
                    else:
                        assert factor not in rem
                continue
        rem[factor] = exp
    return (Factors(quo), Factors(rem))

