.sympy.polys.euclidtools._dup_zz_gcd_interpolate

def _dup_zz_gcd_interpolate(h, x, K):
    f = []
    while h:
        g = h % x
        if g > x // 2:
            g -= x
        f.insert(0, g)
        h = (h - g) // x
    return f

.sympy.polys.densearith.dup_quo_ground

def dup_quo_ground(f, c, K):
    if not c:
        raise ZeroDivisionError('polynomial division')
    if not f:
        return f
    if K.is_Field:
        return [K.quo(cf, c) for cf in f]
    else:
        return [cf // c for cf in f]

.sympy.polys.densearith.dup_div

def dup_div(f, g, K):
    if K.is_Field:
        return dup_ff_div(f, g, K)
    else:
        return dup_rr_div(f, g, K)

.sympy.polys.densearith.dup_rr_div

def dup_rr_div(f, g, K):
    df = dup_degree(f)
    dg = dup_degree(g)
    q, r, dr = ([], f, df)
    if not g:
        raise ZeroDivisionError('polynomial division')
    elif df < dg:
        return (q, r)
    lc_g = dup_LC(g, K)
    while True:
        lc_r = dup_LC(r, K)
        if lc_r % lc_g:
            break
        c = K.exquo(lc_r, lc_g)
        j = dr - dg
        q = dup_add_term(q, c, j, K)
        h = dup_mul_term(g, c, j, K)
        r = dup_sub(r, h, K)
        _dr, dr = (dr, dup_degree(r))
        if dr < dg:
            break
        elif not dr < _dr:
            raise PolynomialDivisionFailed(f, g, K)
    return (q, r)

.sympy.polys.domains.ring.Ring.exquo

def exquo(self, a, b):
    if a % b:
        raise ExactQuotientFailed(a, b, self)
    else:
        return a // b

.sympy.polys.densearith.dup_add_term

def dup_add_term(f, c, i, K):
    if not c:
        return f
    n = len(f)
    m = n - i - 1
    if i == n - 1:
        return dup_strip([f[0] + c] + f[1:])
    elif i >= n:
        return [c] + [K.zero] * (i - n) + f
    else:
        return f[:m] + [f[m] + c] + f[m + 1:]

.sympy.polys.densearith.dup_mul_term

def dup_mul_term(f, c, i, K):
    if not c or not f:
        return []
    else:
        return [cf * c for cf in f] + [K.zero] * i

.sympy.polys.densearith.dup_sub

def dup_sub(f, g, K):
    if not f:
        return dup_neg(g, K)
    if not g:
        return f
    df = dup_degree(f)
    dg = dup_degree(g)
    if df == dg:
        return dup_strip([a - b for a, b in zip(f, g)])
    else:
        k = abs(df - dg)
        if df > dg:
            h, f = (f[:k], f[k:])
        else:
            h, g = (dup_neg(g[:k], K), g[k:])
        return h + [a - b for a, b in zip(f, g)]

.sympy.core.numbers.NegativeInfinity.__lt__

def __lt__(self, other):
    try:
        other = _sympify(other)
    except SympifyError:
        raise TypeError('Invalid comparison %s < %s' % (self, other))
    if other.is_real:
        if other.is_finite or other is S.Infinity:
            return S.true
        elif other.is_nonnegative:
            return S.true
        elif other.is_infinite and other.is_negative:
            return S.false
    return Expr.__lt__(self, other)

