    elif is_integer is False:
        return False

.sympy.polys.densebasic.dmp_terms_gcd

def dmp_terms_gcd(f, u, K):
    if dmp_ground_TC(f, u, K) or dmp_zero_p(f, u):
        return ((0,) * (u + 1), f)
    F = dmp_to_dict(f, u)
    G = monomial_min(*list(F.keys()))
    if all((g == 0 for g in G)):
        return (G, f)
    f = {}
    for monom, coeff in F.items():
        f[monomial_div(monom, G)] = coeff
    return (G, dmp_from_dict(f, u, K))

.sympy.polys.densebasic.dmp_ground_TC

def dmp_ground_TC(f, u, K):
    while u:
        f = dmp_TC(f, K)
        u -= 1
    return dup_TC(f, K)

.sympy.polys.densetools.dmp_ground_primitive

def dmp_ground_primitive(f, u, K):
    if not u:
        return dup_primitive(f, K)
    if dmp_zero_p(f, u):
        return (K.zero, f)
    cont = dmp_ground_content(f, u, K)
    if K.is_one(cont):
        return (cont, f)
    else:
        return (cont, dmp_quo_ground(f, cont, u, K))

.sympy.polys.densetools.dmp_ground_content

def dmp_ground_content(f, u, K):
    from sympy.polys.domains import QQ
    if not u:
        return dup_content(f, K)
    if dmp_zero_p(f, u):
        return K.zero
    cont, v = (K.zero, u - 1)
    if K == QQ:
        for c in f:
            cont = K.gcd(cont, dmp_ground_content(c, v, K))
    else:
        for c in f:
            cont = K.gcd(cont, dmp_ground_content(c, v, K))
            if K.is_one(cont):
                break
    return cont

.sympy.polys.densebasic.dmp_exclude

def dmp_exclude(f, u, K):
    if not u or dmp_ground_p(f, None, u):
        return ([], f, u)
    J, F = ([], dmp_to_dict(f, u))
    for j in range(0, u + 1):
        for monom in F.keys():
            if monom[j]:
                break
        else:
            J.append(j)
    if not J:
        return ([], f, u)
    f = {}
    for monom, coeff in F.items():
        monom = list(monom)
        for j in reversed(J):
            del monom[j]
        f[tuple(monom)] = coeff
    u -= len(J)
    return (J, dmp_from_dict(f, u, K), u)

.sympy.polys.factortools.dmp_zz_factor

def dmp_zz_factor(f, u, K):
    if not u:
        return dup_zz_factor(f, K)
    if dmp_zero_p(f, u):
        return (K.zero, [])
    cont, g = dmp_ground_primitive(f, u, K)
    if dmp_ground_LC(g, u, K) < 0:
        cont, g = (-cont, dmp_neg(g, u, K))
    if all((d <= 0 for d in dmp_degree_list(g, u))):
        return (cont, [])
    G, g = dmp_primitive(g, u, K)
    factors = []
    if dmp_degree(g, u) > 0:
        g = dmp_sqf_part(g, u, K)
        H = dmp_zz_wang(g, u, K)
        factors = dmp_trial_division(f, H, u, K)
    for g, k in dmp_zz_factor(G, u - 1, K)[1]:
        factors.insert(0, ([g], k))
    return (cont, _sort_factors(factors))

.sympy.polys.densebasic.dmp_degree_list

def dmp_degree_list(f, u):
    degs = [-oo] * (u + 1)
    _rec_degree_list(f, u, 0, degs)
    return tuple(degs)

.sympy.polys.densebasic._rec_degree_list

def _rec_degree_list(g, v, i, degs):
    degs[i] = max(degs[i], dmp_degree(g, v))
    if v > 0:
        v, i = (v - 1, i + 1)
        for c in g:
            _rec_degree_list(c, v, i, degs)

