from collections import defaultdict
from sympy.core.mul import Mul
from sympy.core.traversal import bottom_up
from sympy.functions.elementary.trigonometric import cos, sin, tan, cot, sec, csc, sqrt, TrigonometricFunction

def TRmorrie(rv):

    def f(rv, first=True):
        if not rv.is_Mul:
            return rv
        if first:
            n, d = rv.as_numer_denom()
            return f(n, 0) / f(d, 0)
        args = defaultdict(list)
        coss = {}
        other = []
        for c in rv.args:
            b, e = c.as_base_exp()
            if e.is_Integer and isinstance(b, cos):
                co, a = b.args[0].as_coeff_Mul()
                args[a].append(co)
                coss[b] = e
            else:
                other.append(c)
        new = []
        for a in args:
            c = args[a]
            c.sort()
            while c:
                k = 0
                cc = ci = c[0]
                while cc in c:
                    k += 1
                    cc *= 2
                if k > 1:
                    newarg = sin(2 ** k * ci * a) / 2 ** k / sin(ci * a)
                    take = None
                    ccs = []
                    for i in range(k):
                        cc /= 2
                        key = cos(a * cc, evaluate=False)
                        ccs.append(cc)
                        take = min(coss[key], take or coss[key])
                    for i in range(k):
                        cc = ccs.pop()
                        key = cos(a * cc, evaluate=False)
                        coss[key] -= take
                        if not coss[key]:
                            c.remove(cc)
                    new.append(newarg ** take)
                else:
                    b = cos(c.pop(0) * a)
                    other.append(b ** coss[b])
        if new:
            rv = Mul(*new + other + [cos(k * a, evaluate=False) for a in args for k in args[a]])
        return rv
    return bottom_up(rv, f)

sympy.sympy.core.traversal.bottom_up

def bottom_up(rv, F, atoms=False, nonbasic=False):
    """Apply ``F`` to all expressions in an expression tree from the
    bottom up. If ``atoms`` is True, apply ``F`` even if there are no args;
    if ``nonbasic`` is True, try to apply ``F`` to non-Basic objects.
    """
    args = getattr(rv, 'args', None)
    if args is not None:
        if args:
            args = tuple([bottom_up(a, F, atoms, nonbasic) for a in args])
            if args != rv.args:
                rv = rv.func(*args)
            rv = F(rv)
        elif atoms:
            rv = F(rv)
    else:
        if nonbasic:
            try:
                rv = F(rv)
            except TypeError:
                pass

    return rv

