.django.core.management.base.BaseCommand.create_parser

def create_parser(self, prog_name, subcommand, **kwargs):
    parser = CommandParser(prog='%s %s' % (os.path.basename(prog_name), subcommand), description=self.help or None, formatter_class=DjangoHelpFormatter, missing_args_message=getattr(self, 'missing_args_message', None), called_from_command_line=getattr(self, '_called_from_command_line', None), **kwargs)
    self.add_base_argument(parser, '--version', action='version', version=self.get_version(), help="Show program's version number and exit.")
    self.add_base_argument(parser, '-v', '--verbosity', default=1, type=int, choices=[0, 1, 2, 3], help='Verbosity level; 0=minimal output, 1=normal output, 2=verbose output, 3=very verbose output')
    self.add_base_argument(parser, '--settings', help='The Python path to a settings module, e.g. "myproject.settings.main". If this isn\'t provided, the DJANGO_SETTINGS_MODULE environment variable will be used.')
    self.add_base_argument(parser, '--pythonpath', help='A directory to add to the Python path, e.g. "/home/djangoprojects/myproject".')
    self.add_base_argument(parser, '--traceback', action='store_true', help='Raise on CommandError exceptions.')
    self.add_base_argument(parser, '--no-color', action='store_true', help="Don't colorize the command output.")
    self.add_base_argument(parser, '--force-color', action='store_true', help='Force colorization of the command output.')
    if self.requires_system_checks:
        parser.add_argument('--skip-checks', action='store_true', help='Skip system checks.')
    self.add_arguments(parser)
    return parser

.django.core.management.base.CommandParser.__init__

def __init__(self, *, missing_args_message=None, called_from_command_line=None, **kwargs):
    self.missing_args_message = missing_args_message
    self.called_from_command_line = called_from_command_line
    super().__init__(**kwargs)

.django.core.management.base.BaseCommand.get_version

def get_version(self):
    return django.get_version()

.django.utils.version.get_version

def get_version(version=None):
    version = get_complete_version(version)
    main = get_main_version(version)
    sub = ''
    if version[3] == 'alpha' and version[4] == 0:
        git_changeset = get_git_changeset()
        if git_changeset:
            sub = '.dev%s' % git_changeset
    elif version[3] != 'final':
        mapping = {'alpha': 'a', 'beta': 'b', 'rc': 'rc'}
        sub = mapping[version[3]] + str(version[4])
    return main + sub

.django.utils.version.get_complete_version

def get_complete_version(version=None):
    if version is None:
        from django import VERSION as version
    else:
        assert len(version) == 5
        assert version[3] in ('alpha', 'beta', 'rc', 'final')
    return version

.django.utils.version.get_main_version

def get_main_version(version=None):
    version = get_complete_version(version)
    parts = 2 if version[2] == 0 else 3
    return '.'.join((str(x) for x in version[:parts]))

.django.core.management.base.BaseCommand.add_base_argument

def add_base_argument(self, parser, *args, **kwargs):
    for arg in args:
        if arg in self.suppressed_base_arguments:
            kwargs['help'] = argparse.SUPPRESS
            break
    parser.add_argument(*args, **kwargs)

.django.core.management.commands.check.Command.add_arguments

def add_arguments(self, parser):
    parser.add_argument('args', metavar='app_label', nargs='*')
    parser.add_argument('--tag', '-t', action='append', dest='tags', help='Run only checks labeled with given tag.')
    parser.add_argument('--list-tags', action='store_true', help='List available tags.')
    parser.add_argument('--deploy', action='store_true', help='Check deployment settings.')
    parser.add_argument('--fail-level', default='ERROR', choices=['CRITICAL', 'ERROR', 'WARNING', 'INFO', 'DEBUG'], help='Message level that will cause the command to exit with a non-zero status. Default is ERROR.')
    parser.add_argument('--database', action='append', dest='databases', help='Run database related checks against these aliases.')

.django.core.management.base.CommandParser.parse_args

def parse_args(self, args=None, namespace=None):
    if self.missing_args_message and (not (args or any((not arg.startswith('-') for arg in args)))):
        self.error(self.missing_args_message)
    return super().parse_args(args, namespace)

.django.core.management.base.no_translations

def no_translations(handle_func):

    def wrapped(*args, **kwargs):
        from django.utils import translation
        saved_locale = translation.get_language()
        translation.deactivate_all()
        try:
            res = handle_func(*args, **kwargs)
        finally:
            if saved_locale is not None:
                translation.activate(saved_locale)
        return res
    return wrapped

.django.core.management.base.BaseCommand.add_arguments

def add_arguments(self, parser):
    pass

.django.core.management.base.DjangoHelpFormatter.add_usage

def add_usage(self, usage, actions, *args, **kwargs):
    super().add_usage(usage, self._reordered_actions(actions), *args, **kwargs)

.django.core.management.base.DjangoHelpFormatter._reordered_actions

def _reordered_actions(self, actions):
    return sorted(actions, key=lambda a: set(a.option_strings) & self.show_last != set())

from typing import Callable, Iterator, List, Optional, SupportsInt, Tuple, Union

def parse(version: str) -> Union['LegacyVersion', 'Version']:
    try:
        return Version(version)
    except InvalidVersion:
        return LegacyVersion(version)

scikit-learn.sklearn.externals._packaging.version.__init__

def __init__(self, version: str) -> None:

    # Validate the version and parse it into pieces
    match = self._regex.search(version)
    if not match:
        raise InvalidVersion(f"Invalid version: '{version}'")

    # Store the parsed out pieces of the version
    self._version = _Version(
        epoch=int(match.group("epoch")) if match.group("epoch") else 0,
        release=tuple(int(i) for i in match.group("release").split(".")),
        pre=_parse_letter_version(match.group("pre_l"), match.group("pre_n")),
        post=_parse_letter_version(
            match.group("post_l"), match.group("post_n1") or match.group("post_n2")
        ),
        dev=_parse_letter_version(match.group("dev_l"), match.group("dev_n")),
        local=_parse_local_version(match.group("local")),
    )

    # Generate a key which will be used for sorting
    self._key = _cmpkey(
        self._version.epoch,
        self._version.release,
        self._version.pre,
        self._version.post,
        self._version.dev,
        self._version.local,
    )

