sympy.sympy.polys.polyutils._not_a_coeff

def _not_a_coeff(expr):
    """Do not treat NaN and infinities as valid polynomial coefficients. """
    if type(expr) in illegal_types or expr in finf:
        return True
    if isinstance(expr, float) and float(expr) != expr:
        return True  # nan
    return  # could be

sympy.sympy.polys.polyutils._is_coeff

def _is_coeff(factor):
    return factor.is_number

sympy.sympy.polys.polyutils._sort_gens

def _sort_gens(gens, **args):
    """Sort generators in a reasonably intelligent way. """
    opt = build_options(args)

    gens_order, wrt = {}, None

    if opt is not None:
        gens_order, wrt = {}, opt.wrt

        for i, gen in enumerate(opt.sort):
            gens_order[gen] = i + 1

    def order_key(gen):
        gen = str(gen)

        if wrt is not None:
            try:
                return (-len(wrt) + wrt.index(gen), gen, 0)
            except ValueError:
                pass

        name, index = _re_gen.match(gen).groups()

        if index:
            index = int(index)
        else:
            index = 0

        try:
            return ( gens_order[name], name, index)
        except KeyError:
            pass

        try:
            return (_gens_order[name], name, index)
        except KeyError:
            pass

        return (_max_order, name, index)

    try:
        gens = sorted(gens, key=order_key)
    except TypeError:  # pragma: no cover
        pass

    return tuple(gens)

from functools import cache, reduce, wraps
import inspect
import re
import numpy as np

class ArtistInspector:

    def __init__(self, o):
        if not isinstance(o, Artist):
            if np.iterable(o):
                o = list(o)
                if len(o):
                    o = o[0]
        self.oorig = o
        if not isinstance(o, type):
            o = type(o)
        self.o = o
        self.aliasd = self.get_aliases()

    def get_aliases(self):
        names = [name for name in dir(self.o) if name.startswith(('set_', 'get_')) and callable(getattr(self.o, name))]
        aliases = {}
        for name in names:
            func = getattr(self.o, name)
            if not self.is_alias(func):
                continue
            propname = re.search(f'`({name[:4]}.*)`', inspect.getdoc(func)).group(1)
            aliases.setdefault(propname[4:], set()).add(name[4:])
        return aliases
    _get_valid_values_regex = re.compile('\\n\\s*(?:\\.\\.\\s+)?ACCEPTS:\\s*((?:.|\\n)*?)(?:$|(?:\\n\\n))')

    def get_valid_values(self, attr):
        name = 'set_%s' % attr
        if not hasattr(self.o, name):
            raise AttributeError(f'{self.o} has no function {name}')
        func = getattr(self.o, name)
        if hasattr(func, '_kwarg_doc'):
            return func._kwarg_doc
        docstring = inspect.getdoc(func)
        if docstring is None:
            return 'unknown'
        if docstring.startswith('Alias for '):
            return None
        match = self._get_valid_values_regex.search(docstring)
        if match is not None:
            return re.sub('\n *', ' ', match.group(1))
        param_name = func.__code__.co_varnames[1]
        match = re.search(f'(?m)^ *\\*?{param_name} : (.+)', docstring)
        if match:
            return match.group(1)
        return 'unknown'

    def get_setters(self):
        setters = []
        for name in dir(self.o):
            if not name.startswith('set_'):
                continue
            func = getattr(self.o, name)
            if not callable(func) or self.number_of_parameters(func) < 2 or self.is_alias(func):
                continue
            setters.append(name[4:])
        return setters

    @staticmethod
    @cache
    def number_of_parameters(func):
        return len(inspect.signature(func).parameters)

    @staticmethod
    @cache
    def is_alias(method):
        ds = inspect.getdoc(method)
        if ds is None:
            return False
        return ds.startswith('Alias for ')

    def aliased_name(self, s):
        aliases = ''.join((' or %s' % x for x in sorted(self.aliasd.get(s, []))))
        return s + aliases
    _NOT_LINKABLE = {'matplotlib.image._ImageBase.set_alpha', 'matplotlib.image._ImageBase.set_array', 'matplotlib.image._ImageBase.set_data', 'matplotlib.image._ImageBase.set_filternorm', 'matplotlib.image._ImageBase.set_filterrad', 'matplotlib.image._ImageBase.set_interpolation', 'matplotlib.image._ImageBase.set_interpolation_stage', 'matplotlib.image._ImageBase.set_resample', 'matplotlib.text._AnnotationBase.set_annotation_clip'}

    def pprint_setters(self, prop=None, leadingspace=2):
        if leadingspace:
            pad = ' ' * leadingspace
        else:
            pad = ''
        if prop is not None:
            accepts = self.get_valid_values(prop)
            return f'{pad}{prop}: {accepts}'
        lines = []
        for prop in sorted(self.get_setters()):
            accepts = self.get_valid_values(prop)
            name = self.aliased_name(prop)
            lines.append(f'{pad}{name}: {accepts}')
        return lines

matplotlib.lib.matplotlib.artist.get_valid_values

def get_valid_values(self, attr):
    """
    Get the legal arguments for the setter associated with *attr*.

    This is done by querying the docstring of the setter for a line that
    begins with "ACCEPTS:" or ".. ACCEPTS:", and then by looking for a
    numpydoc-style documentation for the setter's first argument.
    """

    name = 'set_%s' % attr
    if not hasattr(self.o, name):
        raise AttributeError(f'{self.o} has no function {name}')
    func = getattr(self.o, name)

    if hasattr(func, '_kwarg_doc'):
        return func._kwarg_doc

    docstring = inspect.getdoc(func)
    if docstring is None:
        return 'unknown'

    if docstring.startswith('Alias for '):
        return None

    match = self._get_valid_values_regex.search(docstring)
    if match is not None:
        return re.sub("\n *", " ", match.group(1))

    # Much faster than list(inspect.signature(func).parameters)[1],
    # although barely relevant wrt. matplotlib's total import time.
    param_name = func.__code__.co_varnames[1]
    # We could set the presence * based on whether the parameter is a
    # varargs (it can't be a varkwargs) but it's not really worth it.
    match = re.search(fr"(?m)^ *\*?{param_name} : (.+)", docstring)
    if match:
        return match.group(1)

    return 'unknown'

matplotlib.lib.matplotlib.artist.get_setters

def get_setters(self):
    """
    Get the attribute strings with setters for object.

    For example, for a line, return ``['markerfacecolor', 'linewidth',
    ....]``.
    """
    setters = []
    for name in dir(self.o):
        if not name.startswith('set_'):
            continue
        func = getattr(self.o, name)
        if (not callable(func)
                or self.number_of_parameters(func) < 2
                or self.is_alias(func)):
            continue
        setters.append(name[4:])
    return setters

matplotlib.lib.matplotlib.artist.aliased_name

def aliased_name(self, s):
    """
    Return 'PROPNAME or alias' if *s* has an alias, else return 'PROPNAME'.

    For example, for the line markerfacecolor property, which has an
    alias, return 'markerfacecolor or mfc' and for the transform
    property, which does not, return 'transform'.
    """
    aliases = ''.join(' or %s' % x for x in sorted(self.aliasd.get(s, [])))
    return s + aliases

from sympy.functions.elementary.trigonometric import cos, sin, tan, cot, sec, csc, sqrt, TrigonometricFunction

def TR6(rv, max=4, pow=False):
    return _TR56(rv, cos, sin, lambda x: 1 - x, max=max, pow=pow)

sympy.sympy.simplify.fu._TR56

def _TR56(rv, f, g, h, max, pow):
    """Helper for TR5 and TR6 to replace f**2 with h(g**2)

    Options
    =======

    max :   controls size of exponent that can appear on f
            e.g. if max=4 then f**4 will be changed to h(g**2)**2.
    pow :   controls whether the exponent must be a perfect power of 2
            e.g. if pow=True (and max >= 6) then f**6 will not be changed
            but f**8 will be changed to h(g**2)**4

    >>> from sympy.simplify.fu import _TR56 as T
    >>> from sympy.abc import x
    >>> from sympy import sin, cos
    >>> h = lambda x: 1 - x
    >>> T(sin(x)**3, sin, cos, h, 4, False)
    (1 - cos(x)**2)*sin(x)
    >>> T(sin(x)**6, sin, cos, h, 6, False)
    (1 - cos(x)**2)**3
    >>> T(sin(x)**6, sin, cos, h, 6, True)
    sin(x)**6
    >>> T(sin(x)**8, sin, cos, h, 10, True)
    (1 - cos(x)**2)**4
    """

    def _f(rv):
        # I'm not sure if this transformation should target all even powers
        # or only those expressible as powers of 2. Also, should it only
        # make the changes in powers that appear in sums -- making an isolated
        # change is not going to allow a simplification as far as I can tell.
        if not (rv.is_Pow and rv.base.func == f):
            return rv
        if not rv.exp.is_real:
            return rv

        if (rv.exp < 0) == True:
            return rv
        if (rv.exp > max) == True:
            return rv
        if rv.exp == 1:
            return rv
        if rv.exp == 2:
            return h(g(rv.base.args[0])**2)
        else:
            if rv.exp % 2 == 1:
                e = rv.exp//2
                return f(rv.base.args[0])*h(g(rv.base.args[0])**2)**e
            elif rv.exp == 4:
                e = 2
            elif not pow:
                if rv.exp % 2:
                    return rv
                e = rv.exp//2
            else:
                p = perfect_power(rv.exp)
                if not p:
                    return rv
                e = rv.exp//2
            return h(g(rv.base.args[0])**2)**e

    return bottom_up(rv, _f)

from typing import TYPE_CHECKING, ClassVar, overload, Literal
from .singleton import S
from .operations import AssocOp, AssocOpDispatcher
from .logic import fuzzy_not, _fuzzy_group
from .expr import Expr
from .kind import KindDispatcher
from sympy.functions.elementary.complexes import Abs, im, re
from .function import expand_mul

class Mul(Expr, AssocOp):
    __slots__ = ()
    is_Mul = True
    _args_type = Expr
    _kind_dispatcher = KindDispatcher('Mul_kind_dispatcher', commutative=True)
    identity: ClassVar[Expr]
    if TYPE_CHECKING:

        def __new__(cls, *args: Expr | complex, evaluate: bool=True) -> Expr:
            ...

        @property
        def args(self) -> tuple[Expr, ...]:
            ...

    def as_real_imag(self, deep=True, **hints):
        from sympy.functions.elementary.complexes import Abs, im, re
        other = []
        coeffr = []
        coeffi = []
        addterms = S.One
        for a in self.args:
            r, i = a.as_real_imag()
            if i.is_zero:
                coeffr.append(r)
            elif r.is_zero:
                coeffi.append(i * S.ImaginaryUnit)
            elif a.is_commutative:
                aconj = a.conjugate() if other else None
                for i, x in enumerate(other):
                    if x == aconj:
                        coeffr.append(Abs(x) ** 2)
                        del other[i]
                        break
                else:
                    if a.is_Add:
                        addterms *= a
                    else:
                        other.append(a)
            else:
                other.append(a)
        m = self.func(*other)
        if hints.get('ignore') == m:
            return
        if len(coeffi) % 2:
            imco = im(coeffi.pop(0))
        else:
            imco = S.Zero
        reco = self.func(*coeffr + coeffi)
        r, i = (reco * re(m), reco * im(m))
        if addterms == 1:
            if m == 1:
                if imco.is_zero:
                    return (reco, S.Zero)
                else:
                    return (S.Zero, reco * imco)
            if imco is S.Zero:
                return (r, i)
            return (-imco * i, imco * r)
        from .function import expand_mul
        addre, addim = expand_mul(addterms, deep=False).as_real_imag()
        if imco is S.Zero:
            return (r * addre - i * addim, i * addre + r * addim)
        else:
            r, i = (-imco * i, imco * r)
            return (r * addre - i * addim, r * addim + i * addre)
    _eval_is_commutative = lambda self: _fuzzy_group((a.is_commutative for a in self.args))

sympy.sympy.core.add.as_real_imag

def as_real_imag(self, deep=True, **hints):
    """
    Return a tuple representing a complex number.

    Examples
    ========

    >>> from sympy import I
    >>> (7 + 9*I).as_real_imag()
    (7, 9)
    >>> ((1 + I)/(1 - I)).as_real_imag()
    (0, 1)
    >>> ((1 + 2*I)*(1 + 3*I)).as_real_imag()
    (-5, 5)
    """
    sargs = self.args
    re_part, im_part = [], []
    for term in sargs:
        re, im = term.as_real_imag(deep=deep)
        re_part.append(re)
        im_part.append(im)
    return (self.func(*re_part), self.func(*im_part))

sympy.sympy.core.assumptions.getit

def getit(self):
    try:
        return self._assumptions[fact]
    except KeyError:
        if self._assumptions is self.default_assumptions:
            self._assumptions = self.default_assumptions.copy()
        return _ask(fact, self)

sympy.sympy.core.basic.__eq__

def __eq__(self, other):
    """Return a boolean indicating whether a == b on the basis of
    their symbolic trees.

    This is the same as a.compare(b) == 0 but faster.

    Notes
    =====

    If a class that overrides __eq__() needs to retain the
    implementation of __hash__() from a parent class, the
    interpreter must be told this explicitly by setting
    __hash__ : Callable[[object], int] = <ParentClass>.__hash__.
    Otherwise the inheritance of __hash__() will be blocked,
    just as if __hash__ had been explicitly set to None.

    References
    ==========

    from https://docs.python.org/dev/reference/datamodel.html#object.__hash__
    """
    if self is other:
        return True

    if not isinstance(other, Basic):
        return self._do_eq_sympify(other)

    # check for pure number expr
    if  not (self.is_Number and other.is_Number) and (
            type(self) != type(other)):
        return False
    a, b = self._hashable_content(), other._hashable_content()
    if a != b:
        return False
    # check number *in* an expression
    for a, b in zip(a, b):
        if not isinstance(a, Basic):
            continue
        if a.is_Number and type(a) != type(b):
            return False
    return True

sympy.sympy.core.basic.func

@property
def func(self):
    """
    The top-level function in an expression.

    The following should hold for all objects::

        >> x == x.func(*x.args)

    Examples
    ========

    >>> from sympy.abc import x
    >>> a = 2*x
    >>> a.func
    <class 'sympy.core.mul.Mul'>
    >>> a.args
    (2, x)
    >>> a.func(*a.args)
    2*x
    >>> a == a.func(*a.args)
    True

    """
    return self.__class__

sympy.sympy.core.basic.args

@property
def args(self) -> tuple[Basic, ...]:
    """Returns a tuple of arguments of 'self'.

    Examples
    ========

    >>> from sympy import cot
    >>> from sympy.abc import x, y

    >>> cot(x).args
    (x,)

    >>> cot(x).args[0]
    x

    >>> (x*y).args
    (x, y)

    >>> (x*y).args[1]
    y

    Notes
    =====

    Never use self._args, always use self.args.
    Only use _args in __new__ when creating a new function.
    Do not override .args() from Basic (so that it is easy to
    change the interface in the future if needed).
    """
    return self._args

sympy.sympy.core.cache.wrapper

@wraps(func)
def wrapper(*args, **kwargs):
    try:
        retval = cfunc(*args, **kwargs)
    except TypeError as e:
        if not e.args or not e.args[0].startswith('unhashable type:'):
            raise
        retval = func(*args, **kwargs)
    return retval

sympy.sympy.core.decorators._func

@wraps(func)
def _func(self, other):
    # XXX: The check for _op_priority here should be removed. It is
    # needed to stop mutable matrices from being sympified to
    # immutable matrices which breaks things in quantum...
    if not hasattr(other, '_op_priority'):
        try:
            other = sympify(other, strict=True)
        except SympifyError:
            return retval
    if not isinstance(other, expectedcls):
        return retval
    return func(self, other)

sympy.sympy.core.decorators.__sympifyit_wrapper

@wraps(func)
def __sympifyit_wrapper(a, b):
    try:
        # If an external class has _op_priority, it knows how to deal
        # with SymPy objects. Otherwise, it must be converted.
        if not hasattr(b, '_op_priority'):
            b = sympify(b, strict=True)
        return func(a, b)
    except SympifyError:
        return retval

sympy.sympy.core.expr.conjugate

def conjugate(self):
    """Returns the complex conjugate of 'self'."""
    from sympy.functions.elementary.complexes import conjugate as c
    return c(self)

sympy.sympy.core.expr.as_real_imag

def as_real_imag(self, deep=True, **hints) -> tuple[Expr, Expr]:
    """Performs complex expansion on 'self' and returns a tuple
       containing collected both real and imaginary parts. This
       method cannot be confused with re() and im() functions,
       which does not perform complex expansion at evaluation.

       However it is possible to expand both re() and im()
       functions and get exactly the same results as with
       a single call to this function.

       >>> from sympy import symbols, I

       >>> x, y = symbols('x,y', real=True)

       >>> (x + y*I).as_real_imag()
       (x, y)

       >>> from sympy.abc import z, w

       >>> (z + w*I).as_real_imag()
       (re(z) - im(w), re(w) + im(z))

    """
    if hints.get('ignore') == self:
        return None  # type: ignore
    else:
        from sympy.functions.elementary.complexes import im, re
        return (re(self), im(self))

sympy.sympy.core.expr.__neg__

def __neg__(self) -> Expr:
    # Mul has its own __neg__ routine, so we just
    # create a 2-args Mul with the -1 in the canonical
    # slot 0.
    c = self.is_commutative
    return Mul._from_args((S.NegativeOne, self), c)

sympy.sympy.core.expr.__pow__

def __pow__(self, other, mod=None) -> Expr:
    power = self._pow(other)
    if mod is None:
        return power
    else:
        try:
            return power % mod
        except TypeError:
            return NotImplemented

sympy.sympy.core.function.expand_mul

def expand_mul(expr, deep=True):
    """
    Wrapper around expand that only uses the mul hint.  See the expand
    docstring for more information.

    Examples
    ========

    >>> from sympy import symbols, expand_mul, exp, log
    >>> x, y = symbols('x,y', positive=True)
    >>> expand_mul(exp(x+y)*(x+y)*log(x*y**2))
    x*exp(x + y)*log(x*y**2) + y*exp(x + y)*log(x*y**2)

    """
    return sympify(expr).expand(deep=deep, mul=True, power_exp=False,
    power_base=False, basic=False, multinomial=False, log=False)

sympy.sympy.core.mul.__neg__

def __neg__(self):
    c, args = self.as_coeff_mul()
    if args[0] is not S.ComplexInfinity:
        c = -c
    if c is not S.One:
        if args[0].is_Number:
            args = list(args)
            if c is S.NegativeOne:
                args[0] = -args[0]
            else:
                args[0] *= c
        else:
            args = (c,) + args
    return self._from_args(args, self.is_commutative)

sympy.sympy.core.mul.as_real_imag

def as_real_imag(self, deep=True, **hints):
    from sympy.functions.elementary.complexes import Abs, im, re
    other = []
    coeffr = []
    coeffi = []
    addterms = S.One
    for a in self.args:
        r, i = a.as_real_imag()
        if i.is_zero:
            coeffr.append(r)
        elif r.is_zero:
            coeffi.append(i*S.ImaginaryUnit)
        elif a.is_commutative:
            aconj = a.conjugate() if other else None
            # search for complex conjugate pairs:
            for i, x in enumerate(other):
                if x == aconj:
                    coeffr.append(Abs(x)**2)
                    del other[i]
                    break
            else:
                if a.is_Add:
                    addterms *= a
                else:
                    other.append(a)
        else:
            other.append(a)
    m = self.func(*other)
    if hints.get('ignore') == m:
        return
    if len(coeffi) % 2:
        imco = im(coeffi.pop(0))
        # all other pairs make a real factor; they will be
        # put into reco below
    else:
        imco = S.Zero
    reco = self.func(*(coeffr + coeffi))
    r, i = (reco*re(m), reco*im(m))
    if addterms == 1:
        if m == 1:
            if imco.is_zero:
                return (reco, S.Zero)
            else:
                return (S.Zero, reco*imco)
        if imco is S.Zero:
            return (r, i)
        return (-imco*i, imco*r)
    from .function import expand_mul
    addre, addim = expand_mul(addterms, deep=False).as_real_imag()
    if imco is S.Zero:
        return (r*addre - i*addim, i*addre + r*addim)
    else:
        r, i = -imco*i, imco*r
        return (r*addre - i*addim, r*addim + i*addre)

sympy.sympy.core.numbers.__add__

def __add__(self, other):
    if global_parameters.evaluate:
        if isinstance(other, int):
            return Integer(self.p + other)
        elif isinstance(other, Integer):
            return Integer(self.p + other.p)
        elif isinstance(other, Rational):
            return Rational._new(self.p*other.q + other.p, other.q, 1)
        return Rational.__add__(self, other)
    else:
        return Add(self, other)

sympy.sympy.core.numbers.__sub__

def __sub__(self, other):
    if global_parameters.evaluate:
        if isinstance(other, int):
            return Integer(self.p - other)
        elif isinstance(other, Integer):
            return Integer(self.p - other.p)
        elif isinstance(other, Rational):
            return Rational._new(self.p*other.q - other.p, other.q, 1)
        return Rational.__sub__(self, other)
    return Rational.__sub__(self, other)

sympy.sympy.core.numbers.__rsub__

def __rsub__(self, other):
    if global_parameters.evaluate:
        if isinstance(other, int):
            return Integer(other - self.p)
        elif isinstance(other, Rational):
            return Rational._new(other.p - self.p*other.q, other.q, 1)
        return Rational.__rsub__(self, other)
    return Rational.__rsub__(self, other)

sympy.sympy.core.numbers.__mul__

def __mul__(self, other):
    if global_parameters.evaluate:
        if isinstance(other, int):
            return Integer(self.p*other)
        elif isinstance(other, Integer):
            return Integer(self.p*other.p)
        elif isinstance(other, Rational):
            return Rational._new(self.p*other.p, other.q, igcd(self.p, other.q))
        return Rational.__mul__(self, other)
    return Rational.__mul__(self, other)

sympy.sympy.core.numbers.__rmul__

def __rmul__(self, other):
    if global_parameters.evaluate:
        if isinstance(other, int):
            return Integer(other*self.p)
        elif isinstance(other, Rational):
            return Rational._new(other.p*self.p, other.q, igcd(self.p, other.q))
        return Rational.__rmul__(self, other)
    return Rational.__rmul__(self, other)

sympy.sympy.core.numbers.__eq__

def __eq__(self, other):
    if isinstance(other, int):
        return (self.p == other)
    elif isinstance(other, Integer):
        return (self.p == other.p)
    return Rational.__eq__(self, other)

sympy.sympy.core.numbers.__neg__

@staticmethod
def __neg__():
    return S.NegativeOne

sympy.sympy.core.power.as_real_imag

def as_real_imag(self, deep=True, **hints):
    if self.exp.is_Integer:
        from sympy.polys.polytools import poly

        exp = self.exp
        re_e, im_e = self.base.as_real_imag(deep=deep)
        if not im_e:
            return self, S.Zero
        a, b = symbols('a b', cls=Dummy)
        if exp >= 0:
            if re_e.is_Number and im_e.is_Number:
                # We can be more efficient in this case
                expr = expand_multinomial(self.base**exp)
                if expr != self:
                    return expr.as_real_imag()

            expr = poly(
                (a + b)**exp)  # a = re, b = im; expr = (a + b*I)**exp
        else:
            mag = re_e**2 + im_e**2
            re_e, im_e = re_e/mag, -im_e/mag
            if re_e.is_Number and im_e.is_Number:
                # We can be more efficient in this case
                expr = expand_multinomial((re_e + im_e*S.ImaginaryUnit)**-exp)
                if expr != self:
                    return expr.as_real_imag()

            expr = poly((a + b)**-exp)

        # Terms with even b powers will be real
        r = [i for i in expr.terms() if not i[0][1] % 2]
        re_part = Add(*[cc*a**aa*b**bb for (aa, bb), cc in r])
        # Terms with odd b powers will be imaginary
        r = [i for i in expr.terms() if i[0][1] % 4 == 1]
        im_part1 = Add(*[cc*a**aa*b**bb for (aa, bb), cc in r])
        r = [i for i in expr.terms() if i[0][1] % 4 == 3]
        im_part3 = Add(*[cc*a**aa*b**bb for (aa, bb), cc in r])

        return (re_part.subs({a: re_e, b: S.ImaginaryUnit*im_e}),
        im_part1.subs({a: re_e, b: im_e}) + im_part3.subs({a: re_e, b: -im_e}))

    from sympy.functions.elementary.trigonometric import atan2, cos, sin

    if self.exp.is_Rational:
        re_e, im_e = self.base.as_real_imag(deep=deep)

        if im_e.is_zero and self.exp is S.Half:
            if re_e.is_extended_nonnegative:
                return self, S.Zero
            if re_e.is_extended_nonpositive:
                return S.Zero, (-self.base)**self.exp

        # XXX: This is not totally correct since for x**(p/q) with
        #      x being imaginary there are actually q roots, but
        #      only a single one is returned from here.
        r = self.func(self.func(re_e, 2) + self.func(im_e, 2), S.Half)

        t = atan2(im_e, re_e)

        rp, tp = self.func(r, self.exp), t*self.exp

        return rp*cos(tp), rp*sin(tp)
    elif self.base is S.Exp1:
        from sympy.functions.elementary.exponential import exp
        re_e, im_e = self.exp.as_real_imag()
        if deep:
            re_e = re_e.expand(deep, **hints)
            im_e = im_e.expand(deep, **hints)
        c, s = cos(im_e), sin(im_e)
        return exp(re_e)*c, exp(re_e)*s
    else:
        from sympy.functions.elementary.complexes import im, re
        if deep:
            hints['complex'] = False

            expanded = self.expand(deep, **hints)
            if hints.get('ignore') == expanded:
                return None
            else:
                return (re(expanded), im(expanded))
        else:
            return re(self), im(self)

sympy.sympy.core.symbol.as_real_imag

def as_real_imag(self, deep=True, **hints) -> tuple[Expr, Expr]:
    # XXX: Remove the ignore flag
    if hints.get('ignore') == self:
        return None # type: ignore
    else:
        from sympy.functions.elementary.complexes import im, re
        return (re(self), im(self))

sympy.sympy.functions.elementary.complexes.as_real_imag

def as_real_imag(self, deep=True, **hints):
    """
    Return the imaginary part with a zero real part.

    """
    return (self, S.Zero)

sympy.sympy.functions.elementary.exponential.as_real_imag

def as_real_imag(self, deep=True, **hints):
    """
    Returns this function as a complex coordinate.

    Examples
    ========

    >>> from sympy import I, log
    >>> from sympy.abc import x
    >>> log(x).as_real_imag()
    (log(Abs(x)), arg(x))
    >>> log(I).as_real_imag()
    (0, pi/2)
    >>> log(1 + I).as_real_imag()
    (log(sqrt(2)), pi/4)
    >>> log(I*x).as_real_imag()
    (log(Abs(x)), arg(I*x))

    """
    sarg = self.args[0]
    if deep:
        sarg = self.args[0].expand(deep, **hints)
    sarg_abs = Abs(sarg)
    if sarg_abs == sarg:
        return self, S.Zero
    sarg_arg = arg(sarg)
    if hints.get('log', False):  # Expand the log
        hints['complex'] = False
        return (log(sarg_abs).expand(deep, **hints), sarg_arg)
    else:
        return log(sarg_abs), sarg_arg

sympy.sympy.functions.elementary.hyperbolic.as_real_imag

def as_real_imag(self, deep=True, **hints):
    if self.args[0].is_extended_real:
        if deep:
            hints['complex'] = False
            return (self.expand(deep, **hints), S.Zero)
        else:
            return (self, S.Zero)
    if deep:
        re, im = self.args[0].expand(deep, **hints).as_real_imag()
    else:
        re, im = self.args[0].as_real_imag()
    denom = sinh(re)**2 + cos(im)**2
    return (sinh(re)*cosh(re)/denom, sin(im)*cos(im)/denom)

sympy.sympy.functions.elementary.trigonometric.as_real_imag

def as_real_imag(self, deep=True, **hints):
    from sympy.functions.elementary.hyperbolic import cosh, sinh
    re, im = self._as_real_imag(deep=deep, **hints)
    return (cos(re)*cosh(im), -sin(re)*sinh(im))

