    label = map(printer._print, (self.j1, self.j2, self.j12, self.j3,
            self.j4, self.j34, self.j13, self.j24, self.j))
    return r'\left\{\begin{array}{ccc} %s & %s & %s \\ %s & %s & %s \\ %s & %s & %s \end{array}\right\}' % \
        tuple(label)

