sympy.sympy.printing.str._print_MatPow

def _print_MatPow(self, expr):
    PREC = precedence(expr)
    return '%s**%s' % (self.parenthesize(expr.base, PREC, strict=False),
                     self.parenthesize(expr.exp, PREC, strict=False))

