.sympy.core.numbers.Rational.__eq__

def __eq__(self, other):
    try:
        other = _sympify(other)
    except SympifyError:
        return NotImplemented
    if not isinstance(other, Number):
        return False
    if not self:
        return not other
    if other.is_NumberSymbol:
        if other.is_irrational:
            return False
        return other.__eq__(self)
    if other.is_Rational:
        return self.p == other.p and self.q == other.q
    if other.is_Float:
        if self.q & self.q - 1:
            return False
        s, m, t = other._mpf_[:3]
        if s:
            m = -m
        if not t:
            if not self.is_Integer or self.is_even:
                return False
            return m == self.p
        from .power import integer_log
        if t > 0:
            if not self.is_Integer:
                return False
            return self.p and (not self.p % m) and (integer_log(self.p // m, 2) == (t, True))
        if self.is_Integer:
            return False
        return m == self.p and integer_log(self.q, 2) == (-t, True)
    return False

.sympy.core.numbers.Rational.__mul__

def __mul__(self, other):
    if global_parameters.evaluate:
        if isinstance(other, Integer):
            return Rational(self.p * other.p, self.q, igcd(other.p, self.q))
        elif isinstance(other, Rational):
            return Rational(self.p * other.p, self.q * other.q, igcd(self.p, other.q) * igcd(self.q, other.p))
        elif isinstance(other, Float):
            return other * self
        else:
            return Number.__mul__(self, other)
    return Number.__mul__(self, other)

.sympy.core.numbers.Rational.__sub__

def __sub__(self, other):
    if global_parameters.evaluate:
        if isinstance(other, Integer):
            return Rational(self.p - self.q * other.p, self.q, 1)
        elif isinstance(other, Rational):
            return Rational(self.p * other.q - self.q * other.p, self.q * other.q)
        elif isinstance(other, Float):
            return -other + self
        else:
            return Number.__sub__(self, other)
    return Number.__sub__(self, other)

.sympy.geometry.polygon.Polygon.__new__

def __new__(cls, *args, n=0, **kwargs):
    if n:
        args = list(args)
        if len(args) == 2:
            args.append(n)
        elif len(args) == 3:
            args.insert(2, n)
        return RegularPolygon(*args, **kwargs)
    vertices = [Point(a, dim=2, **kwargs) for a in args]
    nodup = []
    for p in vertices:
        if nodup and p == nodup[-1]:
            continue
        nodup.append(p)
    if len(nodup) > 1 and nodup[-1] == nodup[0]:
        nodup.pop()
    i = -3
    while i < len(nodup) - 3 and len(nodup) > 2:
        a, b, c = (nodup[i], nodup[i + 1], nodup[i + 2])
        if Point.is_collinear(a, b, c):
            nodup.pop(i + 1)
            if a == c:
                nodup.pop(i)
        else:
            i += 1
    vertices = list(nodup)
    if len(vertices) > 3:
        return GeometryEntity.__new__(cls, *vertices, **kwargs)
    elif len(vertices) == 3:
        return Triangle(*vertices, **kwargs)
    elif len(vertices) == 2:
        return Segment(*vertices, **kwargs)
    else:
        return Point(*vertices, **kwargs)

.sympy.geometry.point.Point.is_collinear

def is_collinear(self, *args):
    points = (self,) + args
    points = Point._normalize_dimension(*[Point(i) for i in points])
    points = list(uniq(points))
    return Point.affine_rank(*points) <= 1

.sympy.utilities.iterables.uniq

def uniq(seq, result=None):
    try:
        n = len(seq)
    except TypeError:
        n = None

    def check():
        if n is not None and len(seq) != n:
            raise RuntimeError('sequence changed size during iteration')
    try:
        seen = set()
        result = result or []
        for i, s in enumerate(seq):
            if not (s in seen or seen.add(s)):
                yield s
                check()
    except TypeError:
        if s not in result:
            yield s
            check()
            result.append(s)
        if hasattr(seq, '__getitem__'):
            yield from uniq(seq[i + 1:], result)
        else:
            yield from uniq(seq, result)

