.sympy.matrices.matrices.MatrixBase.make_explicit

def make_explicit(x):
    if isinstance(x, BlockMatrix):
        return x.as_explicit()
    elif isinstance(x, MatrixSymbol) and all((_.is_Integer for _ in x.shape)):
        return x.as_explicit()
    else:
