.sympy.polys.matrices.sdm.SDM.convert_to

def convert_to(A, K):
    Kold = A.domain
    if K == Kold:
        return A.copy()
    Ak = unop_dict(A, lambda e: K.convert_from(e, Kold))
    return A.new(Ak, A.shape, K)

