.sympy.polys.matrices.sdm.SDM.getitem

def getitem(self, i, j):
    try:
        return self[i][j]
    except KeyError:
        m, n = self.shape
        if -m <= i < m and -n <= j < n:
            try:
                return self[i % m][j % n]
            except KeyError:
                return self.domain.zero
        else:
            raise IndexError('index out of range')

