.sympy.polys.polytools.Poly.LC

def LC(f, order=None):
    if order is not None:
        return f.coeffs(order)[0]
    if hasattr(f.rep, 'LC'):
        result = f.rep.LC()
    else:
        raise OperationNotSupported(f, 'LC')
    return f.rep.dom.to_sympy(result)

.sympy.polys.polytools.Poly.coeffs

