class Library:

    def __init__(self):
        self.filters = {}
        self.tags = {}

    def tag(self, name=None, compile_function=None):
        if name is None and compile_function is None:
            return self.tag_function
        elif name is not None and compile_function is None:
            if callable(name):
                return self.tag_function(name)
            else:

                def dec(func):
                    return self.tag(name, func)
                return dec
        elif name is not None and compile_function is not None:
            self.tags[name] = compile_function
            return compile_function
        else:
            raise ValueError('Unsupported arguments to Library.tag: (%r, %r)' % (name, compile_function))

    def tag_function(self, func):
        self.tags[getattr(func, '_decorated_function', func).__name__] = func
        return func

    def filter(self, name=None, filter_func=None, **flags):
        if name is None and filter_func is None:

            def dec(func):
                return self.filter_function(func, **flags)
            return dec
        elif name is not None and filter_func is None:
            if callable(name):
                return self.filter_function(name, **flags)
            else:

                def dec(func):
                    return self.filter(name, func, **flags)
                return dec
        elif name is not None and filter_func is not None:
            self.filters[name] = filter_func
            for attr in ('expects_localtime', 'is_safe', 'needs_autoescape'):
                if attr in flags:
                    value = flags[attr]
                    setattr(filter_func, attr, value)
                    if hasattr(filter_func, '_decorated_function'):
                        setattr(filter_func._decorated_function, attr, value)
            filter_func._filter_name = name
            return filter_func
        else:
            raise ValueError('Unsupported arguments to Library.filter: (%r, %r)' % (name, filter_func))

    def filter_function(self, func, **flags):
        name = getattr(func, '_decorated_function', func).__name__
        return self.filter(name, func, **flags)

    def simple_tag(self, func=None, takes_context=None, name=None):

        def dec(func):
            params, varargs, varkw, defaults, kwonly, kwonly_defaults, _ = getfullargspec(unwrap(func))
            function_name = name or getattr(func, '_decorated_function', func).__name__

            @functools.wraps(func)
            def compile_func(parser, token):
                bits = token.split_contents()[1:]
                target_var = None
                if len(bits) >= 2 and bits[-2] == 'as':
                    target_var = bits[-1]
                    bits = bits[:-2]
                args, kwargs = parse_bits(parser, bits, params, varargs, varkw, defaults, kwonly, kwonly_defaults, takes_context, function_name)
                return SimpleNode(func, takes_context, args, kwargs, target_var)
            self.tag(function_name, compile_func)
            return func
        if func is None:
            return dec
        elif callable(func):
            return dec(func)
        else:
            raise ValueError('Invalid arguments provided to simple_tag')

    def inclusion_tag(self, filename, func=None, takes_context=None, name=None):

        def dec(func):
            params, varargs, varkw, defaults, kwonly, kwonly_defaults, _ = getfullargspec(unwrap(func))
            function_name = name or getattr(func, '_decorated_function', func).__name__

            @functools.wraps(func)
            def compile_func(parser, token):
                bits = token.split_contents()[1:]
                args, kwargs = parse_bits(parser, bits, params, varargs, varkw, defaults, kwonly, kwonly_defaults, takes_context, function_name)
                return InclusionNode(func, takes_context, args, kwargs, filename)
            self.tag(function_name, compile_func)
            return func
        return dec

import os
import matplotlib as mpl
from matplotlib import _api, _afm, cbook, ft2font
from matplotlib._fontconfig_pattern import parse_fontconfig_pattern, generate_fontconfig_pattern
from matplotlib.rcsetup import _validators

class FontProperties:

    @_cleanup_fontproperties_init
    def __init__(self, family=None, style=None, variant=None, weight=None, stretch=None, size=None, fname=None, math_fontfamily=None):
        self.set_family(family)
        self.set_style(style)
        self.set_variant(variant)
        self.set_weight(weight)
        self.set_stretch(stretch)
        self.set_file(fname)
        self.set_size(size)
        self.set_math_fontfamily(math_fontfamily)
        if isinstance(family, str) and style is None and (variant is None) and (weight is None) and (stretch is None) and (size is None) and (fname is None):
            self.set_fontconfig_pattern(family)

    def get_fontconfig_pattern(self):
        return generate_fontconfig_pattern(self)

    def set_family(self, family):
        family = mpl._val_or_rc(family, 'font.family')
        if isinstance(family, str):
            family = [family]
        self._family = family

    def set_style(self, style):
        style = mpl._val_or_rc(style, 'font.style')
        _api.check_in_list(['normal', 'italic', 'oblique'], style=style)
        self._slant = style

    def set_variant(self, variant):
        variant = mpl._val_or_rc(variant, 'font.variant')
        _api.check_in_list(['normal', 'small-caps'], variant=variant)
        self._variant = variant

    def set_weight(self, weight):
        weight = mpl._val_or_rc(weight, 'font.weight')
        if weight in weight_dict:
            self._weight = weight
            return
        try:
            weight = int(weight)
        except ValueError:
            pass
        else:
            if 0 <= weight <= 1000:
                self._weight = weight
                return
        raise ValueError(f'weight={weight!r} is invalid')

    def set_stretch(self, stretch):
        stretch = mpl._val_or_rc(stretch, 'font.stretch')
        if stretch in stretch_dict:
            self._stretch = stretch
            return
        try:
            stretch = int(stretch)
        except ValueError:
            pass
        else:
            if 0 <= stretch <= 1000:
                self._stretch = stretch
                return
        raise ValueError(f'stretch={stretch!r} is invalid')

    def set_size(self, size):
        size = mpl._val_or_rc(size, 'font.size')
        try:
            size = float(size)
        except ValueError:
            try:
                scale = font_scalings[size]
            except KeyError as err:
                raise ValueError('Size is invalid. Valid font size are ' + ', '.join(map(str, font_scalings))) from err
            else:
                size = scale * FontManager.get_default_size()
        if size < 1.0:
            _log.info('Fontsize %1.2f < 1.0 pt not allowed by FreeType. Setting fontsize = 1 pt', size)
            size = 1.0
        self._size = size

    def set_file(self, file):
        self._file = os.fspath(file) if file is not None else None

    def set_fontconfig_pattern(self, pattern):
        for key, val in parse_fontconfig_pattern(pattern).items():
            if type(val) is list:
                getattr(self, 'set_' + key)(val[0])
            else:
                getattr(self, 'set_' + key)(val)

    def set_math_fontfamily(self, fontfamily):
        if fontfamily is None:
            fontfamily = mpl.rcParams['mathtext.fontset']
        else:
            valid_fonts = _validators['mathtext.fontset'].valid.values()
            _api.check_in_list(valid_fonts, math_fontfamily=fontfamily)
        self._math_fontfamily = fontfamily
    set_name = set_family
    get_slant = get_style
    set_slant = set_style
    get_size_in_points = get_size

matplotlib.lib.matplotlib._fontconfig_pattern.generate_fontconfig_pattern

def generate_fontconfig_pattern(d):
    """Convert a `.FontProperties` to a fontconfig pattern string."""
    kvs = [(k, getattr(d, f"get_{k}")())
           for k in ["style", "variant", "weight", "stretch", "file", "size"]]
    # Families is given first without a leading keyword.  Other entries (which
    # are necessarily scalar) are given as key=value, skipping Nones.
    return (",".join(_family_escape(f) for f in d.get_family())
            + "".join(f":{k}={_value_escape(str(v))}"
                      for k, v in kvs if v is not None))

