def check_classification_targets(y):
    """Ensure that target y is of a non-regression type.

    Only the following target types (as defined in type_of_target) are allowed:
        'binary', 'multiclass', 'multiclass-multioutput',
        'multilabel-indicator', 'multilabel-sequences'

    Parameters
    ----------
    y : array-like
        Target values.
    """
    y_type = type_of_target(y, input_name="y")
    if y_type not in [
        "binary",
        "multiclass",
        "multiclass-multioutput",
        "multilabel-indicator",
        "multilabel-sequences",
    ]:
        raise ValueError(
            f"Unknown label type: {y_type}. Maybe you are trying to fit a "
            "classifier, which expects discrete classes on a "
            "regression target with continuous values."
        )

    if "multiclass" in y_type:
        n_samples = _num_samples(y)
        if n_samples > 20 and cached_unique(y).shape[0] > round(0.5 * n_samples):
            # Only raise the warning when we have at least 20 samples.
            warnings.warn(
                "The number of unique classes is greater than 50% of the number "
                "of samples. `y` could represent a regression problem, not a "
                "classification problem.",
                UserWarning,
                stacklevel=2,
            )

from .coreerrors import NonCommutativeExpression
from collections import defaultdict
from sympy.polys.polytools import gcd, factor

class Term:
    __slots__ = ('coeff', 'numer', 'denom')

    def __init__(self, term, numer=None, denom=None):
        if numer is None and denom is None:
            if not term.is_commutative:
                raise NonCommutativeExpression('commutative expression expected')
            coeff, factors = term.as_coeff_mul()
            numer, denom = (defaultdict(int), defaultdict(int))
            for factor in factors:
                base, exp = decompose_power(factor)
                if base.is_Add:
                    cont, base = base.primitive()
                    coeff *= cont ** exp
                if exp > 0:
                    numer[base] += exp
                else:
                    denom[base] += -exp
            numer = Factors(numer)
            denom = Factors(denom)
        else:
            coeff = term
            if numer is None:
                numer = Factors()
            if denom is None:
                denom = Factors()
        self.coeff = coeff
        self.numer = numer
        self.denom = denom

    def mul(self, other):
        coeff = self.coeff * other.coeff
        numer = self.numer.mul(other.numer)
        denom = self.denom.mul(other.denom)
        numer, denom = numer.normal(denom)
        return Term(coeff, numer, denom)

