            if base.is_Add:
                cont, base = base.primitive()
                coeff *= cont**exp

            if exp > 0:
                numer[base] += exp
            else:
                denom[base] += -exp

        numer = Factors(numer)
        denom = Factors(denom)
    else:
        coeff = term

        if numer is None:
            numer = Factors()

        if denom is None:
            denom = Factors()

    self.coeff = coeff
    self.numer = numer
    self.denom = denom

