import math
import matplotlib as mpl

class PercentFormatter(Formatter):

    def __init__(self, xmax=100, decimals=None, symbol='%', is_latex=False):
        self.xmax = xmax + 0.0
        self.decimals = decimals
        self._symbol = symbol
        self._is_latex = is_latex

    def format_pct(self, x, display_range):
        x = self.convert_to_pct(x)
        if self.decimals is None:
            scaled_range = self.convert_to_pct(display_range)
            if scaled_range <= 0:
                decimals = 0
            else:
                decimals = math.ceil(2.0 - math.log10(2.0 * scaled_range))
                if decimals > 5:
                    decimals = 5
                elif decimals < 0:
                    decimals = 0
        else:
            decimals = self.decimals
        s = f'{x:0.{int(decimals)}f}'
        return s + self.symbol

    def convert_to_pct(self, x):
        return 100.0 * (x / self.xmax)

    @property
    def symbol(self):
        symbol = self._symbol
        if not symbol:
            symbol = ''
        elif not self._is_latex and mpl.rcParams['text.usetex']:
            for spec in '\\#$%&~_^{}':
                symbol = symbol.replace(spec, '\\' + spec)
        return symbol

    @symbol.setter
    def symbol(self, symbol):
        self._symbol = symbol

matplotlib.lib.matplotlib.ticker.convert_to_pct

def convert_to_pct(self, x):
    return 100.0 * (x / self.xmax)

matplotlib.lib.matplotlib.ticker.symbol

@property
def symbol(self):
    r"""
    The configured percent symbol as a string.

    If LaTeX is enabled via :rc:`text.usetex`, the special characters
    ``{'#', '$', '%', '&', '~', '_', '^', '\', '{', '}'}`` are
    automatically escaped in the string.
    """
    symbol = self._symbol
    if not symbol:
        symbol = ''
    elif not self._is_latex and mpl.rcParams['text.usetex']:
        # Source: http://www.personal.ceu.hu/tex/specchar.htm
        # Backslash must be first for this to work correctly since
        # it keeps getting added in
        for spec in r'\#$%&~_^{}':
            symbol = symbol.replace(spec, '\\' + spec)
    return symbol

