.django.template.base.FilterExpression.__init__

def __init__(self, token, parser):
    self.token = token
    matches = filter_re.finditer(token)
    var_obj = None
    filters = []
    upto = 0
    for match in matches:
        start = match.start()
        if upto != start:
            raise TemplateSyntaxError('Could not parse some characters: %s|%s|%s' % (token[:upto], token[upto:start], token[start:]))
        if var_obj is None:
            var, constant = match.group('var', 'constant')
            if constant:
                try:
                    var_obj = Variable(constant).resolve({})
                except VariableDoesNotExist:
                    var_obj = None
            elif var is None:
                raise TemplateSyntaxError('Could not find variable at start of %s.' % token)
            else:
                var_obj = Variable(var)
        else:
            filter_name = match.group('filter_name')
            args = []
            constant_arg, var_arg = match.group('constant_arg', 'var_arg')
            if constant_arg:
                args.append((False, Variable(constant_arg).resolve({})))
            elif var_arg:
                args.append((True, Variable(var_arg)))
            filter_func = parser.find_filter(filter_name)
            self.args_check(filter_name, filter_func, args)
            filters.append((filter_func, args))
        upto = match.end()
    if upto != len(token):
        raise TemplateSyntaxError("Could not parse the remainder: '%s' from '%s'" % (token[upto:], token))
    self.filters = filters
    self.var = var_obj

.django.template.base.Variable.__init__

def __init__(self, var):
    self.var = var
    self.literal = None
    self.lookups = None
    self.translate = False
    self.message_context = None
    if not isinstance(var, str):
        raise TypeError('Variable must be a string or number, got %s' % type(var))
    try:
        if '.' in var or 'e' in var.lower():
            self.literal = float(var)
            if var.endswith('.'):
                raise ValueError
        else:
            self.literal = int(var)
    except ValueError:
        if var.startswith('_(') and var.endswith(')'):
            self.translate = True
            var = var[2:-1]
        try:
            self.literal = mark_safe(unescape_string_literal(var))
        except ValueError:
            if var.find(VARIABLE_ATTRIBUTE_SEPARATOR + '_') > -1 or var[0] == '_':
                raise TemplateSyntaxError("Variables and attributes may not begin with underscores: '%s'" % var)
            self.lookups = tuple(var.split(VARIABLE_ATTRIBUTE_SEPARATOR))

