def unescape_string_literal(s):
    if s[0] not in '"\'' or s[-1] != s[0]:
        raise ValueError('Not a string literal: %r' % s)
    quote = s[0]
    return s[1:-1].replace('\\%s' % quote, quote).replace('\\\\', '\\')

